const el = (id) => document.getElementById(id);
const cssEscape = (value) => {
  if (window.CSS?.escape) {
    return window.CSS.escape(String(value || ''));
  }
  return String(value || '').replace(/["\\]/g, '\\$&');
};

function escapeHtml(value) {
  return String(value || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function escapeRegExp(value) {
  return String(value || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function normalizeSearchTerms(query) {
  return String(query || '')
    .trim()
    .toLowerCase()
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 12);
}

function highlightSearchSnippet(value, query) {
  let html = escapeHtml(value);
  const terms = normalizeSearchTerms(query)
    .sort((a, b) => b.length - a.length);
  for (const term of terms) {
    const pattern = new RegExp(`(${escapeRegExp(term)})`, 'ig');
    html = html.replace(pattern, '<mark>$1</mark>');
  }
  return html;
}

function highlightTermsInElement(root, query) {
  const terms = normalizeSearchTerms(query)
    .sort((a, b) => b.length - a.length);
  if (!root || !terms.length) {
    return;
  }
  const pattern = new RegExp(`(${terms.map(escapeRegExp).join('|')})`, 'i');
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
    acceptNode(node) {
      const parentName = node.parentElement?.tagName?.toLowerCase() || '';
      if (!node.nodeValue || parentName === 'mark' || parentName === 'script' || parentName === 'style') {
        return NodeFilter.FILTER_REJECT;
      }
      return pattern.test(node.nodeValue) ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_REJECT;
    },
  });
  const nodes = [];
  while (walker.nextNode()) {
    nodes.push(walker.currentNode);
  }
  for (const node of nodes) {
    const fragment = document.createDocumentFragment();
    const parts = String(node.nodeValue || '').split(pattern);
    for (const part of parts) {
      if (!part) {
        continue;
      }
      if (terms.some((term) => part.toLowerCase() === term)) {
        const mark = document.createElement('mark');
        mark.textContent = part;
        fragment.appendChild(mark);
      } else {
        fragment.appendChild(document.createTextNode(part));
      }
    }
    node.parentNode?.replaceChild(fragment, node);
  }
}

function searchTermsMatchText(text, terms) {
  const haystack = String(text || '').toLowerCase();
  return terms.length > 0 && terms.every((term) => haystack.includes(term));
}

function makeClientId() {
  if (window.crypto && typeof window.crypto.randomUUID === 'function') {
    return window.crypto.randomUUID();
  }
  return `${Date.now()}-${Math.random().toString(16).slice(2)}`;
}

function delay(ms) {
  return new Promise((resolve) => {
    window.setTimeout(resolve, ms);
  });
}

function readLocalStorageJson(key, fallback) {
  try {
    const raw = window.localStorage?.getItem(key);
    return raw ? JSON.parse(raw) : fallback;
  } catch (_) {
    return fallback;
  }
}

function writeLocalStorageJson(key, value) {
  try {
    if (!window.localStorage) {
      return false;
    }
    window.localStorage.setItem(key, JSON.stringify(value));
    return true;
  } catch (_) {
    // Local storage may be unavailable in private or restricted browsers.
    return false;
  }
}

function makeApiProfileId() {
  return `api-${makeClientId()}`;
}

const REASONING_EFFORT_PATTERN = /^[a-z][a-z0-9_-]{0,31}$/;

function providerCapabilitiesRegistry() {
  return window.RemoteCodexProviderCapabilities || null;
}

function inferApiProviderKind(input = {}) {
  const registry = providerCapabilitiesRegistry();
  if (registry?.inferProviderKind) {
    return registry.inferProviderKind(input);
  }
  const explicit = String(input?.providerKind || '').trim().toLowerCase();
  if (['openai', 'anthropic', 'gemini', 'custom'].includes(explicit)) {
    return explicit;
  }
  const label = String(input?.provider || input || '').trim().toLowerCase();
  if (label === 'openai') return 'openai';
  if (label === 'anthropic' || label === 'claude') return 'anthropic';
  if (label === 'gemini' || label === 'google gemini') return 'gemini';
  return 'custom';
}

function canonicalProviderLabel(providerKind, customLabel = '') {
  const registry = providerCapabilitiesRegistry();
  const option = registry?.getProviderOption?.(providerKind);
  if (providerKind === 'custom') {
    return String(customLabel || option?.canonicalProvider || 'Custom').trim() || 'Custom';
  }
  return option?.canonicalProvider
    || ({ openai: 'OpenAI', anthropic: 'Anthropic', gemini: 'Gemini' }[providerKind])
    || 'Custom';
}

function normalizeSessionDefaults(input = {}) {
  const source = input && typeof input === 'object' && !Array.isArray(input) ? input : {};
  const effort = String(source.effort || '').trim().toLowerCase();
  const validEffort = REASONING_EFFORT_PATTERN.test(effort) ? effort : '';
  const requestedMode = String(source.effortMode || '').trim().toLowerCase();
  const effortMode = ['auto', 'manual'].includes(requestedMode)
    ? requestedMode
    : validEffort ? 'manual' : 'auto';
  return {
    model: String(source.model || '').trim(),
    effortMode,
    effort: effortMode === 'manual' ? validEffort : '',
    allowUnverifiedEffort: effortMode === 'manual' && Boolean(validEffort) && source.allowUnverifiedEffort === true,
    summary: ['auto', 'concise', 'detailed', 'none'].includes(String(source.summary || '').trim())
      ? String(source.summary || '').trim()
      : '',
  };
}

function formatSessionDefaultsSummary(input = {}) {
  const defaults = normalizeSessionDefaults(input);
  return [
    defaults.model || t('settings.autoModel'),
    defaults.effort ? reasoningEffortLabel(defaults.effort) : t('settings.autoThinking'),
    defaults.summary || t('settings.defaultSummary'),
  ].join(' | ');
}

function normalizeApiProfile(input = {}, index = 0) {
  const fallback = DEFAULT_UI_SETTINGS.apiProfiles[0];
  const profileId = String(input.profileId || input.id || (index === 0 ? fallback.profileId : makeApiProfileId())).trim() || makeApiProfileId();
  const label = String(input.label || input.name || input.provider || (index === 0 ? fallback.label : `API Profile ${index + 1}`)).trim();
  const hasProviderIdentity = Boolean(String(input.providerKind || input.provider || '').trim());
  const providerKind = inferApiProviderKind(hasProviderIdentity ? input : fallback);
  const provider = String(input.provider || '').trim();
  return {
    profileId,
    label: label || `API Profile ${index + 1}`,
    providerKind,
    // provider participates in the API binding fingerprint. Preserve legacy
    // labels during migration; providerKind is capability metadata only.
    provider: provider || canonicalProviderLabel(providerKind),
    baseUrl: String(input.baseUrl || '').trim(),
    apiKey: String(input.apiKey || ''),
    rememberApiKey: input.rememberApiKey !== false || Boolean(input.apiKey),
    sessionDefaults: normalizeSessionDefaults(input.sessionDefaults),
  };
}

function normalizeApiProfiles(input = {}) {
  const rawProfiles = Array.isArray(input.apiProfiles) && input.apiProfiles.length
    ? input.apiProfiles
    : input.apiSettings
      ? [{
        profileId: 'default',
        label: input.apiSettings.provider || input.apiSettings.label || 'OpenAI',
        ...input.apiSettings,
      }]
      : DEFAULT_UI_SETTINGS.apiProfiles;
  const seen = new Set();
  const profiles = [];
  rawProfiles.forEach((profile, index) => {
    const normalized = normalizeApiProfile(profile, index);
    if (seen.has(normalized.profileId)) {
      normalized.profileId = makeApiProfileId();
    }
    seen.add(normalized.profileId);
    profiles.push(normalized);
  });
  return profiles.length ? profiles : DEFAULT_UI_SETTINGS.apiProfiles.map(normalizeApiProfile);
}

function normalizeHostApiProfiles(value = {}, profiles = []) {
  const profileIds = new Set(profiles.map((profile) => profile.profileId));
  const next = {};
  if (!value || typeof value !== 'object') {
    return next;
  }
  for (const [hostId, profileId] of Object.entries(value)) {
    if (profileIds.has(profileId)) {
      next[hostId] = profileId;
    }
  }
  return next;
}

function normalizeUiSettings(input = {}) {
  const locale = input.locale === 'en' ? 'en' : 'zh-CN';
  const theme = input.theme === 'dark-tech' ? 'dark-tech' : 'minimal-light';
  const optimizeSpeedMode = input.optimizeSpeedMode !== false;
  const apiProfiles = normalizeApiProfiles(input);
  const profileIds = new Set(apiProfiles.map((profile) => profile.profileId));
  const fallbackProfileId = apiProfiles[0]?.profileId || 'default';
  const defaultApiProfileId = profileIds.has(input.defaultApiProfileId) ? input.defaultApiProfileId : fallbackProfileId;
  const selectedApiProfileId = profileIds.has(input.selectedApiProfileId) ? input.selectedApiProfileId : defaultApiProfileId;
  return {
    locale,
    theme,
    optimizeSpeedMode,
    apiProfiles,
    selectedApiProfileId,
    defaultApiProfileId,
    hostApiProfiles: normalizeHostApiProfiles(input.hostApiProfiles, apiProfiles),
  };
}

function normalizeDismissedAlerts(input = {}) {
  const result = new Map();
  if (!input || typeof input !== 'object') {
    return result;
  }
  for (const [key, values] of Object.entries(input)) {
    const sessionKey = String(key || '').trim();
    if (!sessionKey || !Array.isArray(values)) {
      continue;
    }
    const fingerprints = values
      .map((value) => String(value || '').trim())
      .filter(Boolean)
      .slice(-300);
    if (fingerprints.length) {
      result.set(sessionKey, new Set(fingerprints));
    }
  }
  return result;
}

function serializeDismissedAlerts() {
  const serialized = {};
  for (const [key, values] of state.dismissedAlerts.entries()) {
    const fingerprints = Array.from(values || []).filter(Boolean).slice(-300);
    if (fingerprints.length) {
      serialized[key] = fingerprints;
    }
  }
  return serialized;
}

function persistDismissedAlerts() {
  writeLocalStorageJson(DISMISSED_ALERTS_STORAGE_KEY, serializeDismissedAlerts());
}

function normalizeManualSessionTitles(input = {}) {
  const result = new Map();
  if (!input || typeof input !== 'object') {
    return result;
  }
  for (const [key, value] of Object.entries(input)) {
    const sessionKey = String(key || '').trim();
    const title = String(value || '').replace(/\s+/g, ' ').trim();
    if (sessionKey && title) {
      result.set(sessionKey, title.slice(0, 180));
    }
  }
  return result;
}

function serializeManualSessionTitles() {
  const serialized = {};
  for (const [key, value] of state.manualSessionTitles.entries()) {
    const title = String(value || '').replace(/\s+/g, ' ').trim();
    if (key && title) {
      serialized[key] = title.slice(0, 180);
    }
  }
  return serialized;
}

function persistManualSessionTitles() {
  writeLocalStorageJson(MANUAL_SESSION_TITLES_STORAGE_KEY, serializeManualSessionTitles());
}

function normalizedBrowserSecretKey(value) {
  return String(value || '').toLowerCase().replace(/[^a-z0-9]+/g, '');
}

function isBrowserSecretQueryKey(value) {
  const key = normalizedBrowserSecretKey(value);
  if (!key || key === 'tokenbudget') {
    return false;
  }
  return key === 'auth'
    || key === 'password'
    || key === 'passwd'
    || key === 'secret'
    || key === 'authorization'
    || key === 'proxyauthorization'
    || key === 'cookie'
    || key === 'setcookie'
    || key === 'accesskey'
    || key === 'secretkey'
    || key === 'accountkey'
    || key === 'storagekey'
    || key === 'encryptionkey'
    || key === 'connectionstring'
    || /^(?:aws)?(?:accesskeyid|secretaccesskey)$/.test(key)
    || /(?:apikey|token|password|passwd|secret|credential|credentials|authorization|privatekey|signingkey|cookie)$/.test(key)
    || key === 'key'
    || key === 'sig'
    || key === 'signature'
    || key === 'code'
    || /key$/.test(key)
    || /signature$/.test(key);
}

function browserSafeUrl(value, maxLength = 600) {
  const raw = String(value || '').trim();
  if (!raw) {
    return null;
  }
  try {
    const url = new URL(raw);
    if (url.username || url.password) {
      return null;
    }
    for (const key of [...url.searchParams.keys()]) {
      if (isBrowserSecretQueryKey(key)) {
        url.searchParams.delete(key);
      }
    }
    url.hash = '';
    return url.toString().slice(0, maxLength) || null;
  } catch (_) {
    return null;
  }
}

function browserSafeApiBinding(value) {
  if (!value || typeof value !== 'object') {
    return null;
  }
  const kind = ['profile', 'host_environment', 'unknown'].includes(String(value.kind || ''))
    ? String(value.kind)
    : 'unknown';
  return {
    kind,
    profileId: kind === 'profile' ? String(value.profileId || '').trim().slice(0, 120) || null : null,
    label: String(value.label || '').trim().slice(0, 120) || null,
    provider: String(value.provider || '').trim().slice(0, 80) || null,
    providerKind: String(value.providerKind || '').trim().toLowerCase().slice(0, 32) || null,
    normalizedBaseUrl: browserSafeUrl(value.normalizedBaseUrl || value.baseUrl, 500),
    modelProviderHint: kind === 'host_environment'
      ? String(value.modelProviderHint || '').trim().slice(0, 120) || null
      : null,
    bindingFingerprint: String(value.bindingFingerprint || '').trim().slice(0, 128) || null,
  };
}

function browserSafeRebindTarget(value) {
  if (!value || typeof value !== 'object') {
    return null;
  }
  return {
    kind: value.kind === 'host_environment' ? 'host_environment' : 'profile',
    profileId: String(value.profileId || '').trim().slice(0, 120) || null,
    label: String(value.label || '').trim().slice(0, 120) || null,
    provider: String(value.provider || '').trim().slice(0, 80) || null,
    providerKind: String(value.providerKind || '').trim().toLowerCase().slice(0, 32) || null,
    baseUrl: browserSafeUrl(value.baseUrl, 500),
    responsesEndpoint: browserSafeUrl(value.responsesEndpoint, 600)
      || (value.kind === 'host_environment' ? 'Host-resolved /responses endpoint' : null),
  };
}

function normalizeSessionRebindFailures(input = {}) {
  const result = new Map();
  if (!input || typeof input !== 'object' || Array.isArray(input)) {
    return result;
  }
  for (const [rawKey, rawValue] of Object.entries(input)) {
    const key = String(rawKey || '').trim();
    const hostId = String(rawValue?.hostId || '').trim().slice(0, 180);
    const sessionId = String(rawValue?.sessionId || '').trim().slice(0, 180);
    const previousBinding = browserSafeApiBinding(rawValue?.previousBinding);
    const target = browserSafeRebindTarget(rawValue?.target);
    if (!key || !hostId || !sessionId || !previousBinding || !target) {
      continue;
    }
    result.set(key, {
      hostId,
      sessionId,
      failedAt: String(rawValue?.failedAt || '').trim().slice(0, 40) || null,
      previousBinding,
      target,
      errorCode: String(rawValue?.errorCode || '').trim().slice(0, 120) || null,
    });
  }
  return result;
}

function persistSessionRebindFailures() {
  const serialized = {};
  for (const [key, value] of state.sessionRebindFailures.entries()) {
    serialized[key] = {
      hostId: value.hostId,
      sessionId: value.sessionId,
      failedAt: value.failedAt || null,
      previousBinding: browserSafeApiBinding(value.previousBinding),
      target: browserSafeRebindTarget(value.target),
      errorCode: value.errorCode || null,
    };
  }
  writeLocalStorageJson(SESSION_REBIND_FAILURES_STORAGE_KEY, serialized);
}

function initializeMessageNotificationState() {
  const client = window.MessageNotificationClient;
  if (!client?.ReceiptStore || !client?.NotificationOutbox) {
    return;
  }
  state.messageNotificationTabId = makeClientId();
  state.messageReceiptStore = new client.ReceiptStore({
    load: () => window.localStorage?.getItem(MESSAGE_READ_RECEIPTS_STORAGE_KEY) || '',
    save: (value) => window.localStorage?.setItem(MESSAGE_READ_RECEIPTS_STORAGE_KEY, value),
    onPersist: () => {
      resetMessageNotificationStoreRetry('receipt');
      broadcastMessageNotificationState('receipts-changed');
    },
    runExclusive: (callback) => runMessageNotificationStorageTransaction(
      MESSAGE_RECEIPT_WRITE_LOCK_NAME,
      callback
    ),
    onLockUnavailable: () => scheduleMessageNotificationStoreRetry('receipt'),
    onPersistError: (error) => {
      if (isMessageNotificationQuotaError(error)) {
        resetMessageNotificationStoreRetry('receipt');
        return;
      }
      reportError(error);
      scheduleMessageNotificationStoreRetry('receipt');
    },
    onPersistenceDisabled: () => resetMessageNotificationStoreRetry('receipt'),
  });
  state.legacyMessageReadReceipts = readLocalStorageJson(
    LEGACY_MESSAGE_READ_RECEIPTS_STORAGE_KEY,
    {}
  ) || {};
  state.messageNotificationOutbox = new client.NotificationOutbox({
    load: () => window.localStorage?.getItem(MESSAGE_NOTIFICATION_OUTBOX_STORAGE_KEY) || '',
    save: (value) => window.localStorage?.setItem(
      MESSAGE_NOTIFICATION_OUTBOX_STORAGE_KEY,
      JSON.stringify(value)
    ),
    clear: () => window.localStorage?.removeItem(MESSAGE_NOTIFICATION_OUTBOX_STORAGE_KEY),
    onPersist: () => {
      resetMessageNotificationStoreRetry('outbox');
      broadcastMessageNotificationState('outbox-changed');
    },
    runExclusive: (callback) => runMessageNotificationStorageTransaction(
      MESSAGE_OUTBOX_WRITE_LOCK_NAME,
      callback
    ),
    onLockUnavailable: () => scheduleMessageNotificationStoreRetry('outbox'),
    onPersistError: (error) => {
      if (isMessageNotificationQuotaError(error)) {
        resetMessageNotificationStoreRetry('outbox');
        return;
      }
      reportError(error);
      scheduleMessageNotificationStoreRetry('outbox');
    },
    onPersistenceDisabled: () => {
      resetMessageNotificationStoreRetry('outbox');
      window.setTimeout(() => void requestMessageNotificationOutboxDrain(), 0);
    },
    onQuotaRecovered: () => {
      window.setTimeout(() => void requestMessageNotificationOutboxDrain(), 0);
    },
  });
  if (typeof window.BroadcastChannel === 'function') {
    state.messageNotificationChannel = new window.BroadcastChannel(MESSAGE_NOTIFICATION_CHANNEL_NAME);
    state.messageNotificationChannel.addEventListener('message', (event) => {
      scheduleMessageNotificationBroadcastFlush(event?.data?.type);
    });
  }
  window.setTimeout(() => void requestMessageNotificationOutboxDrain(), 0);
}

function rememberManualSessionTitle(session, title) {
  const key = getSessionKey(session);
  const normalized = String(title || '').replace(/\s+/g, ' ').trim().slice(0, 180);
  if (!key || !normalized) {
    return;
  }
  state.manualSessionTitles.set(key, normalized);
  persistManualSessionTitles();
}

function applyManualSessionTitle(session) {
  if (!session) {
    return session;
  }
  const title = state.manualSessionTitles.get(getSessionKey(session));
  return title ? { ...session, title, manualTitle: true } : session;
}

function apiProfileModelForStorage(model) {
  const id = String(model?.id || model?.model || '').trim().slice(0, 256);
  if (!id) {
    return null;
  }
  return {
    id,
    displayName: String(model?.displayName || id).trim().slice(0, 256),
    description: String(model?.description || '').trim().slice(0, 240),
    inputModalities: Array.isArray(model?.inputModalities)
      ? model.inputModalities.map((value) => String(value || '').slice(0, 64)).slice(0, 12)
      : [],
    reasoningLevels: Array.isArray(model?.reasoningLevels)
      ? model.reasoningLevels.map((value) => String(value || '').trim().slice(0, 32)).filter(Boolean).slice(0, 24)
      : [],
    capabilityKnown: model?.capabilityKnown === true,
    defaultReasoningEffort: String(model?.defaultReasoningEffort || '').trim().slice(0, 32),
    allowManualEffort: model?.allowManualEffort === true,
    capabilitySource: String(model?.capabilitySource || '').trim().slice(0, 64),
    selectable: model?.selectable !== false,
    availability: String(model?.availability || 'available').trim().slice(0, 32),
    cliSupported: typeof model?.cliSupported === 'boolean' ? model.cliSupported : 'unknown',
    providerAdvertised: typeof model?.providerAdvertised === 'boolean' ? model.providerAdvertised : true,
    visible: model?.visible !== false,
    isDefault: model?.isDefault === true,
    supportsPersonality: model?.supportsPersonality === true,
  };
}

function apiProfileModelCatalogStorageKey(catalogKey) {
  return `stored::${localConfigRevision(String(catalogKey || ''))}`;
}

function apiProfileModelCatalogStorageKeyFromRevision(identityRevision) {
  return `stored::${String(identityRevision || '').trim()}`;
}

function normalizeStoredApiProfileModelCatalogs(input) {
  const catalogs = new Map();
  const entries = Array.isArray(input) ? input : [];
  for (const candidate of entries.slice(-40)) {
    const legacyKey = String(candidate?.key || '').trim();
    const identityRevision = String(
      candidate?.identityRevision || (legacyKey ? localConfigRevision(legacyKey) : '')
    ).trim().slice(0, 128);
    const key = apiProfileModelCatalogStorageKeyFromRevision(identityRevision);
    const profileId = String(candidate?.profileId || '').trim();
    const hostId = String(candidate?.hostId || '').trim();
    if (!/^\d+-[a-f0-9]{32}$/i.test(identityRevision) || !profileId || !hostId || !Array.isArray(candidate?.models)) {
      continue;
    }
    const persistenceTruncated = candidate.persistenceTruncated === true || candidate.models.length > 300;
    const models = candidate.models
      .slice(0, 300)
      .map(apiProfileModelForStorage)
      .filter(Boolean);
    catalogs.set(key, {
      key,
      identityRevision,
      profileId,
      hostId,
      models,
      complete: candidate.complete === true && !persistenceTruncated,
      truncated: candidate.truncated === true || persistenceTruncated,
      persistenceTruncated,
      nextCursor: String(candidate.nextCursor || '').trim() || null,
      fetchedAt: String(candidate.fetchedAt || '').trim() || null,
      restored: true,
    });
  }
  return catalogs;
}

function apiProfileModelCatalogForStorage(catalog) {
  const models = catalog?.models || [];
  const persistenceTruncated = catalog?.persistenceTruncated === true || models.length > 300;
  return {
    identityRevision: catalog?.identityRevision
      || localConfigRevision(String(catalog?.key || '')),
    profileId: catalog?.profileId,
    hostId: catalog?.hostId,
    models: models.slice(0, 300).map(apiProfileModelForStorage).filter(Boolean),
    complete: catalog?.complete === true && !persistenceTruncated,
    truncated: catalog?.truncated === true || persistenceTruncated,
    persistenceTruncated,
    nextCursor: catalog?.nextCursor || null,
    fetchedAt: catalog?.fetchedAt || null,
  };
}

function persistApiProfileModelCatalogs() {
  const profileIds = new Set((state.ui.apiProfiles || []).map((profile) => profile.profileId));
  const latestByScope = new Map();
  for (const catalog of state.apiProfileModelCatalogs.values()) {
    if (profileIds.has(catalog?.profileId) && catalog?.hostId) {
      const scope = `${catalog.profileId}::${catalog.hostId}`;
      latestByScope.delete(scope);
      latestByScope.set(scope, catalog);
    }
  }
  const candidates = [...latestByScope.values()].slice(-12).reverse();
  const entries = [];
  let estimatedBytes = 2;
  let droppedForBudget = false;
  for (const catalog of candidates) {
    const entry = apiProfileModelCatalogForStorage(catalog);
    const entryBytes = JSON.stringify(entry).length * 2 + 2;
    if (estimatedBytes + entryBytes > 1_500_000) {
      droppedForBudget = true;
      continue;
    }
    entries.push(entry);
    estimatedBytes += entryBytes;
  }
  entries.reverse();
  const saved = writeLocalStorageJson(API_PROFILE_MODEL_CATALOGS_STORAGE_KEY, entries);
  state.apiProfileModelCatalogPersistenceError = saved && !droppedForBudget
    ? ''
    : 'The verified catalog is available for this page, but browser storage could not retain every model list.';
  return saved && !droppedForBudget;
}

function initializePersistentUiState() {
  state.navigatorCollapsed = readLocalStorageJson(NAVIGATOR_COLLAPSED_STORAGE_KEY, true) !== false;
  state.dismissedAlerts = normalizeDismissedAlerts(readLocalStorageJson(DISMISSED_ALERTS_STORAGE_KEY, {}));
  state.manualSessionTitles = normalizeManualSessionTitles(readLocalStorageJson(MANUAL_SESSION_TITLES_STORAGE_KEY, {}));
  state.sessionRebindFailures = normalizeSessionRebindFailures(
    readLocalStorageJson(SESSION_REBIND_FAILURES_STORAGE_KEY, {})
  );
  initializeMessageNotificationState();
  const storedUi = normalizeUiSettings(readLocalStorageJson(UI_SETTINGS_STORAGE_KEY, DEFAULT_UI_SETTINGS));
  state.ui.locale = storedUi.locale;
  state.ui.theme = storedUi.theme;
  state.ui.optimizeSpeedMode = storedUi.optimizeSpeedMode;
  state.ui.apiProfiles = storedUi.apiProfiles;
  state.ui.selectedApiProfileId = storedUi.selectedApiProfileId;
  state.ui.defaultApiProfileId = storedUi.defaultApiProfileId;
  state.ui.hostApiProfiles = storedUi.hostApiProfiles;
  state.apiProfileModelCatalogs = normalizeStoredApiProfileModelCatalogs(
    readLocalStorageJson(API_PROFILE_MODEL_CATALOGS_STORAGE_KEY, [])
  );
  persistApiProfileModelCatalogs();
  const storedOptions = readLocalStorageJson(COMPOSER_SESSION_OPTIONS_STORAGE_KEY, {});
  if (storedOptions && typeof storedOptions === 'object') {
    for (const [key, value] of Object.entries(storedOptions)) {
      state.codexControls.sessionOptionsByKey.set(key, normalizeComposerOptionValues(value));
      state.codexControls.persistedSessionOptionKeys.add(key);
    }
  }
}

function uiSettingsStorageValue(input = state.ui) {
  const normalized = normalizeUiSettings(input);
  const apiProfiles = normalized.apiProfiles.map((profile) => ({
    ...profile,
    apiKey: profile.apiKey || '',
    rememberApiKey: Boolean(profile.apiKey || profile.rememberApiKey),
  }));
  return {
    locale: normalized.locale,
    theme: normalized.theme,
    optimizeSpeedMode: normalized.optimizeSpeedMode,
    apiProfiles,
    selectedApiProfileId: normalized.selectedApiProfileId,
    defaultApiProfileId: normalized.defaultApiProfileId,
    hostApiProfiles: normalized.hostApiProfiles,
  };
}

function persistUiSettings() {
  writeLocalStorageJson(UI_SETTINGS_STORAGE_KEY, uiSettingsStorageValue(state.ui));
}

function currentLocale() {
  return state.ui.locale === 'en' ? 'en' : 'zh-CN';
}

function isOptimizeSpeedMode() {
  return state.ui.optimizeSpeedMode !== false;
}

function sessionListQuery(extra = {}) {
  const params = new URLSearchParams(extra);
  if (!isOptimizeSpeedMode()) {
    params.set('full', '1');
  }
  return params.toString();
}

function currentTheme() {
  return state.ui.theme === 'dark-tech' ? 'dark-tech' : 'minimal-light';
}

function applyUiTheme() {
  document.documentElement.dataset.theme = currentTheme();
}

function t(key) {
  return UI_TEXT[currentLocale()]?.[key] || UI_TEXT.en[key] || key;
}

function formatUiText(key, values = {}) {
  return t(key).replace(/\{([A-Za-z0-9_]+)\}/g, (match, name) => (
    Object.prototype.hasOwnProperty.call(values, name) ? String(values[name]) : match
  ));
}

function translateStaticText(value) {
  const text = String(value || '');
  const trimmed = text.trim();
  if (!trimmed) {
    return text;
  }
  const dictionary = currentLocale() === 'zh-CN' ? ZH_STATIC_TEXT : EN_STATIC_TEXT;
  const translated = dictionary[trimmed];
  return translated ? text.replace(trimmed, translated) : text;
}

function shouldSkipLocalizationNode(node) {
  const parent = node?.parentElement || node;
  if (!parent || !(parent instanceof Element)) {
    return false;
  }
  return Boolean(parent.closest('#session-log, .markdown-body, pre, code, script, style'));
}

function applyStaticLocalization(root = document.body) {
  if (!root) {
    return;
  }
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
    acceptNode(node) {
      if (!node.nodeValue?.trim() || shouldSkipLocalizationNode(node)) {
        return NodeFilter.FILTER_REJECT;
      }
      return NodeFilter.FILTER_ACCEPT;
    },
  });
  const textNodes = [];
  while (walker.nextNode()) {
    textNodes.push(walker.currentNode);
  }
  for (const node of textNodes) {
    const translated = translateStaticText(node.nodeValue);
    if (node.nodeValue !== translated) {
      node.nodeValue = translated;
    }
  }

  for (const element of root.querySelectorAll('[placeholder], [aria-label], [title]')) {
    if (shouldSkipLocalizationNode(element)) {
      continue;
    }
    for (const attribute of ['placeholder', 'aria-label', 'title']) {
      if (element.hasAttribute(attribute)) {
        const current = element.getAttribute(attribute);
        const translated = translateStaticText(current);
        if (current !== translated) {
          element.setAttribute(attribute, translated);
        }
      }
    }
  }
}

function optionTreeSignature(specs = []) {
  return JSON.stringify(specs);
}

function createOptionTreeNode(spec = {}) {
  if (Array.isArray(spec.options)) {
    const group = document.createElement('optgroup');
    group.label = String(spec.label || '');
    for (const child of spec.options) {
      group.appendChild(createOptionTreeNode(child));
    }
    return group;
  }
  const option = document.createElement('option');
  option.value = String(spec.value || '');
  option.textContent = String(spec.text || '');
  if (spec.label != null) {
    option.label = String(spec.label);
  }
  option.disabled = spec.disabled === true;
  return option;
}

function syncOptionTree(container, specs = []) {
  if (!container) {
    return false;
  }
  const signature = optionTreeSignature(specs);
  if (container.dataset.optionTreeSignature === signature) {
    return false;
  }
  container.replaceChildren(...specs.map(createOptionTreeNode));
  container.dataset.optionTreeSignature = signature;
  return true;
}

function syncSelectOptions(select, specs = [], selectedValue = select?.value || '') {
  if (!select) {
    return false;
  }
  const changed = syncOptionTree(select, specs);
  const requested = String(selectedValue || '');
  const available = Array.from(select.options || []).some((option) => option.value === requested);
  const nextValue = available ? requested : '';
  if (select.value !== nextValue) {
    select.value = nextValue;
  }
  return changed;
}

function getApiProfiles() {
  const normalized = normalizeUiSettings(state.ui);
  state.ui.apiProfiles = normalized.apiProfiles;
  state.ui.selectedApiProfileId = normalized.selectedApiProfileId;
  state.ui.defaultApiProfileId = normalized.defaultApiProfileId;
  state.ui.hostApiProfiles = normalized.hostApiProfiles;
  return state.ui.apiProfiles;
}

function getApiProfile(profileId) {
  return getApiProfiles().find((profile) => profile.profileId === profileId) || getApiProfiles()[0] || null;
}

function getSelectedApiProfile() {
  return getApiProfile(state.ui.selectedApiProfileId);
}

function getApiProfileForHost(hostId) {
  const hostProfileId = hostId ? state.ui.hostApiProfiles?.[hostId] : '';
  return getApiProfile(hostProfileId || state.ui.defaultApiProfileId);
}

function getApiRequestConfig(hostId = state.selectedHostId) {
  const api = getApiProfileForHost(hostId);
  if (!api) {
    return null;
  }
  const config = {
    provider: api.provider,
    providerKind: api.providerKind,
    baseUrl: api.baseUrl,
    apiKey: api.apiKey,
    profileId: api.profileId,
    label: api.label,
  };
  return config.baseUrl || config.apiKey ? config : null;
}

function apiProfileRequestConfig(profile) {
  if (!profile) {
    return null;
  }
  return {
    provider: profile.provider || '',
    providerKind: profile.providerKind || '',
    baseUrl: profile.baseUrl || '',
    apiKey: profile.apiKey || '',
    profileId: profile.profileId || '',
    label: profile.label || profile.provider || profile.profileId || '',
  };
}

function apiProfileModelHosts() {
  return state.hosts.filter((host) => host.online && host.capabilities?.apiTest);
}

function selectedApiProfileModelHostId(profile = getSelectedApiProfile()) {
  const hosts = apiProfileModelHosts();
  const availableIds = new Set(hosts.map((host) => host.hostId));
  const requested = String(el('settings-api-model-host')?.value || state.apiProfileModelCatalogHostId || '');
  if (availableIds.has(requested)) {
    return requested;
  }
  const mapped = hosts.find((host) => state.ui.hostApiProfiles?.[host.hostId] === profile?.profileId);
  if (mapped) {
    return mapped.hostId;
  }
  if (availableIds.has(state.selectedHostId)) {
    return state.selectedHostId;
  }
  return hosts[0]?.hostId || '';
}

function apiProfileEditorDraft(profile) {
  const selected = getSelectedApiProfile();
  if (!profile || selected?.profileId !== profile.profileId || !el('settings-api-provider-kind')) {
    return profile;
  }
  const providerKind = el('settings-api-provider-kind')?.value
    || profile.providerKind
    || inferApiProviderKind(profile);
  const providerInput = String(el('settings-api-provider')?.value || '').trim();
  return {
    ...profile,
    providerKind,
    provider: providerKind !== 'custom' && providerKind === profile.providerKind && providerInput
      ? providerInput
      : canonicalProviderLabel(providerKind, providerInput),
    baseUrl: String(el('settings-api-base-url')?.value || '').trim(),
    apiKey: String(el('settings-api-key')?.value || ''),
  };
}

function apiProfileModelCatalogKey(profile, hostId = selectedApiProfileModelHostId(profile)) {
  if (!profile || !hostId) {
    return '';
  }
  return apiProfileModelCatalogKeyForConfig(apiProfileEditorDraft(profile), hostId);
}

function apiProfileModelCatalogKeyForConfig(apiConfig, hostId) {
  if (!apiConfig || !hostId) {
    return '';
  }
  return `${encodeURIComponent(hostId)}::${rebindProfilePreviewIdentity(apiConfig)}`;
}

function getApiProfileModelCatalog(profile = getSelectedApiProfile(), hostId = '') {
  const resolvedHostId = hostId || selectedApiProfileModelHostId(profile);
  const key = apiProfileModelCatalogKey(profile, resolvedHostId);
  const catalog = key
    ? state.apiProfileModelCatalogs.get(key)
      || state.apiProfileModelCatalogs.get(apiProfileModelCatalogStorageKey(key))
      || null
    : null;
  return catalog
    && catalog.profileId === profile?.profileId
    && catalog.hostId === resolvedHostId
    ? catalog
    : null;
}

function validatedApiBaseUrlSuggestion(result, currentBaseUrl = '') {
  if (
    !result
    || result.suggestionReason !== 'validated_v1_models'
    || !result.suggestedBaseUrl
  ) {
    return '';
  }
  try {
    const current = new URL(String(currentBaseUrl || '').trim());
    const suggested = new URL(String(result.suggestedBaseUrl || '').trim());
    if (
      !['http:', 'https:'].includes(suggested.protocol)
      || suggested.username
      || suggested.password
      || current.origin !== suggested.origin
    ) {
      return '';
    }
    current.hash = '';
    suggested.hash = '';
    current.searchParams.sort();
    suggested.searchParams.sort();
    const currentPath = current.pathname.replace(/\/+$/, '');
    const suggestedPath = suggested.pathname.replace(/\/+$/, '');
    if (suggestedPath !== `${currentPath}/v1` || current.search !== suggested.search) {
      return '';
    }
    return suggested.toString().replace(/\/+$/, '');
  } catch (_) {
    return '';
  }
}

function clearApiProfileModelState(profileId) {
  const id = String(profileId || '').trim();
  if (!id) {
    return;
  }
  for (const [key, catalog] of state.apiProfileModelCatalogs.entries()) {
    if (String(catalog?.profileId || '') === id) {
      state.apiProfileModelCatalogs.delete(key);
    }
  }
  for (const [key, request] of state.apiProfileModelCatalogRequests.entries()) {
    if (String(request?.profileId || '') === id) {
      state.apiProfileModelCatalogRequests.delete(key);
    }
  }
  for (const [key, catalog] of state.codexControls.modelCatalogByKey.entries()) {
    if (String(catalog?.previewProfileId || '') === id) {
      state.codexControls.modelCatalogByKey.delete(key);
      state.codexControls.modelOptionsErrorsByKey.delete(key);
      state.codexControls.modelOptionsRetryAfterBySession.delete(key);
    }
  }
  persistApiProfileModelCatalogs();
}

function renderApiProfileModelCatalogControls(profile = getSelectedApiProfile()) {
  const select = el('settings-api-model-host');
  const button = el('settings-api-fetch-models-button');
  const suggestionButton = el('settings-api-apply-suggested-base-url-button');
  const status = el('settings-api-model-catalog-status');
  if (!suggestionButton || !status) {
    return;
  }

  const hostId = selectedApiProfileModelHostId(profile);
  const hosts = apiProfileModelHosts();
  const hostOptions = hosts.length
    ? hosts.map((host) => ({
      value: host.hostId,
      text: `${host.label || host.hostId} (${host.hostId})`,
    }))
    : [{ value: '', text: 'No online Host supports API model requests' }];
  if (select) {
    syncSelectOptions(select, hostOptions, hostId);
  }
  state.apiProfileModelCatalogHostId = hostId;

  const key = apiProfileModelCatalogKey(profile, hostId);
  const request = state.apiProfileModelCatalogRequests.get(key) || {};
  const busy = request.busy === true;
  const suggestedBaseUrl = validatedApiBaseUrlSuggestion(request, apiProfileEditorDraft(profile)?.baseUrl);
  const catalog = getApiProfileModelCatalog(profile, hostId);
  if (button) {
    button.disabled = !hostId || busy;
    button.textContent = busy ? 'Fetching...' : catalog ? 'Refresh models' : 'Fetch models';
  }
  suggestionButton.classList.toggle('hidden', !suggestedBaseUrl);
  suggestionButton.disabled = busy || !suggestedBaseUrl;
  suggestionButton.textContent = t('settings.useDetectedV1');
  status.classList.toggle('hidden', !suggestedBaseUrl);
  if (suggestedBaseUrl) {
    status.textContent = formatUiText('settings.detectedV1Status', { baseUrl: suggestedBaseUrl });
  } else {
    status.textContent = '';
  }
}

async function fetchApiProfileModelPages(hostId, apiConfig, options = {}) {
  const limit = Math.max(1, Math.min(500, Number(options.limit || 200) || 200));
  const maxPages = Math.max(1, Math.min(25, Number(options.maxPages || 10) || 10));
  const modelsById = new Map();
  const seenCursors = new Set();
  let cursor = '';
  let complete = false;
  let nextCursor = null;
  let fetchedAt = null;

  for (let pageIndex = 0; pageIndex < maxPages; pageIndex += 1) {
    const response = await fetchJson(`/api/hosts/${encodeURIComponent(hostId)}/api-test`, {
      method: 'POST',
      body: JSON.stringify({
        apiConfig,
        cursor: cursor || undefined,
        limit,
        includeLimit: true,
      }),
    });
    const result = response?.result || null;
    const page = result?.modelPage;
    if (!result?.ok || !page || !Array.isArray(page.models)) {
      const error = new Error(normalizeModelCatalogError(result?.error || result?.message));
      const suggestedBaseUrl = validatedApiBaseUrlSuggestion(result, apiConfig?.baseUrl);
      if (suggestedBaseUrl) {
        error.suggestedBaseUrl = suggestedBaseUrl;
        error.suggestionReason = result.suggestionReason;
      }
      throw error;
    }
    for (const model of page.models) {
      const id = String(model?.id || model?.model || '').trim();
      if (id && !modelsById.has(id)) {
        modelsById.set(id, model);
      }
    }
    fetchedAt = response.timestamp || result.testedAt || fetchedAt || new Date().toISOString();
    nextCursor = String(page.nextCursor || '').trim() || null;
    complete = page.complete === true;
    if (complete || !nextCursor || seenCursors.has(nextCursor)) {
      break;
    }
    seenCursors.add(nextCursor);
    cursor = nextCursor;
  }

  return {
    models: [...modelsById.values()],
    complete,
    truncated: !complete,
    nextCursor: complete ? null : nextCursor,
    fetchedAt,
  };
}

function apiProfileModelRequestIsCurrent(key, hostId) {
  const current = getSelectedApiProfile();
  return Boolean(
    current
    && selectedApiProfileModelHostId(current) === hostId
    && apiProfileModelCatalogKey(current, hostId) === key
  );
}

async function fetchApiProfileModels() {
  const profile = saveActiveApiProfileFromSettingsForm();
  const hostId = selectedApiProfileModelHostId(profile);
  if (!profile) {
    throw new Error('Choose an API profile first.');
  }
  if (!hostId) {
    throw new Error('No online Host can request models for this API profile.');
  }
  const apiConfig = apiProfileRequestConfig(profile);
  if (!apiConfig || (!apiConfig.baseUrl && !apiConfig.apiKey)) {
    throw new Error('Enter a Base URL or API Key before requesting models.');
  }
  validateApiConfigForRequest(apiConfig, hostId);
  const key = apiProfileModelCatalogKeyForConfig(apiConfig, hostId);
  const operationId = makeClientId();
  state.apiProfileModelCatalogRequests.set(key, {
    operationId,
    profileId: profile.profileId,
    hostId,
    busy: true,
    error: '',
  });
  renderApiProviderEditorState(profile);
  try {
    await verifyHostAvailable(hostId);
    const page = await fetchApiProfileModelPages(hostId, apiConfig);
    const registry = providerCapabilitiesRegistry();
    const providerKind = apiConfig.providerKind || inferApiProviderKind(apiConfig);
    const models = registry?.decorateModels?.(providerKind, page.models)
      || page.models.map((model) => ({ ...model, id: String(model?.id || model?.model || '').trim() })).filter((model) => model.id);
    const catalog = {
      key,
      profileId: profile.profileId,
      hostId,
      models,
      complete: page.complete === true,
      truncated: page.truncated === true,
      nextCursor: page.nextCursor || null,
      fetchedAt: page.fetchedAt || new Date().toISOString(),
    };
    const isLatest = state.apiProfileModelCatalogRequests.get(key)?.operationId === operationId;
    if (isLatest) {
      state.apiProfileModelCatalogs.delete(key);
      state.apiProfileModelCatalogs.delete(apiProfileModelCatalogStorageKey(key));
      state.apiProfileModelCatalogs.set(key, catalog);
      persistApiProfileModelCatalogs();
      state.apiProfileModelCatalogRequests.set(key, {
        operationId,
        profileId: profile.profileId,
        hostId,
        busy: false,
        error: '',
      });
    }
    if (isLatest && apiProfileModelRequestIsCurrent(key, hostId)) {
      renderApiProviderEditorState(getSelectedApiProfile());
    }
    return catalog;
  } catch (error) {
    const normalizedError = error instanceof Error ? error : new Error(String(error || ''));
    normalizedError.message = normalizeModelCatalogError(normalizedError.message);
    const isLatest = state.apiProfileModelCatalogRequests.get(key)?.operationId === operationId;
    if (isLatest) {
      state.apiProfileModelCatalogRequests.set(key, {
        operationId,
        profileId: profile.profileId,
        hostId,
        busy: false,
        error: normalizedError.message,
        suggestedBaseUrl: normalizedError.suggestedBaseUrl || '',
        suggestionReason: normalizedError.suggestionReason || '',
      });
    }
    if (isLatest && apiProfileModelRequestIsCurrent(key, hostId)) {
      renderApiProviderEditorState(getSelectedApiProfile());
    }
    throw normalizedError;
  }
}

async function applySuggestedApiProfileBaseUrl() {
  const profile = getSelectedApiProfile();
  const hostId = selectedApiProfileModelHostId(profile);
  const key = apiProfileModelCatalogKey(profile, hostId);
  const request = key ? state.apiProfileModelCatalogRequests.get(key) || null : null;
  const suggestedBaseUrl = validatedApiBaseUrlSuggestion(
    request,
    apiProfileEditorDraft(profile)?.baseUrl
  );
  if (!profile || !hostId || !suggestedBaseUrl) {
    throw new Error('The detected /v1 suggestion is no longer valid. Request models again.');
  }

  el('settings-api-base-url').value = suggestedBaseUrl;
  profile.baseUrl = suggestedBaseUrl;
  clearApiProfileModelState(profile.profileId);
  persistUiSettings();
  renderApiProviderEditorState(profile);
  return fetchApiProfileModels();
}

function normalizeModelCatalogError(value) {
  const fallback = 'The API returned HTTP success but not a recognizable model catalog. Check whether the Base URL needs /v1.';
  const text = String(value == null ? '' : value).replace(/\s+/g, ' ').trim();
  if (!text) {
    return fallback;
  }
  if (/<!doctype\s+html\b/i.test(text) || /<\/?[a-z][^>]*>/i.test(text)) {
    return fallback;
  }
  return text.length <= 400 ? text : `${text.slice(0, 397)}...`;
}

function normalizeApiIdentityBaseUrl(value) {
  const raw = String(value || '').trim();
  if (!raw) {
    return '';
  }
  try {
    const url = new URL(raw);
    url.hash = '';
    url.searchParams.sort();
    url.pathname = url.pathname.replace(/\/+$/, '') || '/';
    return url.toString().replace(/\/$/, '');
  } catch (_) {
    return raw.replace(/\/+$/, '');
  }
}

function effectiveApiBaseUrl(value = {}) {
  const configured = normalizeApiIdentityBaseUrl(value.baseUrl || value.normalizedBaseUrl);
  if (configured) {
    return configured;
  }
  return inferApiProviderKind(value) === 'openai' ? OPENAI_OFFICIAL_BASE_URL : '';
}

function apiBindingMatchesProfileIdentity(binding, profile) {
  if (binding?.kind !== 'profile' || !profile) {
    return false;
  }
  const bindingProfileId = String(binding.profileId || '').trim();
  const profileId = String(profile.profileId || '').trim();
  if (bindingProfileId && bindingProfileId !== profileId) {
    return false;
  }
  const bindingProvider = String(binding.provider || '').trim().toLowerCase();
  const profileProvider = String(profile.provider || 'OpenAI').trim().toLowerCase();
  if (bindingProvider !== profileProvider) {
    return false;
  }
  if (
    binding.providerKind
    && inferApiProviderKind(profile) !== String(binding.providerKind).trim().toLowerCase()
  ) {
    return false;
  }
  return effectiveApiBaseUrl(binding) === effectiveApiBaseUrl(profile);
}

function sessionApiBinding(session) {
  if (session?.runtimeConfig && Object.prototype.hasOwnProperty.call(session.runtimeConfig, 'apiBinding')) {
    return session.runtimeConfig.apiBinding ?? null;
  }
  if (session?.runtimeConfig && Object.prototype.hasOwnProperty.call(session.runtimeConfig, 'sessionBinding')) {
    return session.runtimeConfig.sessionBinding ?? null;
  }
  if (session && Object.prototype.hasOwnProperty.call(session, 'apiBinding')) {
    return session.apiBinding ?? null;
  }
  return session?.sessionRecord?.apiBinding || null;
}

function getBoundApiProfileForSession(session) {
  const binding = sessionApiBinding(session);
  if (binding?.kind !== 'profile') {
    return null;
  }
  return (state.ui.apiProfiles || []).find((profile) => (
    profile.profileId === binding.profileId
    && apiBindingMatchesProfileIdentity(binding, profile)
  )) || null;
}

function sessionApiControlValue(session) {
  const binding = sessionApiBinding(session);
  if (binding?.kind === 'host_environment') {
    return '__host_environment__';
  }
  if (binding?.kind === 'profile' && binding.profileId) {
    return String(binding.profileId);
  }
  return '__unknown_binding__';
}

function preferredHistoryRebindTarget(session) {
  const apiConfig = getApiRequestConfig(session?.hostId);
  return apiConfig?.profileId || '__host_environment__';
}

function hostSupportsSessionApiRebind(session, targetProfileId = '') {
  if (!session?.hostId) {
    return false;
  }
  const capabilities = getHost(session.hostId)?.capabilities || {};
  if (
    capabilities.sessionApiRebindV1 !== true
    || capabilities.runApiBinding !== true
    || capabilities.apiCatalog !== true
  ) {
    return false;
  }
  return targetProfileId !== '__host_environment__'
    || capabilities.bindingPreflight === true;
}

function sessionSupportsTurnSelectionControls(session) {
  if (!session) {
    return false;
  }
  const host = getHost(session.hostId);
  if (host?.capabilities?.turnControls === false) {
    return false;
  }
  if (!session.live) {
    return host?.capabilities?.turnControls !== false;
  }
  const runtime = session.runtime || getRuntimeForSession(session) || {};
  const adapter = String(runtime.adapterId || runtime.runtimeId || runtime.kind || '')
    .trim()
    .toLowerCase()
    .replaceAll('_', '-');
  if (adapter) {
    return adapter === 'codex-app-server';
  }
  return Boolean(
    host?.capabilities?.turnControls === true
    || sessionApiBinding(session)?.bindingFingerprint
  );
}

function sessionContractError(code, message, details = {}) {
  const error = new Error(message);
  error.code = code;
  Object.assign(error, details);
  return error;
}

function resolveApiProfileRequestConfig(profile, binding, hostId) {
  const apiConfig = apiProfileRequestConfig(profile);
  if (!apiConfig?.baseUrl && !apiConfig?.apiKey) {
    throw sessionContractError(
      'session_api_binding_unavailable',
      'The API profile bound to this Session has no saved credentials.',
      { sessionBinding: binding, canRebind: true }
    );
  }
  validateApiConfigForRequest(apiConfig, hostId);
  return apiConfig;
}

function resolveLaunchApiConfig({ hostId, sourceSession = null, explicitProfileId = '' }) {
  if (!sourceSession) {
    const apiConfig = getApiRequestConfig(hostId);
    validateApiConfigForRequest(apiConfig, hostId);
    return { apiConfig, explicitRebind: false };
  }

  const binding = sessionApiBinding(sourceSession);
  if (explicitProfileId) {
    const profile = (state.ui.apiProfiles || []).find((item) => item.profileId === explicitProfileId);
    if (!profile) {
      throw sessionContractError(
        'session_api_binding_unavailable',
        'Selected API profile is unavailable.',
        { sessionBinding: binding, canRebind: true }
      );
    }
    const apiConfig = resolveApiProfileRequestConfig(profile, binding, hostId);
    return { apiConfig, explicitRebind: true };
  }
  if (binding?.kind === 'host_environment') {
    return { apiConfig: null, explicitRebind: false };
  }
  if (binding?.kind !== 'profile') {
    throw sessionContractError(
      'session_api_binding_unavailable',
      'This Session has no verifiable API binding. Choose an API before resuming.',
      { sessionBinding: binding, canRebind: true }
    );
  }
  const profile = (state.ui.apiProfiles || []).find((item) => item.profileId === binding.profileId);
  if (!profile) {
    throw sessionContractError(
      'session_api_binding_unavailable',
      'The API profile bound to this Session was removed.',
      { sessionBinding: binding, canRebind: true }
    );
  }
  const apiConfig = resolveApiProfileRequestConfig(profile, binding, hostId);
  if (!apiBindingMatchesProfileIdentity(binding, profile)) {
    throw sessionContractError(
      'session_api_binding_mismatch',
      'The saved API profile identity changed. Use Session Rebind to change provider or Base URL.',
      {
        sessionBinding: binding,
        submittedBinding: {
          kind: 'profile',
          profileId: profile.profileId || null,
          label: profile.label || null,
          provider: profile.provider || 'OpenAI',
          normalizedBaseUrl: effectiveApiBaseUrl(profile) || null,
        },
        canRebind: true,
      }
    );
  }
  return { apiConfig, explicitRebind: false };
}

function validateApiConfigForRequest(apiConfig, hostId = state.selectedHostId) {
  if (!apiConfig) {
    return;
  }
  if (!apiConfig.baseUrl && inferApiProviderKind(apiConfig) !== 'openai') {
    const profileLabel = apiConfig.label || apiConfig.provider || apiConfig.profileId || 'selected API profile';
    throw new Error(`${profileLabel} requires an explicit Base URL. Only OpenAI profiles can use the official default endpoint.`);
  }
  if (apiConfig.baseUrl && !apiConfig.apiKey) {
    const host = getHost(hostId);
    const profileLabel = apiConfig.label || apiConfig.provider || apiConfig.profileId || 'selected API profile';
    throw new Error(`${profileLabel} for ${host?.label || hostId || 'this host'} has a Base URL but no API key. Add the key in Settings, or clear the host mapping to use the host environment.`);
  }
}

function summarizeApiConfigForDisplay(apiConfig) {
  if (!apiConfig || typeof apiConfig !== 'object' || (!apiConfig.baseUrl && !apiConfig.apiKey)) {
    return null;
  }
  return {
    profileId: apiConfig.profileId || null,
    label: apiConfig.label || apiConfig.provider || 'API profile',
    provider: apiConfig.provider || null,
    baseUrl: apiConfig.baseUrl || null,
  };
}

function getSessionApiProfileSummary(session) {
  if (!session) {
    return {
      label: 'API: none',
      title: 'No API profile recorded for this session.',
      source: 'none',
    };
  }

  const binding = sessionApiBinding(session);
  if (binding?.kind === 'profile') {
    const label = binding.label || binding.profileId || binding.provider || 'API profile';
    const details = [
      binding.provider ? `Provider: ${binding.provider}` : '',
      binding.normalizedBaseUrl || binding.baseUrl
        ? `Base URL: ${binding.normalizedBaseUrl || binding.baseUrl}`
        : '',
      binding.profileId ? `Profile ID: ${binding.profileId}` : '',
    ].filter(Boolean).join('\n');
    return {
      label: `API: ${label}`,
      title: details || 'API identity bound to this Session run.',
      source: 'binding',
    };
  }

  if (binding?.kind === 'host_environment') {
    const label = binding.label || binding.provider || binding.modelProviderHint || 'Host environment';
    const details = [
      binding.provider ? `Provider: ${binding.provider}` : '',
      binding.normalizedBaseUrl || binding.baseUrl
        ? `Base URL: ${binding.normalizedBaseUrl || binding.baseUrl}`
        : '',
      binding.modelProviderHint ? `Model provider: ${binding.modelProviderHint}` : '',
    ].filter(Boolean).join('\n');
    return {
      label: `API: ${label}`,
      title: details || 'API environment attested for this Session run.',
      source: 'binding',
    };
  }

  if (binding?.kind === 'unknown') {
    return {
      label: 'API: unknown',
      title: binding.modelProviderHint
        ? `No verifiable API binding. Model provider hint: ${binding.modelProviderHint}`
        : 'No verifiable API binding is available for this Session.',
      source: 'unknown',
    };
  }

  const runtimeRecorded = session.runtime && (
    session.runtime.apiProfileLabel
    || session.runtime.apiProfileId
    || session.runtime.apiProvider
    || session.runtime.apiBaseUrl
  )
    ? {
      label: session.runtime.apiProfileLabel || session.runtime.apiProfileId || session.runtime.apiProvider || 'API profile',
      profileId: session.runtime.apiProfileId || '',
      provider: session.runtime.apiProvider || '',
      baseUrl: session.runtime.apiBaseUrl || '',
    }
    : null;
  const recorded = session.apiProfile || session.runtime?.apiProfile || null;
  const effectiveRecorded = recorded || runtimeRecorded;
  if (effectiveRecorded?.label || effectiveRecorded?.profileId || effectiveRecorded?.provider || effectiveRecorded?.baseUrl) {
    const label = effectiveRecorded.label || effectiveRecorded.profileId || effectiveRecorded.provider || 'API profile';
    const details = [
      effectiveRecorded.provider ? `Provider: ${effectiveRecorded.provider}` : '',
      effectiveRecorded.baseUrl ? `Base URL: ${effectiveRecorded.baseUrl}` : '',
      effectiveRecorded.profileId ? `Profile ID: ${effectiveRecorded.profileId}` : '',
    ].filter(Boolean).join('\n');
    return {
      label: `API: ${label}`,
      title: details || 'Legacy API profile recorded when this Session started.',
      source: 'legacy-recorded',
    };
  }

  return {
    label: 'API: unknown',
    title: 'No Session API binding has been recorded. The browser Host default applies only to new Sessions.',
    source: 'unknown',
  };
}

async function fetchJson(url, options = {}) {
  const { timeoutMs: requestedTimeoutMs, ...requestOptions } = options;
  const timeoutMs = Math.max(0, Number(requestedTimeoutMs || 0) || 0);
  const controller = timeoutMs > 0 && !requestOptions.signal ? new AbortController() : null;
  let timedOut = false;
  let timeout = null;
  if (controller) {
    requestOptions.signal = controller.signal;
    timeout = window.setTimeout(() => {
      timedOut = true;
      controller.abort();
    }, timeoutMs);
  }

  let response;
  let body;
  try {
    response = await fetch(url, {
      headers: {
        'Content-Type': 'application/json',
        ...(requestOptions.headers || {}),
      },
      ...requestOptions,
    });
    body = await response.json();
  } catch (error) {
    if (timedOut) {
      const timeoutError = new Error(`Request timed out after ${timeoutMs}ms.`);
      timeoutError.code = 'request_timeout';
      timeoutError.url = url;
      throw timeoutError;
    }
    throw error;
  } finally {
    if (timeout !== null) window.clearTimeout(timeout);
  }
  if (!response.ok) {
    const error = new Error(body.error || body.message || `request failed: ${response.status}`);
    error.status = response.status;
    error.body = body;
    error.url = url;
    error.code = body.code || null;
    error.stage = body.stage || null;
    error.sessionBinding = body.sessionBinding || null;
    error.submittedBinding = body.submittedBinding || null;
    error.canRebind = Boolean(body.canRebind);
    error.canTranscriptFallback = Boolean(body.canTranscriptFallback);
    if (response.status === 401 && body?.authRequired && !options.skipAuthHandling) {
      requireRelayLogin(error.message);
    }
    throw error;
  }
  return body;
}

function authAllowsRequests() {
  return !state.auth.required || state.auth.authenticated;
}

function renderAuthGate() {
  const gate = el('auth-gate');
  if (!gate) {
    return;
  }
  const locked = state.auth.required && !state.auth.authenticated;
  gate.classList.toggle('hidden', !locked);
  gate.setAttribute('aria-hidden', locked ? 'false' : 'true');

  const title = el('auth-title');
  if (title) {
    title.textContent = state.auth.setupRequired ? 'Set admin account' : 'Sign in';
  }

  const subtitle = el('auth-subtitle');
  if (subtitle) {
    subtitle.textContent = state.auth.setupRequired
      ? 'Create the browser login. The password is stored as a local scrypt hash, not plaintext.'
      : 'Use your relay account. The recovery token is still available for emergency access.';
  }

  const usernameInput = el('auth-username-input');
  if (usernameInput && document.activeElement !== usernameInput && !usernameInput.value) {
    usernameInput.value = state.auth.username || 'admin';
  }

  el('auth-password-confirm-input')?.classList.toggle('hidden', !state.auth.setupRequired);
  el('auth-recovery-details')?.classList.toggle('hidden', state.auth.setupRequired);

  const hint = el('auth-token-hint');
  if (hint) {
    if (!state.auth.required) {
      hint.textContent = 'Relay auth is disabled.';
    } else if (state.auth.setupRequired) {
      hint.textContent = `Account file: ${state.auth.accountFile || 'tmp/relay-auth-account.json'}. Recovery token: ${state.auth.tokenHint || '(new token)'}.`;
    } else {
      hint.textContent = `Signed account: ${state.auth.username || 'admin'}. Recovery token file: ${state.auth.tokenFile || 'tmp/relay-auth-token.txt'}.`;
    }
  }

  const error = el('auth-error');
  if (error) {
    error.textContent = state.auth.error || '';
  }

  const accountButton = el('account-button');
  if (accountButton) {
    accountButton.hidden = !state.auth.required || !state.auth.authenticated || !state.auth.hasAccount;
  }

  const logoutButton = el('logout-button');
  if (logoutButton) {
    logoutButton.hidden = !state.auth.required || !state.auth.authenticated;
  }

  const accountSection = el('account-settings-section');
  if (accountSection) {
    accountSection.classList.toggle('hidden', !state.auth.required);
  }

  renderAccountDialog();
}

function renderAccountDialog() {
  const dialog = el('account-dialog');
  if (!dialog) {
    return;
  }
  const open = state.auth.accountOpen;
  dialog.classList.toggle('hidden', !open);
  dialog.setAttribute('aria-hidden', open ? 'false' : 'true');
  const usernameInput = el('account-username-input');
  if (usernameInput && open && document.activeElement !== usernameInput && !usernameInput.value) {
    usernameInput.value = state.auth.username || 'admin';
  }
  const error = el('account-error');
  if (error) {
    error.textContent = state.auth.accountError || '';
  }
}

function requireRelayLogin(message = '') {
  state.auth.required = true;
  state.auth.authenticated = false;
  state.auth.error = message || 'Relay login is required.';
  closeStream();
  void releaseSelectedSessionWatchNow();
  closeSkillsInventoryEvents();
  renderAuthGate();
}

function applyAuthConfig(config = {}) {
  state.auth.ready = true;
  state.auth.required = Boolean(config.authRequired);
  state.auth.authenticated = !state.auth.required || Boolean(config.authenticated);
  state.auth.hasAccount = Boolean(config.hasAccount);
  state.auth.setupRequired = Boolean(config.setupRequired);
  state.auth.username = config.username || state.auth.username || '';
  state.auth.tokenHint = config.tokenHint || '';
  state.auth.tokenFile = config.tokenFile || 'tmp/relay-auth-token.txt';
  state.auth.accountFile = config.accountFile || 'tmp/relay-auth-account.json';
  if (!state.auth.authenticated) {
    closeSkillsInventoryEvents();
  }
}

async function refreshAuthState() {
  const config = await fetchJson('/api/auth/config', { skipAuthHandling: true });
  applyAuthConfig(config);
  if (state.auth.authenticated) {
    state.auth.error = '';
  }
  renderAuthGate();
  return state.auth.authenticated;
}

async function setupRelayAccount(username, password, confirmPassword) {
  const response = await fetchJson('/api/auth/setup', {
    method: 'POST',
    body: JSON.stringify({ username, password, confirmPassword }),
    skipAuthHandling: true,
  });
  applyAuthConfig(response);
  state.auth.error = '';
  renderAuthGate();
  await refresh();
}

async function loginRelay(credentials) {
  const response = await fetchJson('/api/auth/login', {
    method: 'POST',
    body: JSON.stringify(credentials),
    skipAuthHandling: true,
  });
  applyAuthConfig(response);
  state.auth.error = '';
  renderAuthGate();
  await refresh();
}

async function changeRelayPassword(payload) {
  const response = await fetchJson('/api/auth/change-password', {
    method: 'POST',
    body: JSON.stringify(payload),
    skipAuthHandling: true,
  });
  applyAuthConfig(response);
  state.auth.accountOpen = false;
  state.auth.accountError = '';
  renderAuthGate();
}

async function logoutRelay() {
  await unwatchSelectedSession({ silent: true }).catch(() => null);
  await fetchJson('/api/auth/logout', {
    method: 'POST',
    body: JSON.stringify({}),
    skipAuthHandling: true,
  }).catch(() => null);
  state.auth.required = true;
  state.auth.authenticated = false;
  state.auth.accountOpen = false;
  state.auth.error = 'Logged out.';
  closeStream();
  closeSkillsInventoryEvents();
  renderAuthGate();
}

function makeSessionKey(hostId, sessionId) {
  return `${hostId}::${sessionId}`;
}

function getSessionKey(session) {
  return session ? makeSessionKey(session.hostId, session.sessionId) : null;
}

function forgetActivityCanonicalConversation(canonicalKey) {
  const normalized = String(canonicalKey || '').trim();
  if (!normalized) {
    return false;
  }
  state.eventCursorByCanonical.delete(normalized);
  for (const [sessionKey, rememberedCanonicalKey] of state.activityCanonicalKeysBySession) {
    if (rememberedCanonicalKey === normalized) {
      state.activityCanonicalKeysBySession.delete(sessionKey);
    }
  }
  return true;
}

function rememberActivityCanonicalAlias(sessionKey, canonicalKey) {
  const key = String(sessionKey || '').trim();
  if (!key) {
    return;
  }
  state.activityCanonicalKeysBySession.delete(key);
  state.activityCanonicalKeysBySession.set(key, canonicalKey);
  while (state.activityCanonicalKeysBySession.size > ACTIVITY_CANONICAL_ALIAS_LIMIT) {
    state.activityCanonicalKeysBySession.delete(
      state.activityCanonicalKeysBySession.keys().next().value
    );
  }
}

function rememberActivityCanonicalKey(canonicalKey, ...identities) {
  const normalized = String(canonicalKey || '').trim();
  if (!normalized) {
    return '';
  }
  for (const identity of identities) {
    const hostId = identity?.hostId;
    for (const sessionId of [
      identity?.sessionId,
      identity?.bridgeSessionId,
      identity?.nativeThreadId,
      identity?.sourceSessionId,
      identity?.originSessionId,
    ]) {
      if (hostId && sessionId) {
        rememberActivityCanonicalAlias(makeSessionKey(hostId, sessionId), normalized);
      }
    }
  }
  return normalized;
}

function getActivityCanonicalKeyForSession(session) {
  if (!session) {
    return '';
  }
  const sessionKey = getSessionKey(session);
  const remembered = state.activityCanonicalKeysBySession.get(sessionKey);
  if (remembered) {
    rememberActivityCanonicalAlias(sessionKey, remembered);
    return remembered;
  }
  const explicit = String(session.canonicalConversationKey || '').trim();
  if (explicit) {
    return rememberActivityCanonicalKey(explicit, session);
  }
  const identity = session.nativeThreadId || session.conversationKey || session.sessionId;
  return session.hostId && identity ? `${session.hostId}::${identity}` : '';
}

function getWatchClientId() {
  if (!state.watchClientId) {
    state.watchClientId = `web-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
  }
  return state.watchClientId;
}

function setHistoryLoading(session, loading) {
  const key = getSessionKey(session);
  if (!key) {
    return;
  }
  if (loading) {
    state.historyLoading.add(key);
  } else {
    state.historyLoading.delete(key);
  }
}

function isHistoryLoading(session) {
  const key = getSessionKey(session);
  return Boolean(key && state.historyLoading.has(key));
}

async function sendSelectedSessionUnwatch(request) {
  const params = new URLSearchParams({
    hostId: request.hostId,
    clientId: request.clientId,
    viewId: request.viewId,
    watchRevision: String(request.watchRevision),
  });
  return fetchJson(`/api/sessions/${encodeURIComponent(request.sessionId)}/watch?${params.toString()}`, {
    method: 'DELETE',
    skipAuthHandling: true,
    keepalive: request.keepalive === true,
  });
}

async function sendSelectedSessionWatch(request) {
  const params = new URLSearchParams({ hostId: request.hostId });
  return fetchJson(`/api/sessions/${encodeURIComponent(request.sessionId)}/watch?${params.toString()}`, {
    method: 'POST',
    skipAuthHandling: true,
    body: JSON.stringify({
      clientId: request.clientId,
      viewId: request.viewId,
      watchRevision: request.watchRevision,
      nativeThreadId: request.nativeThreadId,
      bridgeSessionId: request.bridgeSessionId,
      originSessionId: request.originSessionId,
      sourceSessionId: request.sourceSessionId,
      conversationKey: request.conversationKey,
    }),
  });
}

function getSelectedSessionWatchController() {
  if (!state.sessionWatchController) {
    const createController = window.RemoteCodexSessionWatch?.createSelectedSessionWatchController;
    if (typeof createController !== 'function') {
      throw new Error('Selected Session watch controller is unavailable.');
    }
    state.sessionWatchController = createController({
      clientId: getWatchClientId(),
      viewId: 'primary',
      renewAfterMs: SESSION_WATCH_RENEW_MS,
      sendWatch: sendSelectedSessionWatch,
      sendUnwatch: sendSelectedSessionUnwatch,
      supportsAtomicReplace: (target) => getHost(target.hostId)?.capabilities?.sessionWatchV2 === true,
      onError: (error, target, operation) => appendAlertForSession(target.hostId, target.sessionId, {
        severity: 'warning',
        source: 'ui',
        message: `Realtime watch could not be ${operation === 'unwatch' ? 'stopped' : 'started'}: ${error.message}`,
        timestamp: new Date().toISOString(),
      }),
    });
  }
  return state.sessionWatchController;
}

async function watchSelectedSession(session, options = {}) {
  const key = getSessionKey(session);
  if (!key || key !== getSessionKey(getSelectedSession())) {
    return;
  }
  return getSelectedSessionWatchController().select(session, options);
}

async function unwatchSelectedSession(options = {}) {
  if (!state.sessionWatchController) {
    return;
  }
  return state.sessionWatchController.clear(options);
}

function releaseSelectedSessionWatchNow() {
  return state.sessionWatchController?.releaseNow({ keepalive: true, silent: true }) || Promise.resolve();
}

function maintainSelectedSessionWatch() {
  const selected = getSelectedSession();
  if (!selected?.hostId || !selected?.sessionId) {
    return unwatchSelectedSession({ silent: true });
  }
  return getSelectedSessionWatchController().renewIfDue(selected);
}

function sessionLaunchLabel(mode) {
  if (mode === 'resume') {
    return 'Resuming History...';
  }
  if (mode === 'fork') {
    return 'Forking Branch...';
  }
  return 'Starting Session...';
}

function sessionLaunchIntentKey({ hostId, cwd, launchMode, sourceSession } = {}) {
  const sourceIdentity = sourceSession
    ? String(
      sourceSession.runId
      || sourceSession.activeRunId
      || sourceSession.nativeThreadId
      || sourceSession.sessionId
      || ''
    ).trim()
    : '';
  return JSON.stringify([
    String(hostId || '').trim(),
    normalizeConversationPath(cwd),
    String(launchMode || 'fresh').trim() || 'fresh',
    sourceIdentity,
  ]);
}

function sessionLaunchBusyEntries() {
  if (state.sessionLaunchBusy instanceof Map) {
    return Array.from(state.sessionLaunchBusy.values());
  }
  return state.sessionLaunchBusy ? [state.sessionLaunchBusy] : [];
}

function getSessionLaunchBusyForIntent(intentKey) {
  const key = String(intentKey || '');
  return sessionLaunchBusyEntries().find((busy) => busy?.intentKey === key) || null;
}

function getSessionLaunchBusyForSession(session) {
  if (!session?.hostId) {
    return null;
  }
  const key = getSessionKey(session);
  return sessionLaunchBusyEntries().find((busy) => {
    if (busy.sessionKey && key && busy.sessionKey === key) {
      return true;
    }
    if (busy.hostId !== session.hostId) {
      return false;
    }
    const identities = new Set([
      busy.sessionId,
      busy.sourceSessionId,
      busy.originSessionId,
      busy.nativeThreadId,
      busy.conversationKey,
    ].map((value) => String(value || '').trim()).filter(Boolean));
    return [
      session.sessionId,
      session.bridgeSessionId,
      session.nativeThreadId,
      session.originSessionId,
      session.sourceSessionId,
      session.conversationKey,
    ].some((value) => identities.has(String(value || '').trim()));
  }) || null;
}

function setSessionLaunchBusy(patch) {
  if (!(state.sessionLaunchBusy instanceof Map)) {
    state.sessionLaunchBusy = new Map();
  }
  const next = {
    id: patch.id || makeClientId(),
    startedAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
    ...patch,
  };
  state.sessionLaunchBusy.set(next.intentKey || next.id, next);
  renderAll();
  return next;
}

function updateSessionLaunchBusy(id, patch) {
  const entry = sessionLaunchBusyEntries().find((busy) => busy?.id === id);
  if (!entry || !(state.sessionLaunchBusy instanceof Map)) {
    return;
  }
  state.sessionLaunchBusy.set(entry.intentKey || entry.id, {
    ...entry,
    ...patch,
    updatedAt: new Date().toISOString(),
  });
  renderAll();
}

function clearSessionLaunchBusy(id) {
  const entry = sessionLaunchBusyEntries().find((busy) => busy?.id === id);
  if (!entry || !(state.sessionLaunchBusy instanceof Map)) {
    return;
  }
  state.sessionLaunchBusy.delete(entry.intentKey || entry.id);
  renderAll();
}

function renderNewSessionLaunchState() {
  const cwdInput = el('new-session-cwd');
  const labelInput = el('new-session-label');
  const submitButton = el('new-session-submit-button');
  const browseButton = el('browse-directory-button');
  const usePathButton = el('use-selected-path-button');
  const status = el('new-session-status');
  if (!cwdInput || !submitButton) {
    return;
  }
  const intentKey = sessionLaunchIntentKey({
    hostId: state.selectedHostId,
    cwd: cwdInput.value,
    launchMode: 'fresh',
    sourceSession: null,
  });
  const busy = getSessionLaunchBusyForIntent(intentKey);
  const disabled = Boolean(busy);
  cwdInput.disabled = disabled;
  if (labelInput) labelInput.disabled = disabled;
  if (browseButton) browseButton.disabled = disabled;
  if (usePathButton) usePathButton.disabled = disabled;
  submitButton.disabled = disabled;
  submitButton.textContent = disabled ? 'Creating Session...' : 'New In Directory';
  if (status) {
    status.textContent = disabled
      ? 'A Session is already being created for this Host and path. Please wait.'
      : '';
    status.classList.toggle('hidden', !disabled);
  }
}

function parseSessionTime(session) {
  const value = Date.parse(session?.lastUpdatedAt || session?.updatedAt || 0);
  return Number.isFinite(value) ? value : 0;
}

function parseCreatedTime(session) {
  const value = Date.parse(session?.createdAt || session?.summary?.timestamp || '');
  return Number.isFinite(value) ? value : 0;
}

function getSessionMessageCount(session) {
  const explicit = Number(session?.messageCount || 0);
  if (explicit > 0) {
    return explicit;
  }
  const previewCount = Array.isArray(session?.transcriptPreview) ? session.transcriptPreview.length : 0;
  const liveCount = state.transcripts.get(makeSessionKey(session?.hostId, session?.sessionId))?.length || 0;
  return Math.max(previewCount, liveCount);
}

function compareSessions(a, b) {
  if (a.live !== b.live) {
    return a.live ? -1 : 1;
  }
  const delta = parseSessionTime(b) - parseSessionTime(a);
  if (delta !== 0) {
    return delta;
  }
  return String(a.title || a.sessionId).localeCompare(String(b.title || b.sessionId));
}

function truncatePreview(value) {
  return String(value || '').replace(/\s+/g, ' ').trim().slice(0, 160);
}

function basename(value) {
  const text = String(value || '');
  if (!text) {
    return '';
  }
  const parts = text.split(/[\\/]/).filter(Boolean);
  return parts[parts.length - 1] || text;
}

function formatTime(value) {
  if (!value) {
    return '';
  }

  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    return '';
  }

  return date.toLocaleString([], {
    month: 'short',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  });
}

function formatDuration(value) {
  const ms = Number(value);
  if (!Number.isFinite(ms) || ms < 0) {
    return '';
  }

  const totalSeconds = Math.max(0, Math.floor(ms / 1000));
  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;

  if (hours > 0) {
    return `${hours}h ${String(minutes).padStart(2, '0')}m`;
  }

  if (minutes > 0) {
    return `${minutes}m ${String(seconds).padStart(2, '0')}s`;
  }

  return `${seconds}s`;
}

function formatElapsedSince(value, now = Date.now()) {
  const timestamp = Date.parse(value || '');
  if (!Number.isFinite(timestamp)) {
    return '';
  }

  return formatDuration(now - timestamp);
}

function prettyStatusLabel(value) {
  const text = String(value || '').trim();
  if (!text) {
    return '';
  }

  const map = {
    idle: 'Idle',
    active: 'Thinking',
    thinking: 'Thinking',
    planning: 'Planning',
    reviewing: 'Reviewing',
    'queued-turn': 'Queued',
    'submitting-turn': 'Submitting',
    reconnecting: 'Reconnecting',
    retrying: 'Retrying',
    interrupted: 'Interrupted',
    error: 'Error',
    closed: 'Closed',
    booting: 'Booting',
    'waiting-approval': 'Waiting Approval',
    'waiting-user-input': 'Waiting Input',
    'running-shell-command': 'Running Shell Command',
    compacting: 'Compacting',
    'quota-exhausted': 'Quota Exhausted',
  };

  if (map[text]) {
    return map[text];
  }

  return text
    .replace(/[-_]+/g, ' ')
    .replace(/\b\w/g, (char) => char.toUpperCase());
}

function connectorKindLabel(value) {
  return {
    outbound_agent: 'Outbound Agent',
    ssh_jump: 'SSH Jump',
    gateway_agent: 'Gateway Sidecar',
    reverse_tunnel: 'Reverse Tunnel',
    manual_only: 'Manual Only',
  }[value] || 'Connector';
}

function authMethodLabel(value) {
  return {
    ssh_key: 'SSH Key',
    ssh_agent: 'SSH Agent',
    password: 'Password',
    keyboard_interactive: 'Keyboard-Interactive',
    otp: 'OTP / MFA',
    browser_sso: 'Browser SSO',
    manual_captcha: 'Manual Captcha',
  }[value] || 'Auth';
}

function bootstrapModeLabel(value) {
  return {
    manual_tmux: 'Manual + tmux',
    manual_systemd: 'Manual + systemd',
    ssh_exec: 'SSH Exec',
    gateway_launcher: 'Gateway Launcher',
    manual_only: 'Manual Only',
  }[value] || 'Bootstrap';
}

function describeRuntimeStatus(runtime, stream, session) {
  const connection = stream?.connection || runtime?.connection || (session?.live ? 'connecting' : 'history only');
  const phase = prettyStatusLabel(runtime?.phase || session?.state || 'unknown');
  const turn = runtime?.currentTurnStatus ? prettyStatusLabel(runtime.currentTurnStatus) : (runtimeIsActive(runtime) ? 'Active' : 'Idle');
  const busy = runtime?.busy ? 'Busy' : 'Idle';
  return {
    connection,
    phase,
    turn,
    busy,
  };
}

function getRuntimeElapsedAnchor(runtime) {
  return runtime?.busy && runtime?.busyStartedAt
    ? runtime.busyStartedAt
    : runtime?.phaseStartedAt || runtime?.updatedAt || null;
}

function getStreamElapsedAnchor(stream) {
  return stream?.connectionChangedAt || stream?.lastPingAt || null;
}

function limitText(value, max = 220) {
  const text = String(value || '');
  if (text.length <= max) {
    return text;
  }
  return `${text.slice(0, Math.max(0, max - 3))}...`;
}

function limitSearchText(value, max = 1000) {
  return isOptimizeSpeedMode() ? limitText(value, max) : String(value || '');
}

function summarizeData(value) {
  if (value === null || typeof value === 'undefined') {
    return '';
  }
  if (typeof value === 'string') {
    return limitText(value, 220);
  }
  try {
    return limitText(JSON.stringify(value), 320);
  } catch (_) {
    return limitText(String(value), 220);
  }
}

function formatThinkingValue(value, depth = 0) {
  if (value === null || typeof value === 'undefined') {
    return '';
  }

  if (typeof value === 'string') {
    return value.trim();
  }

  if (typeof value === 'number' || typeof value === 'boolean') {
    return String(value);
  }

  if (Array.isArray(value)) {
    return joinThinkingTextParts(value
      .map((item) => (typeof item === 'string' ? item : formatThinkingValue(item, depth + 1)))
      .filter(Boolean));
  }

  if (typeof value === 'object') {
    if (typeof value.step === 'string' && value.step.trim()) {
      const status = typeof value.status === 'string' && value.status.trim()
        ? `[${value.status.trim()}] `
        : '';
      const extra = typeof value.summary === 'string' && value.summary.trim() && value.summary.trim() !== value.step.trim()
        ? ` - ${value.summary.trim()}`
        : '';
      return `${status}${value.step.trim()}${extra}`.trim();
    }

    for (const key of ['text', 'content', 'summary', 'description', 'title', 'label']) {
      if (typeof value[key] === 'string' && value[key].trim()) {
        return value[key].trim();
      }
    }

    if (depth > 1) {
      return summarizeData(value);
    }

    return Object.entries(value)
      .map(([key, item]) => {
        const normalized = formatThinkingValue(item, depth + 1);
        return normalized ? `${key}: ${normalized}` : '';
      })
      .filter(Boolean)
      .join('\n')
      .trim();
  }

  return String(value).trim();
}

function joinThinkingTextParts(parts) {
  const rawValues = (Array.isArray(parts) ? parts : [])
    .map((part) => String(part || ''))
    .filter((part) => part.trim());
  if (!rawValues.length) {
    return '';
  }
  if (rawValues.some((part) => /\r?\n/.test(part))) {
    return rawValues.map((part) => part.trim()).join('\n').trim();
  }
  if (rawValues.some((part) => /^\s|\s$/.test(part))) {
    return rawValues.join('').trim();
  }
  const values = rawValues.map((part) => part.trim());
  const cjkOnly = values.every((part) => !/[A-Za-z0-9]/.test(part))
    && values.some((part) => /[\u3400-\u9fff\uf900-\ufaff]/.test(part));
  if (cjkOnly) return values.join('');
  return values.join(' ')
    .replace(/\s+([,.!?;:，。！？；：])/g, '$1')
    .replace(/([([{])\s+/g, '$1')
    .trim();
}

function normalizeThinkingMessage(entry) {
  if (!entry) {
    return '';
  }

  const kind = String(entry.kind || '').toLowerCase();
  if (kind === 'token-usage') {
    const usage = entry.data?.tokenUsage || entry.data || null;
    const text = usage ? formatTokenUsage({ tokenUsage: usage }) : '';
    if (text && !/No token usage/i.test(text)) {
      return text;
    }
  }
  if (kind === 'rate-limits') {
    const limits = entry.data?.rateLimits || entry.data || null;
    const text = limits ? formatRateLimits({ rateLimits: limits }) : '';
    if (text && !/No rate limit/i.test(text)) {
      return text;
    }
  }

  const candidates = [
    entry.data?.text,
    entry.data?.content,
    entry.data?.summary,
    entry.data?.plan,
    entry.data?.delta,
    entry.data?.rawPlan,
    entry.message,
    entry.detail,
    entry.data?.command,
    entry.data?.query,
    entry.data?.output,
    entry.data?.stdin,
    entry.data?.arguments?.command,
    entry.data?.arguments?.path,
    entry.data?.arguments?.target,
  ];

  for (const candidate of candidates) {
    const text = formatThinkingValue(candidate);
    if (text) {
      return text;
    }
  }

  return '';
}

function subagentActivityItem(entry) {
  const candidates = [entry?.data?.item, entry?.payload?.item, entry?.item];
  return candidates.find((item) => (
    item
    && typeof item === 'object'
    && String(item.type || '').trim() === 'subAgentActivity'
  )) || null;
}

function isThinkingActivityDiagnostic(entry) {
  if (!entry) {
    return false;
  }
  if (isFileChangeDiagnostic(entry)) {
    return true;
  }

  const kind = String(entry.kind || '').toLowerCase();
  const method = String(entry.method || '').toLowerCase();
  if (subagentActivityItem(entry)) {
    return true;
  }
  return [
    'reasoning',
    'plan',
    'tool-call',
    'mcp-tool-call',
    'dynamic-tool-call',
    'collab-agent-tool-call',
    'collaboration',
    'subagent',
    'command-output',
    'terminal',
    'web-search',
    'approval',
    'permissions',
    'user-input',
    'commentary',
  ].includes(kind)
    || method.includes('commandexecution')
    || method.includes('function_call')
    || /item\/(?:filechange|mcptoolcall|dynamictoolcall|collabagenttoolcall)/.test(method)
    || method.includes('subagentactivity')
    || method.includes('web_search')
    || method.includes('websearch');
}

function requestToThinkingDiagnostic(request) {
  if (!request) {
    return null;
  }
  const method = request.method || '';
  let kind = request.kind || 'request';
  if (isFileChangeDiagnostic({ kind, method, message: request.summary || request.message || '' })) {
    kind = 'file-change';
  } else if (kind === 'request') {
    kind = method.includes('requestUserInput') ? 'user-input' : 'approval';
  }
  return {
    timestamp: request.createdAt || request.updatedAt || new Date().toISOString(),
    severity: request.status === 'pending' ? 'warning' : 'info',
    source: 'codex',
    kind,
    method: method || 'request',
    message: request.summary || request.message || request.title || 'Codex requested user action',
    data: request.payload || null,
    turnId: request.payload?.turnId || null,
    itemId: request.payload?.itemId || null,
    callId: request.payload?.callId || null,
    requestId: request.requestId || null,
    status: request.status || 'pending',
    final: request.status !== 'pending',
  };
}

function getThinkingDiagnosticsForSession(session) {
  if (!session) {
    return [];
  }
  const diagnostics = getDiagnosticsForSession(session)
    .filter(isThinkingActivityDiagnostic);
  const requestDiagnostics = getRequestsForSession(session)
    .map(requestToThinkingDiagnostic)
    .filter(Boolean)
    .filter(isThinkingActivityDiagnostic);
  return [...diagnostics, ...requestDiagnostics];
}

function firstThinkingField(entry, ...names) {
  const roots = [
    entry,
    entry?.data,
    entry?.payload,
    entry?.data?.payload,
    entry?.data?.item,
    entry?.item,
  ];
  for (const root of roots) {
    if (!root || typeof root !== 'object') continue;
    for (const name of names) {
      if (root[name] !== null && typeof root[name] !== 'undefined' && root[name] !== '') {
        return root[name];
      }
    }
  }
  return null;
}

function normalizeThinkingActivityForModel(entry, index = 0) {
  if (!entry) return null;
  const subagentItem = subagentActivityItem(entry);
  const itemTypeHint = String(firstThinkingField(entry, 'itemType', 'item_type', 'type') || '').trim().toLowerCase();
  const subagent = subagentItem || itemTypeHint === 'subagentactivity';
  const kind = isFileChangeDiagnostic(entry)
    ? 'file-change'
    : subagent
      ? 'collaboration'
      : String(entry.kind || 'thinking');
  const method = String(entry.method || firstThinkingField(entry, 'method') || '');
  const deltaLike = /delta/i.test(method);
  const rawDelta = deltaLike
    ? (entry.delta ?? entry.data?.delta ?? entry.data?.text ?? entry.payload?.delta ?? entry.message)
    : null;
  const subagentKind = firstThinkingField(entry, 'subagentKind', 'subagent_kind')
    || subagentItem?.kind
    || subagentItem?.status
    || null;
  const subagentPath = firstThinkingField(entry, 'agentPath', 'agent_path') || subagentItem?.agentPath || subagentItem?.agent_path || null;
  const subagentNickname = firstThinkingField(entry, 'agentNickname', 'agent_nickname') || subagentItem?.agentNickname || subagentItem?.agent_nickname || null;
  const subagentThreadId = firstThinkingField(entry, 'agentThreadId', 'agent_thread_id') || subagentItem?.agentThreadId || subagentItem?.agent_thread_id || null;
  const parentThreadId = firstThinkingField(entry, 'parentThreadId', 'parent_thread_id')
    || entry.data?.threadId
    || entry.data?.thread_id
    || null;
  const text = subagent
    ? `Sub-agent ${subagentPath || subagentNickname || subagentThreadId || 'sub-agent'}: ${subagentKind || 'activity'}`
    : deltaLike && typeof rawDelta === 'string'
    ? rawDelta
    : normalizeThinkingMessage(entry);
  const fileChanges = normalizeFileChanges(entry);
  const argumentsValue = firstThinkingField(entry, 'arguments', 'args');
  const resultValue = firstThinkingField(entry, 'result');
  const argumentsTruncated = firstThinkingField(entry, 'argumentsTruncated') === true
    || thinkingStructuredValueWasTruncated(argumentsValue);
  const resultTruncated = firstThinkingField(entry, 'resultTruncated') === true
    || thinkingStructuredValueWasTruncated(resultValue);
  if (!text && !fileChanges.length && !firstThinkingField(entry, 'command', 'query', 'tool', 'name')) {
    return null;
  }
  if (text && !deltaLike && !subagent && !isUserSuitableThinkingText(text, entry)) {
    return null;
  }
  const normalizedSubagentStatus = subagent
    ? String(subagentKind || 'running').trim()
    : firstThinkingField(entry, 'status');
  const normalized = {
    activityKey: firstThinkingField(entry, 'activityKey'),
    activityRevision: firstThinkingField(entry, 'activityRevision', 'revision'),
    canonicalConversationKey: firstThinkingField(entry, 'canonicalConversationKey'),
    runId: firstThinkingField(entry, 'runId'),
    turnId: firstThinkingField(entry, 'turnId', 'turn_id'),
    itemId: firstThinkingField(entry, 'itemId', 'item_id', 'id'),
    callId: firstThinkingField(entry, 'callId', 'call_id'),
    requestId: firstThinkingField(entry, 'requestId', 'request_id'),
    processId: firstThinkingField(entry, 'processId', 'process_id', 'processHandle'),
    summaryIndex: firstThinkingField(entry, 'summaryIndex', 'summary_index') || 0,
    kind,
    itemType: firstThinkingField(entry, 'itemType', 'type') || (subagent ? 'subAgentActivity' : null),
    method,
    name: firstThinkingField(entry, 'name'),
    status: normalizedSubagentStatus,
    text: text || (fileChanges.length ? 'File changes updated' : ''),
    textTruncated: firstThinkingField(entry, 'textTruncated') === true,
    command: firstThinkingField(entry, 'command', 'cmd'),
    cwd: firstThinkingField(entry, 'cwd', 'workdir', 'workingDirectory'),
    output: firstThinkingField(entry, 'output', 'aggregatedOutput', 'delta'),
    outputTruncated: firstThinkingField(entry, 'outputTruncated') === true,
    stdout: firstThinkingField(entry, 'stdout'),
    stderr: firstThinkingField(entry, 'stderr'),
    stream: firstThinkingField(entry, 'stream'),
    exitCode: firstThinkingField(entry, 'exitCode', 'exit_code'),
    durationMs: firstThinkingField(entry, 'durationMs', 'duration_ms'),
    server: firstThinkingField(entry, 'server'),
    tool: firstThinkingField(entry, 'tool', 'name'),
    namespace: firstThinkingField(entry, 'namespace'),
    resourceUri: firstThinkingField(entry, 'resourceUri'),
    senderThreadId: firstThinkingField(entry, 'senderThreadId') || parentThreadId,
    receiverThreadIds: firstThinkingField(entry, 'receiverThreadIds') || (subagentThreadId ? [subagentThreadId] : null),
    agentThreadId: subagentThreadId,
    agentPath: subagentPath,
    agentNickname: subagentNickname,
    agentRole: firstThinkingField(entry, 'agentRole', 'agent_role') || subagentItem?.agentRole || subagentItem?.agent_role || null,
    parentThreadId,
    subagentKind,
    prompt: firstThinkingField(entry, 'prompt'),
    agentsStates: firstThinkingField(entry, 'agentsStates'),
    model: firstThinkingField(entry, 'model'),
    reasoningEffort: firstThinkingField(entry, 'reasoningEffort'),
    arguments: argumentsValue,
    argumentsTruncated,
    result: resultValue,
    resultTruncated,
    error: firstThinkingField(entry, 'error'),
    progress: firstThinkingField(entry, 'progress'),
    progressTruncated: firstThinkingField(entry, 'progressTruncated') === true,
    query: firstThinkingField(entry, 'query'),
    action: firstThinkingField(entry, 'action'),
    actionData: firstThinkingField(entry, 'actionData'),
    commandActions: firstThinkingField(entry, 'commandActions', 'command_actions'),
    fileChanges,
    fileChangesTruncated: firstThinkingField(entry, 'fileChangesTruncated') === true,
    final: entry.final === true
      || (subagent && /item\/completed$/i.test(method))
      || /(?:completed|failed|cancelled|canceled|interrupted)$/.test(String(normalizedSubagentStatus || '').toLowerCase()),
    success: firstThinkingField(entry, 'success'),
    timestamp: entry.timestamp || firstThinkingField(entry, 'createdAt', 'startedAt') || null,
    updatedAt: firstThinkingField(entry, 'updatedAt', 'completedAt') || entry.timestamp || null,
    source: entry.source || null,
  };
  return window.RemoteCodexThinkingEntryModel?.normalizeThinkingActivityEntry
    ? window.RemoteCodexThinkingEntryModel.normalizeThinkingActivityEntry(normalized, index)
    : normalized;
}

function aggregateThinkingActivityEntries(entries) {
  const normalized = (Array.isArray(entries) ? entries : []).filter(Boolean);
  if (!window.RemoteCodexThinkingEntryModel?.aggregateThinkingEntries) {
    return normalized;
  }
  return window.RemoteCodexThinkingEntryModel.aggregateThinkingEntries(normalized, {
    maxEntries: LIVE_THINKING_ACTIVITY_ENTRY_LIMIT,
  });
}

function buildThinkingActivityEntries(diagnostics) {
  return aggregateThinkingActivityEntries((diagnostics || [])
    .map((entry, index) => normalizeThinkingActivityForModel(entry, index))
    .filter(Boolean));
}

function getProjectedThinkingActivities(session) {
  const canonicalKey = getActivityCanonicalKeyForSession(session);
  if (!canonicalKey || !state.activityProjection) {
    return [];
  }
  return state.activityProjection.activitiesFor(canonicalKey, {
    limit: LIVE_THINKING_ACTIVITY_ENTRY_LIMIT,
  }).map((activity, index) => normalizeThinkingActivityForModel({
    ...activity,
    activityKey: String(activity.activityKey || ''),
    activityRevision: Number(activity.activityRevision || 0),
    kind: activity.kind || 'reasoning',
    method: activity.method || null,
    text: String(activity.text == null ? '' : activity.text),
    timestamp: activity.timestamp || activity.updatedAt || null,
    turnId: activity.turnId || null,
    itemId: activity.itemId || null,
    final: activity.final === true,
    fileChanges: activity.fileChanges || [],
  }, index)).filter(Boolean);
}

function mergeProjectedThinkingEntries(diagnostics, projected) {
  const projectedEntries = Array.isArray(projected) ? projected : [];
  const projectedReasoning = projectedEntries.some((entry) => entry.kind === 'reasoning');
  const diagnosticEntries = (diagnostics || []).filter((entry) => (
    !projectedReasoning || String(entry?.kind || '').toLowerCase() !== 'reasoning'
  )).map((entry, index) => normalizeThinkingActivityForModel(entry, index)).filter(Boolean);
  const ordered = [...diagnosticEntries, ...projectedEntries]
    .sort((left, right) => (
      Date.parse(left.timestamp || 0) - Date.parse(right.timestamp || 0)
      || String(left.activityKey || '').localeCompare(String(right.activityKey || ''))
    ));
  return aggregateThinkingActivityEntries(ordered);
}

function isUserSuitableThinkingText(text, entry = {}) {
  const value = String(text || '').trim();
  if (!value) {
    return false;
  }
  if (String(entry.kind || '').toLowerCase() === 'notification') {
    return false;
  }
  if (/^\{\s*item:\s*\{/.test(value) || /^\{\s*threadId:/.test(value)) {
    return false;
  }
  if (/^\[object Object\]$/.test(value)) {
    return false;
  }
  return true;
}

function buildLiveActivitySegment(session, latestUserEntry = null, diagnostics = null) {
  const startTime = Date.parse(latestUserEntry?.timestamp || '');
  const startGraceMs = 5000;
  const sourceDiagnostics = Array.isArray(diagnostics)
    ? diagnostics.filter(isThinkingActivityDiagnostic)
    : getThinkingDiagnosticsForSession(session);
  const entries = sourceDiagnostics
    .filter((diag) => {
      if (!Number.isFinite(startTime)) {
        return true;
      }
      const diagTime = Date.parse(diag.timestamp || '');
      return Number.isFinite(diagTime) && diagTime >= startTime - startGraceMs;
    })
    .sort((a, b) => Date.parse(a.timestamp || 0) - Date.parse(b.timestamp || 0));
  const projected = getProjectedThinkingActivities(session).filter((entry) => {
    if (!Number.isFinite(startTime)) {
      return true;
    }
    const activityTime = Date.parse(entry.timestamp || '');
    return Number.isFinite(activityTime) && activityTime >= startTime - startGraceMs;
  });
  const activity = mergeProjectedThinkingEntries(entries, projected)
    .slice(-LIVE_THINKING_ACTIVITY_ENTRY_LIMIT);
  if (!activity.length) {
    return null;
  }
  return {
    userTimestamp: latestUserEntry?.timestamp || 'live',
    userText: latestUserEntry?.text || '',
    entries: activity,
    live: true,
  };
}

function getLatestUserTranscriptEntry(session) {
  const transcript = getTranscriptForSession(session);
  const minIndex = Math.max(0, transcript.length - LIVE_THINKING_TRANSCRIPT_LOOKBACK);
  for (let index = transcript.length - 1; index >= minIndex; index -= 1) {
    const entry = transcript[index];
    if (entry?.speaker === 'user') {
      return entry;
    }
  }
  return null;
}

function getLatestFormalAgentMessage(session) {
  if (!session) {
    return 'No recent agent reply captured.';
  }

  const transcript = getTranscriptForSession(session)
    .filter((entry) => entry && (entry.speaker === 'agent' || entry.speaker === 'assistant') && entry.text);
  const latest = transcript[transcript.length - 1];
  const fallback = String(session.latestAgentMessage || '').trim();
  if (fallback && fallback !== '[object Object]' && !/^\s*[\[{]/.test(fallback)) {
    return latest?.text || fallback;
  }
  return latest?.text || 'No recent agent reply captured.';
}

function buildThinkingEntriesForSession(session, options = {}) {
  if (!session) {
    return [];
  }

  const transcriptSource = Array.isArray(options.transcriptEntries)
    ? options.transcriptEntries
    : getTranscriptForSession(session);
  const transcript = transcriptSource
    .filter((entry) => entry && (entry.speaker === 'user' || entry.speaker === 'agent' || entry.speaker === 'assistant'));
  const thinkingDiagnostics = Array.isArray(options.diagnostics)
    ? options.diagnostics
    : getThinkingDiagnosticsForSession(session);
  const projectedActivities = getProjectedThinkingActivities(session);

  const transcriptTimes = transcript.map((entry) => Date.parse(entry.timestamp || '')).map((value) => (Number.isFinite(value) ? value : null));
  const segments = [];
  const startGraceMs = 5000;

  for (let index = 0; index < transcript.length; index += 1) {
    const entry = transcript[index];
    if (entry.speaker !== 'user') {
      continue;
    }

    const startTime = transcriptTimes[index];
    if (!Number.isFinite(startTime)) {
      continue;
    }

    let replyTime = Infinity;
    for (let nextIndex = index + 1; nextIndex < transcript.length; nextIndex += 1) {
      const nextEntry = transcript[nextIndex];
      if (nextEntry.speaker === 'agent' || nextEntry.speaker === 'assistant') {
        const nextTime = transcriptTimes[nextIndex];
        if (Number.isFinite(nextTime)) {
          replyTime = nextTime;
        }
        break;
      }
      if (nextEntry.speaker === 'user') {
        const nextTime = transcriptTimes[nextIndex];
        if (Number.isFinite(nextTime)) {
          replyTime = nextTime;
        }
        break;
      }
    }

    const windowEntries = thinkingDiagnostics
      .filter((diag) => {
        const diagTime = Date.parse(diag.timestamp || '');
        return Number.isFinite(diagTime) && diagTime >= startTime - startGraceMs && diagTime <= replyTime;
      })
      .sort((a, b) => Date.parse(a.timestamp || 0) - Date.parse(b.timestamp || 0));

    const windowActivities = projectedActivities.filter((activity) => {
      const activityTime = Date.parse(activity.timestamp || '');
      return Number.isFinite(activityTime) && activityTime >= startTime - startGraceMs && activityTime <= replyTime;
    });
    const merged = mergeProjectedThinkingEntries(windowEntries.slice(-80), windowActivities);

    if (merged.length) {
      segments.push({
        userTimestamp: entry.timestamp || null,
        userText: entry.text || '',
        entries: merged,
      });
    }
  }

  return segments;
}

function getTranscriptSearchTerms() {
  if (state.sessionSearchMode !== 'keyword') {
    return [];
  }
  return normalizeSearchTerms(state.sessionSearchQuery);
}

function buildTranscriptSearchMatches(visibleTranscript, focus = null) {
  const terms = getTranscriptSearchTerms();
  if (!terms.length) {
    return [];
  }
  const matches = [];
  for (const [index, entry] of visibleTranscript.entries()) {
    if (!entry || !['user', 'agent', 'assistant'].includes(entry.speaker || '')) {
      continue;
    }
    if (searchTermsMatchText(entry.text || '', terms) || transcriptEntryMatchesSearchMatch(entry, focus)) {
      matches.push({
        entryIndex: index,
        timestamp: entry.timestamp || null,
        speaker: entry.speaker || 'system',
      });
    }
  }
  return matches;
}

function clampTranscriptSearchIndex(matches, focus = null) {
  if (!matches.length) {
    return 0;
  }
  const focusIndex = Number(focus?.entryIndex ?? -1);
  if (focusIndex >= 0) {
    const byIndex = matches.findIndex((match) => match.entryIndex === focusIndex);
    if (byIndex >= 0) {
      return byIndex;
    }
  }
  if (focus?.timestamp) {
    const byTimestamp = matches.findIndex((match) => match.timestamp === focus.timestamp);
    if (byTimestamp >= 0) {
      return byTimestamp;
    }
  }
  return Math.min(Math.max(Number(state.transcriptSearchNavigator.index || 0), 0), matches.length - 1);
}

function getTranscriptSearchTarget(session = getSelectedSession()) {
  const key = getSessionKey(session) || '';
  const focus = state.pendingTranscriptFocus
    && state.pendingTranscriptFocus.hostId === session?.hostId
    && state.pendingTranscriptFocus.sessionId === session?.sessionId
    ? state.pendingTranscriptFocus
    : null;
  const matches = buildTranscriptSearchMatches(
    getTranscriptForSession(session).filter((entry) => entry.speaker === 'user' || entry.speaker === 'agent' || entry.speaker === 'assistant'),
    focus
  );
  if (!key || !matches.length) {
    return null;
  }
  const queryChanged = state.transcriptSearchNavigator.key !== key || state.transcriptSearchNavigator.query !== state.sessionSearchQuery;
  const index = queryChanged ? 0 : clampTranscriptSearchIndex(matches, state.pendingTranscriptFocus);
  return {
    key,
    query: state.sessionSearchQuery,
    matches,
    index,
    match: matches[index],
  };
}

function renderTranscriptSearchNavigator(session, matches = [], activeIndex = 0) {
  const container = el('transcript-search-navigator');
  if (!container) {
    return;
  }
  container.innerHTML = '';
  const key = getSessionKey(session) || '';
  const query = String(state.sessionSearchQuery || '').trim();
  if (!key || !query || !matches.length) {
    container.classList.add('hidden');
    return;
  }

  container.classList.remove('hidden');
  const label = document.createElement('div');
  label.className = 'transcript-search-label';
  label.textContent = `${activeIndex + 1} / ${matches.length}`;
  const queryText = document.createElement('div');
  queryText.className = 'transcript-search-query';
  queryText.textContent = query;
  const previous = document.createElement('button');
  previous.type = 'button';
  previous.className = 'secondary-button transcript-search-nav-button';
  previous.dataset.transcriptSearchNav = 'previous';
  previous.textContent = 'Prev';
  const next = document.createElement('button');
  next.type = 'button';
  next.className = 'secondary-button transcript-search-nav-button';
  next.dataset.transcriptSearchNav = 'next';
  next.textContent = 'Next';
  const close = document.createElement('button');
  close.type = 'button';
  close.className = 'secondary-button transcript-search-close-button';
  close.dataset.transcriptSearchNav = 'clear';
  close.textContent = '\u00d7';
  container.append(label, queryText, previous, next, close);
}

function focusTranscriptSearchMatch(direction = 'next') {
  const selected = getSelectedSession();
  const target = getTranscriptSearchTarget(selected);
  if (!target || !target.matches.length) {
    return;
  }
  const delta = direction === 'previous' ? -1 : 1;
  const nextIndex = direction === 'current'
    ? target.index
    : (target.index + delta + target.matches.length) % target.matches.length;
  const match = target.matches[nextIndex];
  state.transcriptSearchNavigator = {
    key: target.key,
    query: target.query,
    index: nextIndex,
  };
  state.pendingTranscriptFocus = {
    hostId: selected.hostId,
    sessionId: selected.sessionId,
    entryIndex: match.entryIndex,
    timestamp: match.timestamp || null,
    snippet: '',
  };
  renderTranscript(selected, { focus: state.pendingTranscriptFocus });
}

function isFileChangeDiagnostic(entry) {
  const method = String(entry?.method || '').toLowerCase();
  const kind = String(entry?.kind || '').toLowerCase();
  const message = String(entry?.message || '').toLowerCase();
  return kind === 'file-change'
    || kind === 'filechange'
    || method.includes('filechange')
    || method.includes('file_change')
    || method.includes('patch')
    || method.includes('diff')
    || /\b(file|files)\b.*\b(change|changed|edit|edited|patch|diff)\b/.test(message);
}

function countDiffLines(diffText) {
  let additions = 0;
  let deletions = 0;
  for (const line of String(diffText || '').split(/\r?\n/)) {
    if (line.startsWith('+++') || line.startsWith('---')) {
      continue;
    }
    if (line.startsWith('+')) {
      additions += 1;
    } else if (line.startsWith('-')) {
      deletions += 1;
    }
  }
  return { additions, deletions };
}

function countTextLines(text) {
  const value = String(text || '');
  if (!value) {
    return 0;
  }
  return value.split(/\r?\n/).filter((line, index, lines) => line || index < lines.length - 1).length;
}

function toCount(value) {
  const number = Number(value);
  return Number.isFinite(number) && number >= 0 ? number : null;
}

function normalizeFileChangeStatus(value) {
  const text = String(value || '').toLowerCase();
  if (['a', 'add', 'added', 'create', 'created', 'new'].includes(text)) {
    return 'added';
  }
  if (['d', 'delete', 'deleted', 'remove', 'removed'].includes(text)) {
    return 'deleted';
  }
  if (['m', 'modify', 'modified', 'update', 'updated', 'edit', 'edited'].includes(text)) {
    return 'modified';
  }
  if (['r', 'rename', 'renamed', 'move', 'moved'].includes(text)) {
    return 'renamed';
  }
  return '';
}

function fileChangeStatusLabel(status) {
  switch (normalizeFileChangeStatus(status)) {
    case 'added':
      return 'Added';
    case 'deleted':
      return 'Deleted';
    case 'renamed':
      return 'Renamed';
    case 'modified':
      return 'Modified';
    default:
      return 'Changed';
  }
}

function pathFromDiffHeader(diffText) {
  const text = String(diffText || '');
  const gitMatch = text.match(/^diff --git a\/(.+?) b\/(.+)$/m);
  if (gitMatch) {
    return gitMatch[2] || gitMatch[1];
  }
  const plusMatch = text.match(/^\+\+\+\s+(?:b\/)?(.+)$/m);
  if (plusMatch && plusMatch[1] !== '/dev/null') {
    return plusMatch[1];
  }
  const minusMatch = text.match(/^---\s+(?:a\/)?(.+)$/m);
  if (minusMatch && minusMatch[1] !== '/dev/null') {
    return minusMatch[1];
  }
  return '';
}

function splitUnifiedDiff(diffText) {
  const text = String(diffText || '').trim();
  if (!text) {
    return [];
  }
  const chunks = text.split(/\n(?=diff --git\s+)/);
  return chunks.filter(Boolean).map((chunk) => {
    const counts = countDiffLines(chunk);
    return {
      path: pathFromDiffHeader(chunk) || 'workspace change',
      status: 'modified',
      additions: counts.additions,
      deletions: counts.deletions,
      diff: chunk,
    };
  });
}

function normalizeFileChangeRecord(raw, fallbackPath = '') {
  if (!raw || typeof raw !== 'object') {
    return null;
  }
  const diff = String(raw.diff || raw.patch || raw.unifiedDiff || raw.unified_diff || '').trim();
  const counts = countDiffLines(diff);
  const rawStatus = normalizeFileChangeStatus(raw.status || raw.changeType || raw.change_type || raw.type || raw.kind || raw.action);
  const pathValue = String(
    raw.path
      || raw.filePath
      || raw.file_path
      || raw.absolutePath
      || raw.relativePath
      || raw.filename
      || raw.name
      || fallbackPath
      || pathFromDiffHeader(diff)
      || ''
  ).trim();
  const contentLineCount = countTextLines(raw.content || raw.text || '');
  const additions = toCount(raw.additions ?? raw.added ?? raw.insertions ?? raw.linesAdded ?? raw.addedLines)
    ?? (diff ? counts.additions : rawStatus === 'added' ? contentLineCount : null);
  const deletions = toCount(raw.deletions ?? raw.deleted ?? raw.removed ?? raw.linesDeleted ?? raw.deletedLines)
    ?? (diff ? counts.deletions : rawStatus === 'deleted' ? contentLineCount : null);
  if (!diff && !rawStatus && additions === null && deletions === null) {
    return null;
  }
  return {
    path: pathValue || 'workspace change',
    status: rawStatus || (diff ? 'modified' : ''),
    additions,
    deletions,
    diff,
  };
}

function parsePatchApplyUpdatedFiles(value) {
  const text = String(value || '');
  const marker = 'Updated the following files:';
  const markerIndex = text.indexOf(marker);
  if (markerIndex < 0) {
    return [];
  }
  const lines = text.slice(markerIndex + marker.length).split(/\r?\n/);
  const records = [];
  for (const line of lines) {
    const match = line.match(/^\s*([AMDR])\s+(.+?)\s*$/);
    if (!match) {
      if (records.length && line.trim()) {
        break;
      }
      continue;
    }
    const status = normalizeFileChangeStatus(match[1]);
    records.push({
      path: match[2],
      status,
      additions: null,
      deletions: null,
      diff: '',
    });
  }
  return records;
}

function normalizeFileChanges(entry) {
  const roots = [
    entry?.fileChanges,
    entry?.data,
    entry?.payload,
    entry?.data?.payload,
    entry?.data?.changes,
    entry?.data?.files,
    entry?.data?.fileChanges,
    entry?.data?.edits,
    entry?.data?.patches,
  ].filter(Boolean);
  const records = [];
  const seen = new Set();

  function addRecord(record) {
    if (!record) {
      return;
    }
    const key = `${record.path}|${record.additions}|${record.deletions}|${record.diff.slice(0, 80)}`;
    if (seen.has(key)) {
      return;
    }
    seen.add(key);
    records.push(record);
  }

  function visit(value, fallbackPath = '', depth = 0) {
    if (!value || depth > 5) {
      return;
    }
    if (typeof value === 'string') {
      if (/^(diff --git|--- |\+\+\+ |@@ )/m.test(value)) {
        for (const record of splitUnifiedDiff(value)) {
          addRecord(record);
        }
      }
      return;
    }
    if (Array.isArray(value)) {
      for (const item of value) {
        visit(item, fallbackPath, depth + 1);
      }
      return;
    }
    if (typeof value !== 'object') {
      return;
    }

    const nextFallback = String(value.path || value.filePath || value.file_path || value.filename || value.name || fallbackPath || '');
    const looksLikeFileChangeMap = !Array.isArray(value)
      && Object.keys(value).length > 0
      && Object.values(value).every((item) => item && typeof item === 'object' && (
        item.type || item.unified_diff || item.unifiedDiff || item.diff || item.patch || item.content
      ))
      && !('type' in value)
      && !('diff' in value)
      && !('patch' in value)
      && !('unified_diff' in value)
      && !('unifiedDiff' in value);
    if (looksLikeFileChangeMap) {
      for (const [pathKey, item] of Object.entries(value)) {
        addRecord(normalizeFileChangeRecord(item, pathKey));
      }
      return;
    }

    addRecord(normalizeFileChangeRecord(value, nextFallback));
    for (const key of ['changes', 'files', 'fileChanges', 'file_changes', 'edits', 'patches', 'diffs', 'items']) {
      if (value[key]) {
        visit(value[key], nextFallback, depth + 1);
      }
    }
    for (const key of ['diff', 'patch', 'unifiedDiff', 'unified_diff']) {
      if (typeof value[key] === 'string') {
        visit(value[key], nextFallback, depth + 1);
      }
    }
    for (const key of ['stdout', 'stderr', 'output']) {
      if (typeof value[key] === 'string') {
        for (const record of parsePatchApplyUpdatedFiles(value[key])) {
          addRecord(record);
        }
      }
    }
  }

  for (const root of roots) {
    visit(root);
  }
  return records.slice(0, 12);
}

function shortId(value) {
  const text = String(value || '');
  if (!text) {
    return '';
  }
  return text.length > 16 ? `${text.slice(0, 8)}...${text.slice(-6)}` : text;
}

function normalizeTranscriptFiles(rawFiles) {
  const files = [];
  const seen = new Set();
  for (const rawFile of Array.isArray(rawFiles) ? rawFiles : []) {
    if (!rawFile || typeof rawFile !== 'object') {
      continue;
    }
    const pathValue = normalizeRemoteFilePath(rawFile.path || rawFile.remotePath || '');
    const name = String(rawFile.name || basename(pathValue) || 'file').trim();
    if (!pathValue && !name) {
      continue;
    }
    const key = `${pathValue}|${name}`;
    if (seen.has(key)) {
      continue;
    }
    seen.add(key);
    const mime = String(rawFile.mime || rawFile.type || '').trim();
    files.push({
      fileId: String(rawFile.fileId || rawFile.id || key),
      name,
      path: pathValue,
      size: Number(rawFile.size || 0) || 0,
      mime,
      isImage: Boolean(rawFile.isImage) || /^image\//i.test(mime) || IMAGE_FILE_EXTENSIONS.has(fileExtension(name || pathValue)),
      cached: Boolean(rawFile.cached),
    });
  }
  return files;
}

function dedupeTranscript(entries) {
  const seen = new Map();
  const deduped = [];

  for (const entry of entries || []) {
    const files = normalizeTranscriptFiles(entry?.files || entry?.attachments || []);
    if (!entry || (!entry.text && !files.length)) {
      continue;
    }

    const normalized = {
      speaker: entry.speaker || 'system',
      text: cleanTranscriptTextForDisplay(entry.text || '', entry.speaker || 'system'),
      timestamp: entry.timestamp || null,
      stream: entry.stream || null,
      source: entry.source || null,
      clientRequestId: entry.clientRequestId || null,
      deliveryStatus: entry.deliveryStatus || null,
      assistantMessageId: entry.assistantMessageId || null,
      assistantSeq: Number.isSafeInteger(Number(entry.assistantSeq)) ? Number(entry.assistantSeq) : null,
      assistantAt: entry.assistantAt || null,
      notifiable: entry.notifiable === true,
      files,
    };
    if (!normalized.text && !files.length) {
      continue;
    }
    const key = normalized.assistantMessageId
      ? `assistant|${normalized.assistantMessageId}`
      : normalized.clientRequestId
        ? `${normalized.speaker}|request|${normalized.clientRequestId}`
        : `${normalized.speaker}|${normalized.timestamp || ''}|${canonicalTranscriptText(normalized.text)}|${files.map((file) => file.path || file.name).join(',')}`;
    if (seen.has(key)) {
      const index = seen.get(key);
      deduped[index] = { ...deduped[index], ...normalized };
      continue;
    }
    seen.set(key, deduped.length);
    deduped.push(normalized);
  }

  const sorted = deduped
    .map((entry, index) => ({ entry, index }))
    .sort((a, b) => {
      const left = Date.parse(a.entry.timestamp || '');
      const right = Date.parse(b.entry.timestamp || '');
      if (Number.isFinite(left) && Number.isFinite(right) && left !== right) {
        return left - right;
      }
      if (Number.isFinite(left) !== Number.isFinite(right)) {
        return Number.isFinite(left) ? -1 : 1;
      }
      return a.index - b.index;
    })
    .map((item) => item.entry);

  const compacted = [];
  for (const entry of sorted) {
    const previous = compacted[compacted.length - 1];
    const entryFiles = entry.files.map((file) => file.path || file.name).join(',');
    const previousFiles = previous?.files?.map((file) => file.path || file.name).join(',') || '';
    const sameSpeakerAndFiles = previous
      && previous.speaker === entry.speaker
      && previousFiles === entryFiles;
    const assistantIdentityPresent = Boolean(
      previous?.assistantMessageId || entry.assistantMessageId
    );
    const previousText = canonicalTranscriptText(previous?.text || '');
    const entryText = canonicalTranscriptText(entry.text || '');
    if (!assistantIdentityPresent && sameSpeakerAndFiles && previousText && entryText && previousText === entryText) {
      continue;
    }

    const entryTime = Date.parse(entry.timestamp || '');
    const previousTime = Date.parse(previous?.timestamp || '');
    const nearDuplicate = previous
      && sameSpeakerAndFiles
      && !assistantIdentityPresent
      && previousText
      && entryText
      && Number.isFinite(entryTime)
      && Number.isFinite(previousTime)
      && Math.abs(entryTime - previousTime) <= 30000
      && (previousText.includes(entryText) || entryText.includes(previousText));
    if (nearDuplicate) {
      continue;
    }
    compacted.push(entry);
  }

  return compacted;
}

function getRunnerSummary(session) {
  if (!session) {
    return {
      label: 'Unknown',
      warning: null,
    };
  }

  if (session.source !== 'managed') {
    const runtime = getRuntimeForSession(session) || session.runtime || {};
    return {
      label: runtime.connection === 'tailing' ? 'Imported History + Live Tail' : 'Imported History',
      warning: runtime.connection === 'tailing'
        ? 'This session is being tailed from .codex history in real time. Control actions still require a managed Codex app-server session.'
        : 'This session is imported from .codex history only. It does not have a live process until you resume or fork it.',
    };
  }

  const runtimeCommand = String(session.runtime?.command || '');
  const runtimeArgs = Array.isArray(session.runtime?.args) ? session.runtime.args : [];
  const runtimeKind = String(session.runtime?.kind || '');
  const joined = [runtimeCommand, ...runtimeArgs].join(' ').toLowerCase();

  if (joined.includes('demo-session.js') || runtimeCommand.toLowerCase().includes('demo')) {
    return {
      label: 'Demo Runner',
      warning: 'This managed session is still using the local demo runner. Transport works, but agent text and action buttons are simulated rather than coming from a real Codex model.',
    };
  }

  if (runtimeKind === 'codex_app_server' || (joined.includes('codex') && joined.includes('app-server'))) {
    const strategy = session.runtime?.resumeStrategy;
    const warning = strategy === 'transcript_fallback'
      ? 'This live session had to fall back to history transcript bootstrapping because the original native Codex thread was not available.'
      : null;
    return {
      label: 'Codex App Server',
      warning,
    };
  }

  if (joined.includes('codex') && joined.includes('remote-control')) {
    return {
      label: 'Codex Remote Control',
      warning: 'This session is backed by Codex remote-control. Structured runtime events should be available, but this integration may still be incomplete.',
    };
  }

  return {
    label: runtimeCommand ? basename(runtimeCommand) : 'Managed Runner',
    warning: runtimeCommand
      ? `This session is managed by ${basename(runtimeCommand)}. Structured Codex events depend on the runner integration.`
      : 'This managed session does not expose a runtime command yet.',
  };
}

function getHost(hostId) {
  return state.hosts.find((host) => host.hostId === hostId) || null;
}

async function verifyHostAvailable(hostId, options = {}) {
  const host = getHost(hostId);
  if (!host) {
    throw new Error(`Host ${hostId || '(unknown)'} is not registered.`);
  }
  if (!host.online) {
    throw new Error(`Host ${host.label || host.hostId} is offline. Start its agent or restart the HPC connector first.`);
  }

  if (options.probe === false) {
    return { ok: true, cached: true };
  }

  const result = await fetchJson(`/api/hosts/${encodeURIComponent(hostId)}/probe`, {
    method: 'POST',
  });
  if (!result?.ok) {
    throw new Error(result?.error || `Host ${host.label || host.hostId} did not answer the health check.`);
  }
  return result;
}

function getSessionsForHost(hostId) {
  return state.sessions.filter((session) => session.hostId === hostId);
}

function getTrashCollection() {
  return state.sessionCollections.find((collection) => collection.collectionId === TRASH_COLLECTION_ID) || null;
}

function collectionItemsMatch(left, right) {
  if (!left || !right || left.hostId !== right.hostId) {
    return false;
  }
  if (left.conversationKey && right.conversationKey && left.conversationKey === right.conversationKey) {
    return true;
  }
  return Boolean(left.sessionId && right.sessionId && left.sessionId === right.sessionId);
}

function buildCollectionMatchItem(groupOrSession) {
  const conversationKey = groupOrSession?.conversationKey || getSessionConversationKey(groupOrSession);
  return {
    hostId: groupOrSession?.hostId,
    conversationKey,
    sessionId: groupOrSession?.sessionId || groupOrSession?.preferredSession?.sessionId || '',
  };
}

function isConversationInTrash(groupOrSession) {
  const trash = getTrashCollection();
  const trashItems = Array.isArray(trash?.items) ? trash.items : [];
  if (!trashItems.length || !groupOrSession) {
    return false;
  }
  const item = buildCollectionMatchItem(groupOrSession);
  return trashItems.some((entry) => collectionItemsMatch(entry, item));
}

function isConversationDiscarded(groupOrSession) {
  const trash = getTrashCollection();
  const discardedItems = Array.isArray(trash?.discardedItems) ? trash.discardedItems : [];
  if (!discardedItems.length || !groupOrSession) {
    return false;
  }
  const item = buildCollectionMatchItem(groupOrSession);
  return discardedItems.some((entry) => collectionItemsMatch(entry, item));
}

function isConversationHiddenByTrash(groupOrSession) {
  return isConversationInTrash(groupOrSession) || isConversationDiscarded(groupOrSession);
}

function getRecentDirectories(hostId, limit = 8) {
  const seen = new Set();
  const recent = [];

  for (const session of getSessionsForHost(hostId).sort(compareSessions)) {
    const cwd = String(session.cwd || '').trim();
    if (!cwd || seen.has(cwd)) {
      continue;
    }

    seen.add(cwd);
    recent.push({
      path: cwd,
      title: session.title || pathLeaf(cwd) || cwd,
      live: Boolean(session.live),
      updatedAt: session.lastUpdatedAt || session.updatedAt || null,
    });

    if (recent.length >= limit) {
      break;
    }
  }

  return recent;
}

function getSessionConversationKey(session) {
  if (!session) {
    return '';
  }
  const conversationKey = session.conversationKey || '';
  const isIdentityConversationKey = conversationKey && conversationKey === session.sessionId;
  if (conversationKey && !isIdentityConversationKey) {
    return conversationKey;
  }
  return session.originSessionId
    || session.sourceSessionId
    || session.bridgeSessionId
    || (session.nativeThreadId && session.nativeThreadId !== session.sessionId ? session.nativeThreadId : '')
    || conversationKey
    || session.sessionId;
}

function filterVisibleConversationVariants(sessions) {
  const variants = Array.isArray(sessions) ? sessions : [];
  const hasLiveManagedVariant = variants.some((session) => (
    session?.source === 'managed' && session.live === true
  ));
  if (!hasLiveManagedVariant) {
    return variants;
  }
  return variants.filter((session) => !(
    session?.source === 'managed'
    && session.live !== true
    && String(session.state || '').toLowerCase() === 'starting'
    && getSessionMessageCount(session) === 0
  ));
}

function getConversationGroups(hostId) {
  const groups = new Map();

  for (const session of getSessionsForHost(hostId).filter((entry) => !isConversationHiddenByTrash(entry))) {
    const conversationKey = getSessionConversationKey(session);
    const group = groups.get(conversationKey) || {
      hostId,
      conversationKey,
      sessions: [],
    };

    group.sessions.push({
      ...session,
      conversationKey,
    });
    groups.set(conversationKey, group);
  }

  return Array.from(groups.values())
    .map((group) => {
      group.sessions = filterVisibleConversationVariants(group.sessions);
      group.sessions.sort(compareSessions);
      group.totalCount = group.sessions.length;
      group.liveCount = group.sessions.filter((session) => session.live).length;
      group.preferredSession = group.sessions.find((session) => session.live) || group.sessions[0] || null;
      group.cwd = group.preferredSession?.cwd || group.sessions.find((session) => session.cwd)?.cwd || null;
      group.title = group.preferredSession?.title || group.sessions[0]?.title || group.conversationKey;
      group.createdAt = earliestSessionIso(group.sessions);
      group.lastUpdatedAt = latestSessionIso(group.sessions);
      group.messageCount = group.sessions.reduce((total, session) => total + getSessionMessageCount(session), 0);
      group.latestUserMessage = firstNonEmpty(group.sessions.map((session) => session.latestUserMessage));
      group.latestAgentMessage = firstNonEmpty(group.sessions.map((session) => session.latestAgentMessage));
      group.apiProfile = group.preferredSession?.apiProfile || group.sessions.find((session) => session.apiProfile)?.apiProfile || null;
      return group;
    })
    .sort((a, b) => {
      const delta = parseSessionTime({ lastUpdatedAt: b.lastUpdatedAt }) - parseSessionTime({ lastUpdatedAt: a.lastUpdatedAt });
      if (delta !== 0) {
        return delta;
      }
      return String(a.title || a.conversationKey).localeCompare(String(b.title || b.conversationKey));
    });
}

function earliestSessionIso(sessions) {
  let best = null;
  let bestTime = Infinity;
  for (const session of sessions || []) {
    const time = parseCreatedTime(session);
    if (!time || time >= bestTime) {
      continue;
    }
    bestTime = time;
    best = new Date(time).toISOString();
  }
  return best;
}

function latestSessionIso(sessions) {
  let best = null;
  let bestTime = 0;
  for (const session of sessions || []) {
    const time = parseSessionTime(session);
    if (!time || time <= bestTime) {
      continue;
    }
    bestTime = time;
    best = new Date(time).toISOString();
  }
  return best;
}

function sortConversationGroups(groups) {
  const sortBy = state.sessionSortBy;
  const direction = state.sessionSortDir === 'asc' ? 1 : -1;
  const sorted = [...(groups || [])];
  const sortableTime = (value) => {
    const time = Date.parse(value || '');
    if (Number.isFinite(time)) {
      return time;
    }
    return direction === 1 ? Infinity : -Infinity;
  };
  sorted.sort((a, b) => {
    const liveDelta = Number(a.liveCount > 0) - Number(b.liveCount > 0);
    if (liveDelta !== 0) {
      return -liveDelta;
    }

    let delta = 0;
    if (sortBy === 'createdAt') {
      delta = sortableTime(a.createdAt) - sortableTime(b.createdAt);
    } else if (sortBy === 'messageCount') {
      delta = Number(a.messageCount || 0) - Number(b.messageCount || 0);
    } else {
      delta = sortableTime(a.lastUpdatedAt) - sortableTime(b.lastUpdatedAt);
    }

    if (delta !== 0) {
      return delta * direction;
    }
    return String(a.title || a.conversationKey).localeCompare(String(b.title || b.conversationKey));
  });
  return sorted;
}

function getAllConversationGroups() {
  return state.hosts.flatMap((host) => getConversationGroups(host.hostId));
}

function firstNonEmpty(values) {
  for (const value of values) {
    if (value) {
      return value;
    }
  }
  return null;
}

function getConversationSearchText(group) {
  const titleValues = [
    group.title,
    ...(group.sessions || []).map((session) => session.title),
  ];
  const pathValues = [
    group.cwd,
    ...(group.sessions || []).map((session) => session.cwd),
  ];
  if (state.sessionSearchMode === 'title') {
    return titleValues.filter(Boolean).join(' ').toLowerCase();
  }
  if (state.sessionSearchMode === 'path') {
    return pathValues.filter(Boolean).join(' ').toLowerCase();
  }

  return [
    ...titleValues,
    ...pathValues,
    group.conversationKey,
    limitSearchText(group.latestUserMessage),
    limitSearchText(group.latestAgentMessage),
    ...(group.sessions || []).flatMap((session) => [
      session.sessionId,
      session.nativeThreadId,
      session.bridgeSessionId,
      limitSearchText(session.latestUserMessage),
      limitSearchText(session.latestAgentMessage),
      ...(Array.isArray(session.transcriptPreview) ? session.transcriptPreview.map((entry) => limitSearchText(entry.text)) : []),
      ...(state.transcripts.get(makeSessionKey(session.hostId, session.sessionId)) || []).slice(-20).map((entry) => limitSearchText(entry.text)),
    ]),
  ].filter(Boolean).join(' ').toLowerCase();
}

function filterConversationGroups(groups) {
  const query = String(state.sessionSearchQuery || '').trim().toLowerCase();
  if (!query) {
    return groups;
  }

  const terms = query.split(/\s+/).filter(Boolean);
  return groups.filter((group) => {
    const haystack = getConversationSearchText(group);
    return terms.every((term) => haystack.includes(term));
    });
}

function searchResultKey(result) {
  return makeSessionKey(result?.hostId || '', result?.sessionId || '');
}

function getSearchResultsForGroup(group) {
  if (!group || !state.sessionSearchQuery.trim()) {
    return [];
  }
  const sessionIds = new Set((group.sessions || []).map((session) => session.sessionId));
  return state.sessionSearchResults.filter((result) => (
    result.hostId === group.hostId
    && (
      result.conversationKey === group.conversationKey
      || sessionIds.has(result.sessionId)
    )
  ));
}

function hasServerSearchResult(group) {
  return getSearchResultsForGroup(group).length > 0;
}

function filterConversationGroupsWithSearch(groups) {
  const localMatches = filterConversationGroups(groups);
  const query = String(state.sessionSearchQuery || '').trim();
  if (!query || state.sessionSearchMode !== 'keyword' || !state.sessionSearchResults.length) {
    return localMatches;
  }

  const seen = new Set(localMatches.map((group) => `${group.hostId}::${group.conversationKey}`));
  const merged = [...localMatches];
  for (const group of groups) {
    const key = `${group.hostId}::${group.conversationKey}`;
    if (!seen.has(key) && hasServerSearchResult(group)) {
      seen.add(key);
      merged.push(group);
    }
  }
  return merged;
}

function getSelectedCollection() {
  return state.sessionCollections.find((collection) => collection.collectionId === state.selectedCollectionId)
    || state.sessionCollections[0]
    || { collectionId: 'default', name: 'Default', system: true, items: [] };
}

const SESSION_SEARCH_MODE_LABELS = {
  keyword: 'Keyword',
  path: 'Path',
  title: 'Title',
};

const SESSION_SORT_LABELS = {
  updatedAt: 'Recently updated',
  createdAt: 'Created time',
  messageCount: 'Message count',
};

function getSessionSearchModeLabel(mode) {
  return SESSION_SEARCH_MODE_LABELS[mode] || SESSION_SEARCH_MODE_LABELS.keyword;
}

function getSessionSortLabel(mode) {
  return SESSION_SORT_LABELS[mode] || SESSION_SORT_LABELS.updatedAt;
}

function closeMobileSelectMenus() {
  state.mobileMenus.hostSwitcher = false;
  state.mobileMenus.collection = false;
  state.mobileMenus.searchMode = false;
  state.mobileMenus.sortBy = false;
  state.mobileMenus.collectionMoveKey = null;
}

function hasOpenMobileSelectMenu() {
  return Boolean(
    state.mobileMenus.hostSwitcher
    || state.mobileMenus.collection
    || state.mobileMenus.searchMode
    || state.mobileMenus.sortBy
    || state.mobileMenus.collectionMoveKey
  );
}

function toggleMobileSelectMenu(name, value = true) {
  const wasOpen = name === 'collectionMoveKey'
    ? state.mobileMenus.collectionMoveKey === value
    : Boolean(state.mobileMenus[name]);
  closeMobileSelectMenus();

  if (!wasOpen) {
    if (name === 'collectionMoveKey') {
      state.mobileMenus.collectionMoveKey = value;
    } else {
      state.mobileMenus[name] = true;
    }
  }

  renderAll();
}

function renderMobileSelectMenu({
  button,
  menu,
  label,
  options,
  selectedValue,
  open,
  disabled = false,
  onSelect,
}) {
  if (!button || !menu) {
    return;
  }

  button.textContent = label || 'Select';
  button.disabled = Boolean(disabled);
  button.setAttribute('aria-expanded', open ? 'true' : 'false');
  menu.classList.toggle('hidden', !open);
  menu.innerHTML = '';

  const optionList = Array.isArray(options) ? options : [];
  if (!optionList.length) {
    const empty = document.createElement('button');
    empty.type = 'button';
    empty.className = 'mobile-select-option';
    empty.disabled = true;
    empty.textContent = 'No options available';
    menu.appendChild(empty);
    return;
  }

  for (const option of optionList) {
    const item = document.createElement('button');
    item.type = 'button';
    item.className = `mobile-select-option ${option.value === selectedValue ? 'active' : ''}`.trim();
    item.disabled = Boolean(option.disabled);
    item.textContent = option.label || option.value || 'Option';
    item.onclick = async (event) => {
      event.preventDefault();
      event.stopPropagation();
      if (item.disabled) {
        return;
      }
      closeMobileSelectMenus();
      renderAll();
      try {
        await onSelect?.(option.value, option);
      } catch (error) {
        reportError(error);
      }
    };
    menu.appendChild(item);
  }
}

function openNativeSelect(select) {
  if (!select || select.disabled) {
    return;
  }
  select.focus();
  try {
    if (typeof select.showPicker === 'function') {
      select.showPicker();
      return;
    }
  } catch {
    // Some mobile browsers expose showPicker but block synthetic opens.
  }
  try {
    select.click();
  } catch {
    // Focusing still leaves the native control ready for the next tap.
  }
}

function getConversationGroupsForCollection(collection = getSelectedCollection()) {
  if (!collection || collection.collectionId === 'default') {
    return state.selectedHostId ? getConversationGroups(state.selectedHostId) : [];
  }

  const allGroups = getAllConversationGroups();
  const groupMap = new Map(allGroups.map((group) => [`${group.hostId}::${group.conversationKey}`, group]));
  const seen = new Map();
  const groups = [];

  for (const item of collection.items || []) {
      const key = `${item.hostId}::${item.conversationKey}`;
      const group = groupMap.get(key) || findCollectionConversationGroup(allGroups, item);
    const resolved = group
      ? {
          ...group,
          collectionItem: item,
        }
      : {
          hostId: item.hostId,
          hostLabel: item.hostLabel,
          conversationKey: item.conversationKey,
          sessions: [],
          totalCount: item.sessionId ? 1 : 0,
          liveCount: 0,
          preferredSession: null,
          cwd: item.cwd || null,
          title: item.title || item.conversationKey,
          createdAt: item.createdAt || item.addedAt || null,
          lastUpdatedAt: item.updatedAt || item.addedAt || null,
          messageCount: Number(item.messageCount || 0),
          latestUserMessage: null,
          latestAgentMessage: null,
          collectionOnly: true,
          collectionItem: item,
        };
    const dedupeKeys = getCollectionGroupDedupeKeys(resolved, item);
    const existingIndex = dedupeKeys
      .map((dedupeKey) => seen.get(dedupeKey))
      .find((index) => Number.isInteger(index));
    if (Number.isInteger(existingIndex)) {
      const existing = groups[existingIndex];
      const existingItem = existing?.collectionItem || {};
      if (parseSessionTime({ lastUpdatedAt: item.updatedAt || item.addedAt })
        >= parseSessionTime({ lastUpdatedAt: existingItem.updatedAt || existingItem.addedAt })) {
        groups[existingIndex] = {
          ...existing,
          ...resolved,
          collectionItem: item,
        };
      }
      for (const dedupeKey of dedupeKeys) {
        seen.set(dedupeKey, existingIndex);
      }
      continue;
    }

    const nextIndex = groups.length;
    for (const dedupeKey of dedupeKeys) {
      seen.set(dedupeKey, nextIndex);
    }
    groups.push(resolved);
  }

  return groups
    .sort((a, b) => {
      const delta = parseSessionTime({ lastUpdatedAt: b.lastUpdatedAt }) - parseSessionTime({ lastUpdatedAt: a.lastUpdatedAt });
      if (delta !== 0) {
        return delta;
      }
      return String(a.title || a.conversationKey).localeCompare(String(b.title || b.conversationKey));
    });
}

function getCollectionGroupDedupeKeys(group, item = {}) {
  const hostId = group?.hostId || item.hostId || '';
  const keys = new Set();
  const add = (kind, value) => {
    if (hostId && value) {
      keys.add(`${kind}::${hostId}::${value}`);
    }
  };

  add('group', group?.conversationKey);
  add('item', item.conversationKey);
  add('session', item.sessionId);
  for (const session of group?.sessions || []) {
    add('session', session.sessionId);
    add('conversation', session.conversationKey);
    add('origin', session.originSessionId);
    add('source', session.sourceSessionId);
    add('bridge', session.bridgeSessionId);
    add('native', session.nativeThreadId);
  }
  return Array.from(keys);
}

function findCollectionConversationGroup(groups, item) {
  if (!item || !item.hostId) {
    return null;
  }

  const candidates = groups.filter((group) => group.hostId === item.hostId);
  const identities = [
    item.conversationKey,
    item.sessionId,
  ].filter(Boolean).map(String);

  if (identities.length) {
    const exact = candidates.find((group) => {
      const values = getConversationIdentityValues(group);
      return identities.some((identity) => values.has(identity));
    });
    if (exact) {
      return exact;
    }
  }

  const itemPath = normalizeConversationPath(item.cwd);
  if (!itemPath) {
    return null;
  }

  const itemTitle = normalizeConversationTitle(item.title);
  const pathMatches = candidates.filter((group) => normalizeConversationPath(group.cwd) === itemPath);
  if (!pathMatches.length) {
    return null;
  }
  if (!itemTitle) {
    return pathMatches.length === 1 ? pathMatches[0] : null;
  }

  const titleMatch = pathMatches.find((group) => {
    const groupTitles = [
      group.title,
      ...(group.sessions || []).map((session) => session.title),
    ].map(normalizeConversationTitle).filter(Boolean);
    return groupTitles.includes(itemTitle);
  });
  if (titleMatch) {
    return titleMatch;
  }
  return pathMatches.length === 1 ? pathMatches[0] : null;
}

function getConversationIdentityValues(group) {
  const values = new Set();
  const add = (value) => {
    if (value) {
      values.add(String(value));
    }
  };

  add(group.conversationKey);
  for (const session of group.sessions || []) {
    add(session.sessionId);
    add(session.conversationKey);
    add(session.originSessionId);
    add(session.sourceSessionId);
    add(session.bridgeSessionId);
    add(session.nativeThreadId);
  }
  return values;
}

function normalizeConversationPath(value) {
  return String(value || '')
    .trim()
    .replace(/\\/g, '/')
    .replace(/\/+/g, '/')
    .replace(/\/$/, '')
    .toLowerCase();
}

function normalizeConversationTitle(value) {
  return String(value || '').trim().toLowerCase();
}

function getHostSnapshotForCollection(hostId) {
  const host = getHost(hostId) || {};
  const connector = state.connectors.find((item) => item.hostId === hostId) || null;
  return {
    hostLabel: host.label || hostId,
    hostPlatform: host.platform || '',
    targetHost: connector?.targetHost || '',
    targetPort: connector?.targetPort || null,
    connectorId: connector?.connectorId || '',
    connectorLabel: connector?.label || '',
    relayUrl: connector?.relayUrl || '',
  };
}

function buildCollectionItemFromConversation(group) {
  const session = group.preferredSession || group.sessions?.[0] || null;
  return {
    hostId: group.hostId,
    conversationKey: group.conversationKey,
    sessionId: session?.sessionId || group.collectionItem?.sessionId || '',
    title: group.title || session?.title || group.conversationKey,
    cwd: group.cwd || session?.cwd || '',
    ...getHostSnapshotForCollection(group.hostId),
  };
}

function buildCollectionItemFromSession(session) {
  if (!session) {
    return null;
  }
  const conversationKey = getSessionConversationKey(session);
  return {
    hostId: session.hostId,
    conversationKey,
    sessionId: session.sessionId || '',
    title: session.title || conversationKey,
    cwd: session.cwd || '',
    ...getHostSnapshotForCollection(session.hostId),
  };
}

async function refreshSessionCollections() {
  const response = await fetchJson('/api/session-collections');
  state.sessionCollections = response.collections || [];
  if (!state.sessionCollections.some((collection) => collection.collectionId === state.selectedCollectionId)) {
    state.selectedCollectionId = state.sessionCollections[0]?.collectionId || 'default';
  }
}

async function createSessionCollection(name) {
  const response = await fetchJson('/api/session-collections', {
    method: 'POST',
    body: JSON.stringify({ name }),
  });
  await refreshSessionCollections();
  state.selectedCollectionId = response.collection?.collectionId || state.selectedCollectionId;
  renderAll();
}

async function renameSessionCollection(collectionId, name) {
  if (!collectionId || collectionId === 'default') {
    return;
  }
  const response = await fetchJson(`/api/session-collections/${encodeURIComponent(collectionId)}`, {
    method: 'PATCH',
    body: JSON.stringify({ name }),
  });
  await refreshSessionCollections();
  state.selectedCollectionId = response.collection?.collectionId || state.selectedCollectionId;
  renderAll();
}

async function deleteSessionCollection(collectionId) {
  if (!collectionId || collectionId === 'default') {
    return;
  }
  await fetchJson(`/api/session-collections/${encodeURIComponent(collectionId)}`, {
    method: 'DELETE',
  });
  if (state.selectedCollectionId === collectionId) {
    state.selectedCollectionId = 'default';
  }
  await refreshSessionCollections();
  renderAll();
}

async function addConversationToCollection(collectionId, group) {
  if (!collectionId || collectionId === 'default') {
    return;
  }
  await fetchJson(`/api/session-collections/${encodeURIComponent(collectionId)}/items`, {
    method: 'POST',
    body: JSON.stringify({ item: buildCollectionItemFromConversation(group) }),
  });
  await refreshSessionCollections();
  renderAll();
}

async function addSessionToCollection(collectionId, session) {
  if (!collectionId || collectionId === 'default' || !session) {
    return;
  }
  const item = buildCollectionItemFromSession(session);
  if (!item) {
    return;
  }
  await fetchJson(`/api/session-collections/${encodeURIComponent(collectionId)}/items`, {
    method: 'POST',
    body: JSON.stringify({ item }),
  });
  await refreshSessionCollections();
}

async function removeConversationFromCollection(collectionId, group) {
  if (!collectionId || collectionId === DEFAULT_COLLECTION_ID || collectionId === TRASH_COLLECTION_ID) {
    return;
  }
  await fetchJson(`/api/session-collections/${encodeURIComponent(collectionId)}/items/remove`, {
    method: 'POST',
    body: JSON.stringify({ item: buildCollectionItemFromConversation(group) }),
  });
  await refreshSessionCollections();
  renderAll();
}

async function previewConversationTrash(group) {
  const response = await fetchJson('/api/session-collections/trash/preview', {
    method: 'POST',
    body: JSON.stringify({ item: buildCollectionItemFromConversation(group) }),
  });
  return response;
}

async function moveConversationToTrash(group) {
  const response = await fetchJson('/api/session-collections/trash/items', {
    method: 'POST',
    body: JSON.stringify({ item: buildCollectionItemFromConversation(group) }),
  });
  await refreshSessionCollections();
  renderAll();
  return response;
}

async function restoreConversationFromTrash(group) {
  const response = await fetchJson('/api/session-collections/trash/items/restore', {
    method: 'POST',
    body: JSON.stringify({ item: buildCollectionItemFromConversation(group) }),
  });
  await refreshSessionCollections();
  renderAll();
  return response;
}

async function emptyTrashCollection() {
  const response = await fetchJson('/api/session-collections/trash/empty', {
    method: 'POST',
    body: JSON.stringify({}),
  });
  await refreshSessionCollections();
  renderAll();
  return response;
}

function getLiveSessionForConversation(conversation) {
  return conversation?.sessions.find((session) => session.live) || null;
}

function getSelectedConversation() {
  if (!state.selectedHostId || !state.selectedConversationKey) {
    return null;
  }

  return getConversationGroups(state.selectedHostId)
    .find((group) => group.conversationKey === state.selectedConversationKey) || null;
}

function getSelectedSession() {
  const conversation = getSelectedConversation();
  if (!conversation) {
    return null;
  }

  return conversation.sessions.find((session) => session.sessionId === state.selectedSessionId)
    || conversation.preferredSession
    || null;
}

function ensureSelections() {
  if (!state.selectedHostId || !getHost(state.selectedHostId)) {
    const fallbackHost = state.hosts.find((host) => host.online) || state.hosts[0] || null;
    state.selectedHostId = fallbackHost?.hostId || null;
  }

  if (!state.selectedHostId) {
    state.selectedConversationKey = null;
    state.selectedSessionId = null;
    return;
  }

  const groups = getConversationGroups(state.selectedHostId);
  if (!groups.length) {
    state.selectedConversationKey = null;
    state.selectedSessionId = null;
    return;
  }

  let conversation = groups.find((group) => group.conversationKey === state.selectedConversationKey) || null;
  if (!conversation) {
    conversation = groups[0];
    state.selectedConversationKey = conversation.conversationKey;
  }

  const session = conversation.sessions.find((item) => item.sessionId === state.selectedSessionId) || conversation.preferredSession;
  state.selectedSessionId = session?.sessionId || null;
}

function mergeSession(session) {
  if (!session || !session.hostId || !session.sessionId) {
    return null;
  }

  const nextSession = applyManualSessionTitle(session);
  const key = makeSessionKey(session.hostId, session.sessionId);
  const index = state.sessions.findIndex((item) => makeSessionKey(item.hostId, item.sessionId) === key);
  if (index === -1) {
    state.sessions.push(nextSession);
    return nextSession;
  }

  const existing = state.sessions[index];
  if (
    existing?.live
    && existing.source === 'managed'
    && nextSession.live === false
    && nextSession.source !== 'managed'
  ) {
    nextSession.live = true;
    nextSession.source = existing.source;
    nextSession.state = existing.state || 'running';
    nextSession.runtime = existing.runtime || nextSession.runtime || null;
  }

  state.sessions[index] = {
    ...existing,
    ...nextSession,
  };
  return state.sessions[index];
}

function structuredSessionError(error) {
  if (!error) {
    return null;
  }
  return {
    code: error.code || error.body?.code || 'session_request_failed',
    error: error.message || error.body?.error || 'Session request failed.',
    stage: error.stage || error.body?.stage || null,
    sessionBinding: error.sessionBinding || error.body?.sessionBinding || null,
    submittedBinding: error.submittedBinding || error.body?.submittedBinding || null,
    canRebind: Boolean(error.canRebind || error.body?.canRebind),
    canTranscriptFallback: Boolean(error.canTranscriptFallback || error.body?.canTranscriptFallback),
  };
}

function sessionRuntimeProjectionRunId(session) {
  return String(
    session?.runtimeConfig?.runId
    || session?.runtimeConfig?.activeRunId
    || session?.activeRunId
    || session?.runId
    || ''
  ).trim();
}

function runtimeConfigResponseRunId(response) {
  const runId = String(response?.runId || '').trim();
  if (runId) {
    return runId;
  }
  return response?.runStatus === 'live'
    ? String(response?.activeRunId || '').trim()
    : '';
}

function isTerminalSessionLifecycleState(session) {
  const stateText = String(session?.state || '').trim().toLowerCase();
  return Boolean(
    session
    && session.live !== true
    && (
      session.resumeError
      || /^(?:failed(?::|$)|exited(?::|$)|history-only$|stopped$|closed$)/.test(stateText)
    )
  );
}

function canApplyCanonicalRuntimeFallback(target, response, expectedRunId, options = {}) {
  if (!expectedRunId) {
    return false;
  }
  const pendingRun = response?.pendingRun || null;
  if (pendingRun?.status === 'pending') {
    return false;
  }
  if (isTerminalSessionLifecycleState(target)) {
    return true;
  }
  if (options.allowRebindFallback !== true || response?.canRebind !== true) {
    return false;
  }
  const projectedBinding = target?.runtimeConfig && Object.prototype.hasOwnProperty.call(target.runtimeConfig, 'apiBinding')
    ? target.runtimeConfig.apiBinding
    : target?.runtimeConfig?.sessionBinding || target?.apiBinding || null;
  return target?.live === true
    && !projectedBinding?.bindingFingerprint
    && Boolean(runtimeConfigResponseRunId(response))
    && Boolean(String(response?.runStatus || '').trim());
}

function applySessionRuntimeConfig(requestSessionKey, response, expectedRunId = '', options = {}) {
  const target = state.sessions.find((session) => getSessionKey(session) === requestSessionKey) || null;
  if (!target || !response || typeof response !== 'object') {
    return null;
  }
  if (expectedRunId && sessionRuntimeProjectionRunId(target) !== expectedRunId) {
    return null;
  }
  if (
    expectedRunId
    && runtimeConfigResponseRunId(response) !== expectedRunId
    && !(options.acceptCanonicalRunChange === true && runtimeConfigResponseRunId(response))
    && !canApplyCanonicalRuntimeFallback(target, response, expectedRunId, options)
  ) {
    return null;
  }
  const apiBinding = Object.prototype.hasOwnProperty.call(response, 'apiBinding')
    ? response.apiBinding ?? null
    : Object.prototype.hasOwnProperty.call(response, 'sessionBinding')
      ? response.sessionBinding ?? null
      : target.runtimeConfig?.apiBinding ?? target.runtimeConfig?.sessionBinding ?? null;
  const responseSessionBinding = Object.prototype.hasOwnProperty.call(response, 'sessionBinding')
    ? response.sessionBinding ?? null
    : apiBinding;
  return mergeSession({
    ...target,
    runtimeConfig: {
      ...response,
      apiBinding,
      sessionBinding: responseSessionBinding,
    },
    runtimeConfigError: null,
    apiBinding,
    activeRunId: Object.prototype.hasOwnProperty.call(response, 'activeRunId')
      ? response.activeRunId ?? null
      : target.activeRunId ?? null,
    latestSuccessfulRunId: Object.prototype.hasOwnProperty.call(response, 'latestSuccessfulRunId')
      ? response.latestSuccessfulRunId ?? null
      : target.latestSuccessfulRunId ?? null,
    runId: Object.prototype.hasOwnProperty.call(response, 'runId')
      ? response.runId ?? null
      : target.runId ?? null,
    requestedSelection: Object.prototype.hasOwnProperty.call(response, 'requestedSelection')
      ? response.requestedSelection ?? null
      : target.requestedSelection ?? null,
    effectiveSelection: Object.prototype.hasOwnProperty.call(response, 'effectiveSelection')
      ? response.effectiveSelection ?? null
      : target.effectiveSelection ?? null,
  });
}

function sessionWithInvalidatedRuntimeConfig(session, patch = {}) {
  const next = {
    ...(session || {}),
    ...(patch || {}),
  };
  if (!Object.prototype.hasOwnProperty.call(patch || {}, 'runtimeConfig')) {
    next.runtimeConfig = null;
  }
  next.runtimeConfigError = null;
  return next;
}

function captureSessionLifecycleExpectation(session) {
  const runtimeConfig = session?.runtimeConfig && typeof session.runtimeConfig === 'object'
    ? session.runtimeConfig
    : null;
  const binding = runtimeConfig && Object.prototype.hasOwnProperty.call(runtimeConfig, 'apiBinding')
    ? runtimeConfig.apiBinding
    : runtimeConfig?.sessionBinding || null;
  return {
    sessionKey: getSessionKey(session),
    hostId: String(session?.hostId || ''),
    sessionId: String(session?.sessionId || ''),
    expectedRunId: String(runtimeConfig?.runId || '').trim() || null,
    expectedRunStatus: String(runtimeConfig?.runStatus || '').trim() || null,
    expectedBindingFingerprint: String(binding?.bindingFingerprint || '').trim() || null,
  };
}

async function loadStableCanonicalSessionForRebind(session, options = {}) {
  const sessionKey = getSessionKey(session);
  const maxAttempts = Math.max(1, Math.min(3, Number(options.maxAttempts || 3) || 3));
  let candidate = state.sessions.find((item) => getSessionKey(item) === sessionKey) || session;
  let lastError = null;
  for (let attempt = 0; attempt < maxAttempts; attempt += 1) {
    try {
      const canonical = await loadSessionRuntimeConfigForSession(candidate, {
        allowRebindFallback: true,
        acceptCanonicalRunChange: true,
      });
      if (canonical) {
        return canonical;
      }
    } catch (error) {
      lastError = error;
    }
    candidate = state.sessions.find((item) => getSessionKey(item) === sessionKey) || candidate;
    if (attempt + 1 < maxAttempts) {
      await delay(40 * (attempt + 1));
    }
  }
  if (lastError) {
    throw lastError;
  }
  throw sessionContractError(
    'session_run_state_conflict',
    'Canonical Session runtime configuration kept changing before Rebind could start.'
  );
}

function apiResponsesEndpoint(baseUrl) {
  const normalized = normalizeApiIdentityBaseUrl(baseUrl);
  if (!normalized) {
    return '';
  }
  try {
    const url = new URL(normalized);
    url.hash = '';
    url.pathname = `${url.pathname.replace(/\/+$/, '')}/responses`;
    return url.toString();
  } catch (_) {
    return `${normalized.replace(/\/+$/, '')}/responses`;
  }
}

function rebindTargetSummary(profileId, apiConfig = null) {
  if (String(profileId || '') === '__host_environment__') {
    return browserSafeRebindTarget({
      kind: 'host_environment',
      label: 'Host environment',
      responsesEndpoint: 'Host-resolved /responses endpoint',
    });
  }
  const baseUrl = effectiveApiBaseUrl(apiConfig || {});
  return browserSafeRebindTarget({
    kind: 'profile',
    profileId: apiConfig?.profileId || profileId || null,
    label: apiConfig?.label || apiConfig?.provider || profileId || 'API profile',
    provider: apiConfig?.provider || null,
    providerKind: apiConfig?.providerKind || inferApiProviderKind(apiConfig || {}),
    baseUrl,
    responsesEndpoint: apiResponsesEndpoint(baseUrl),
  });
}

function rebindTargetMatchesBinding(binding, target) {
  return target?.kind === 'host_environment'
    ? binding?.kind === 'host_environment'
    : apiBindingMatchesProfileIdentity(binding, target);
}

function rebindTargetDisplayLabel(target) {
  return target?.kind === 'host_environment'
    ? t('session.hostEnvironment')
    : target?.label || target?.provider || 'API profile';
}

function apiBindingConfirmationLabel(binding) {
  const safe = browserSafeApiBinding(binding);
  if (!safe) {
    return t('session.unknownApiBinding');
  }
  const label = safe.kind === 'host_environment'
    ? safe.label || safe.provider || safe.modelProviderHint || t('session.hostEnvironment')
    : safe.label || safe.provider || safe.profileId || 'API profile';
  const baseUrl = effectiveApiBaseUrl(safe);
  const endpoint = apiResponsesEndpoint(baseUrl);
  return endpoint ? `${label} (${endpoint})` : label;
}

function rebindSelectionDisplayValue(selection, key, selectionSource) {
  if (Object.prototype.hasOwnProperty.call(selection || {}, key)) {
    return String(selection[key] || '').trim() || 'Auto / default';
  }
  return selectionSource === 'current-session' ? 'Keep current' : 'Auto / default';
}

function formatSessionRebindConfirmation(previousBinding, target, selection = {}, selectionSource = 'current-session') {
  const sourceLabel = 'Current Session settings';
  return [
    t('session.rebindConfirmTitle'),
    '',
    formatUiText('session.rebindConfirmFrom', { binding: apiBindingConfirmationLabel(previousBinding) }),
    formatUiText('session.rebindConfirmTo', { binding: rebindTargetDisplayLabel(target) }),
    formatUiText('session.rebindConfirmEndpoint', {
      endpoint: target?.responsesEndpoint || t('session.endpointUnavailable'),
    }),
    t('session.rebindRestartWarning'),
    `Run settings: ${sourceLabel}`,
    `Model: ${rebindSelectionDisplayValue(selection, 'model', selectionSource)}`,
    `Thinking: ${rebindSelectionDisplayValue(selection, 'effort', selectionSource)}`,
    `Summary: ${rebindSelectionDisplayValue(selection, 'summary', selectionSource)}`,
  ].join('\n');
}

function recordSessionRebindFailure(session, previousBinding, target, error) {
  const key = getSessionKey(session);
  const safePreviousBinding = browserSafeApiBinding(previousBinding || {
    kind: 'unknown',
    label: 'Unknown previous binding',
  });
  const safeTarget = browserSafeRebindTarget(target);
  if (!key || !safePreviousBinding || !safeTarget) {
    return null;
  }
  const failure = {
    hostId: String(session.hostId || '').trim().slice(0, 180),
    sessionId: String(session.sessionId || '').trim().slice(0, 180),
    failedAt: new Date().toISOString(),
    previousBinding: safePreviousBinding,
    target: safeTarget,
    errorCode: String(error?.code || error?.body?.code || 'session_rebind_failed').trim().slice(0, 120),
  };
  state.sessionRebindFailures.set(key, failure);
  persistSessionRebindFailures();
  return failure;
}

function clearSessionRebindFailure(session) {
  const key = getSessionKey(session);
  if (!key || !state.sessionRebindFailures.delete(key)) {
    return false;
  }
  persistSessionRebindFailures();
  return true;
}

function confirmResumeAfterFailedRebind(session) {
  const key = getSessionKey(session);
  const failure = key ? state.sessionRebindFailures.get(key) || null : null;
  if (!failure) {
    return true;
  }
  const confirmed = window.confirm([
    formatUiText('session.rebindFailed', { target: rebindTargetDisplayLabel(failure.target) }),
    formatUiText('session.rebindResumePrevious', {
      binding: apiBindingConfirmationLabel(failure.previousBinding),
    }),
    t('session.rebindContinue'),
  ].join('\n'));
  if (confirmed) {
    clearSessionRebindFailure(session);
  }
  return confirmed;
}

async function loadCanonicalSessionForLifecycleMutation(session) {
  const sessionKey = getSessionKey(session);
  const current = state.sessions.find((candidate) => getSessionKey(candidate) === sessionKey) || session;
  const canonical = await loadSessionRuntimeConfigForSession(current);
  if (!canonical) {
    throw sessionContractError(
      'session_run_state_conflict',
      'Canonical Session runtime configuration changed before the lifecycle request could start.'
    );
  }
  return canonical;
}

function applyRebindLaunchResponse(expectation, response, fallbackSession = null) {
  if (
    !expectation?.sessionKey
    || !response
    || String(response.sessionId || '') !== expectation.sessionId
    || (response.hostId && String(response.hostId) !== expectation.hostId)
  ) {
    return null;
  }
  const responseRunId = String(response.runId || '').trim();
  if (!responseRunId) {
    return null;
  }
  const current = state.sessions.find((candidate) => getSessionKey(candidate) === expectation.sessionKey)
    || fallbackSession;
  if (!current || getSessionKey(current) !== expectation.sessionKey) {
    return null;
  }
  const currentRunId = String(
    current.runtimeConfig?.runId
    || current.activeRunId
    || current.runId
    || ''
  ).trim();
  if (currentRunId && currentRunId !== expectation.expectedRunId) {
    return currentRunId === responseRunId ? current : null;
  }
  return mergeSession(sessionWithInvalidatedRuntimeConfig(current, {
    state: 'starting',
    live: false,
    runId: responseRunId,
    activeRunId: responseRunId,
    apiBinding: response.sessionBinding || current.apiBinding || null,
    requestedSelection: response.requestedSelection || current.requestedSelection || null,
    resumeError: null,
  }));
}

function applyConfirmedSessionStarted(payload, fallbackSession = null) {
  const hostId = payload?.hostId || fallbackSession?.hostId || '';
  const sessionId = payload?.sessionId || fallbackSession?.sessionId || '';
  const requestSessionKey = getSessionKey({ hostId, sessionId });
  const current = state.sessions.find((candidate) => getSessionKey(candidate) === requestSessionKey)
    || fallbackSession
    || {};
  const started = mergeSession(sessionWithInvalidatedRuntimeConfig(current, {
    ...(payload || {}),
    hostId,
    sessionId,
  }));
  if (started?.hostId && started?.sessionId) {
    const failure = state.sessionRebindFailures.get(getSessionKey(started)) || null;
    if (failure && rebindTargetMatchesBinding(sessionApiBinding(started), failure.target)) {
      clearSessionRebindFailure(started);
    }
    void loadSessionRuntimeConfigForSession(started).catch(() => {});
  }
  return started;
}

async function loadSessionRuntimeConfigForSession(session, options = {}) {
  const requestSessionKey = getSessionKey(session);
  const expectedRunId = sessionRuntimeProjectionRunId(session);
  if (!requestSessionKey || !session?.hostId || !session?.sessionId) {
    return null;
  }
  try {
    const response = await fetchJson(`/api/sessions/${encodeURIComponent(session.sessionId)}/runtime-config?hostId=${encodeURIComponent(session.hostId)}`);
    const updated = applySessionRuntimeConfig(requestSessionKey, response, expectedRunId, options);
    if (updated && getSessionKey(getSelectedSession()) === requestSessionKey) {
      renderSessionDetails();
      renderSessionApiControls(updated);
    }
    return updated;
  } catch (error) {
    const target = state.sessions.find((candidate) => getSessionKey(candidate) === requestSessionKey) || null;
    const requestStillCurrent = target
      && (!expectedRunId || sessionRuntimeProjectionRunId(target) === expectedRunId);
    if (requestStillCurrent) {
      mergeSession({ ...target, runtimeConfigError: structuredSessionError(error) });
    }
    if (requestStillCurrent && getSessionKey(getSelectedSession()) === requestSessionKey) {
      renderSessionApiControls(target);
    }
    throw error;
  }
}

function setTranscriptForSession(hostId, sessionId, transcript) {
  const key = makeSessionKey(hostId, sessionId);
  state.transcripts.set(key, dedupeTranscript(transcript).filter((entry) => (
    !transcriptEntryIsTombstoned(key, entry)
  )));
}

function appendTranscriptEntry(hostId, sessionId, entry) {
  const key = makeSessionKey(hostId, sessionId);
  if (transcriptEntryIsTombstoned(key, entry)) {
    return false;
  }
  const existing = state.transcripts.get(key) || [];
  state.transcripts.set(key, dedupeTranscript([...existing, entry]));
  return true;
}

const TRANSCRIPT_TOMBSTONE_TTL_MS = 10 * 60 * 1000;
const TRANSCRIPT_TOMBSTONE_LIMIT = 64;

function pruneTranscriptTombstones(sessionKey) {
  if (!(state.transcriptTombstones instanceof Map)) state.transcriptTombstones = new Map();
  const existing = state.transcriptTombstones.get(sessionKey) || new Map();
  const cutoff = Date.now() - TRANSCRIPT_TOMBSTONE_TTL_MS;
  for (const [requestId, removedAt] of existing.entries()) {
    if (Number(removedAt || 0) < cutoff) existing.delete(requestId);
  }
  while (existing.size > TRANSCRIPT_TOMBSTONE_LIMIT) {
    existing.delete(existing.keys().next().value);
  }
  if (existing.size) state.transcriptTombstones.set(sessionKey, existing);
  else state.transcriptTombstones.delete(sessionKey);
  return existing;
}

function transcriptEntryIsTombstoned(sessionKey, entry) {
  const clientRequestId = String(entry?.clientRequestId || '').trim();
  if (!sessionKey || !clientRequestId || String(entry?.speaker || '').toLowerCase() !== 'user') {
    return false;
  }
  return pruneTranscriptTombstones(sessionKey).has(clientRequestId);
}

function removeTranscriptEntry(hostId, sessionId, identity = {}) {
  const key = makeSessionKey(hostId, sessionId);
  const clientRequestId = String(identity.clientRequestId || '').trim();
  const speaker = String(identity.speaker || 'user').toLowerCase();
  if (!key || !clientRequestId || speaker !== 'user') return false;
  const tombstones = pruneTranscriptTombstones(key);
  tombstones.set(clientRequestId, Date.now());
  state.transcriptTombstones.set(key, tombstones);
  const existing = state.transcripts.get(key) || [];
  const next = existing.filter((entry) => !(
    String(entry?.speaker || '').toLowerCase() === speaker
    && String(entry?.clientRequestId || '').trim() === clientRequestId
  ));
  state.transcripts.set(key, next);
  return next.length !== existing.length;
}

function composerTracksTranscriptRequest(sessionKey, clientRequestId) {
  const key = resolveComposerSessionKey(sessionKey);
  const requestId = String(clientRequestId || '').trim();
  if (!key || !requestId) return false;
  const submission = state.codexControls.composerSubmissionsBySession.get(key) || null;
  const activeDraft = state.codexControls.activeDraftsBySession.get(key) || null;
  const sentDraft = state.codexControls.sentDraftSnapshotsBySession.get(key) || null;
  return submission?.id === requestId
    || activeDraft?.clientRequestId === requestId
    || sentDraft?.clientRequestId === requestId;
}

function reconcileDetailTranscriptForSession(hostId, sessionId, serverTranscript, localTranscript, options = {}) {
  const key = makeSessionKey(hostId, sessionId);
  const serverEntries = dedupeTranscript(serverTranscript);
  if (options.authoritative !== true) {
    return dedupeTranscript([...serverEntries, ...(localTranscript || [])]);
  }

  const serverRequestKeys = new Set(serverEntries
    .filter((entry) => entry.clientRequestId)
    .map((entry) => `${String(entry.speaker || '').toLowerCase()}|${String(entry.clientRequestId).trim()}`));
  const runtime = options.runtime && typeof options.runtime === 'object' ? options.runtime : {};
  const runtimeRequestId = String(runtime.clientRequestId || runtime.pendingClientRequestId || '').trim();
  const nowMs = Number(options.nowMs || Date.now());
  const retainedLocalEntries = dedupeTranscript(localTranscript).filter((entry) => {
    const speaker = String(entry?.speaker || '').toLowerCase();
    const requestId = String(entry?.clientRequestId || '').trim();
    if (requestId && serverRequestKeys.has(`${speaker}|${requestId}`)) {
      return false;
    }
    if (speaker !== 'user' || !requestId || entry.deliveryStatus !== 'pending') {
      return true;
    }
    if (transcriptEntryIsTombstoned(key, entry)) {
      return false;
    }
    const timestampMs = Date.parse(entry.timestamp || '');
    const fresh = Number.isFinite(timestampMs)
      && nowMs >= timestampMs
      && nowMs - timestampMs <= OPTIMISTIC_TRANSCRIPT_GRACE_MS;
    return Boolean(
      fresh
      && runtimeRequestId === requestId
      && runtimeIsActive(runtime)
      && composerTracksTranscriptRequest(key, requestId)
    );
  });
  return dedupeTranscript([...serverEntries, ...retainedLocalEntries]);
}

function normalizeAssistantProjection(projection = {}, fallbackCanonicalKey = '') {
  const messages = Array.isArray(projection.messages)
    ? projection.messages.filter((message) => message?.assistantMessageId)
    : [];
  return {
    canonicalConversationKey: String(
      projection.canonicalConversationKey || fallbackCanonicalKey || ''
    ).trim(),
    latestAssistantSeq: Math.max(0, Number(projection.latestAssistantSeq || 0)),
    latestAssistantId: projection.latestAssistantId || null,
    latestAssistantAt: projection.latestAssistantAt || null,
    projectionRevision: Math.max(0, Number(projection.projectionRevision || 0)),
    cursorUnknown: projection.cursorUnknown === true,
    sequenceAliases: projection.sequenceAliases && typeof projection.sequenceAliases === 'object'
      ? { ...projection.sequenceAliases }
      : {},
    aliases: [...new Set((projection.aliases || []).map((value) => String(value || '').trim()).filter(Boolean))],
    messages,
    hasMore: projection.hasMore === true,
    nextAfterSeq: Math.max(0, Number(projection.nextAfterSeq || 0)),
  };
}

function mergeAssistantProjection(currentValue, incomingValue) {
  const incoming = normalizeAssistantProjection(incomingValue);
  if (!currentValue || typeof currentValue !== 'object') {
    return incoming;
  }
  const current = normalizeAssistantProjection(currentValue, incoming.canonicalConversationKey);
  if (
    current.canonicalConversationKey
    && incoming.canonicalConversationKey
    && current.canonicalConversationKey !== incoming.canonicalConversationKey
  ) {
    return incoming;
  }
  if (incoming.projectionRevision < current.projectionRevision) {
    return current;
  }
  if (incoming.projectionRevision > current.projectionRevision) {
    return incoming;
  }
  const messages = new Map();
  for (const message of [...current.messages, ...incoming.messages]) {
    messages.set(message.assistantMessageId, { ...(messages.get(message.assistantMessageId) || {}), ...message });
  }
  return {
    canonicalConversationKey: incoming.canonicalConversationKey || current.canonicalConversationKey,
    latestAssistantSeq: Math.max(current.latestAssistantSeq, incoming.latestAssistantSeq),
    latestAssistantId: incoming.latestAssistantId || current.latestAssistantId,
    latestAssistantAt: incoming.latestAssistantAt || current.latestAssistantAt,
    projectionRevision: Math.max(current.projectionRevision, incoming.projectionRevision),
    cursorUnknown: incoming.cursorUnknown && current.cursorUnknown,
    sequenceAliases: { ...current.sequenceAliases, ...incoming.sequenceAliases },
    aliases: [...new Set([...current.aliases, ...incoming.aliases])],
    messages: [...messages.values()].sort((left, right) => (
      Number(left.assistantSeq || 0) - Number(right.assistantSeq || 0)
      || String(left.assistantMessageId).localeCompare(String(right.assistantMessageId))
    )),
    hasMore: incoming.hasMore,
    nextAfterSeq: Math.max(current.nextAfterSeq, incoming.nextAfterSeq),
  };
}

function getAssistantProjectionForSession(session) {
  if (!session) return null;
  const sessionKey = getSessionKey(session);
  const canonicalKey = state.assistantCanonicalKeysBySession.get(sessionKey)
    || session.assistantProjection?.canonicalConversationKey
    || '';
  const retained = canonicalKey ? state.assistantProjections.get(canonicalKey) : null;
  if (retained) return retained;
  if (session.assistantProjection?.canonicalConversationKey) {
    return normalizeAssistantProjection(session.assistantProjection);
  }
  return null;
}

function rememberAssistantProjection(session, projectionValue) {
  const projection = normalizeAssistantProjection(projectionValue);
  const canonicalKey = projection.canonicalConversationKey;
  const sessionKey = getSessionKey(session);
  if (!canonicalKey || !sessionKey) return projection;
  const merged = mergeAssistantProjection(state.assistantProjections.get(canonicalKey), projection);
  state.assistantProjections.set(canonicalKey, merged);
  state.assistantCanonicalKeysBySession.set(sessionKey, canonicalKey);
  return merged;
}

function messageReceiptKeys(session, projection) {
  return [...new Set([
    projection?.canonicalConversationKey,
    ...(projection?.aliases || []),
    getSessionKey(session),
  ].map((value) => String(value || '').trim()).filter(Boolean))];
}

function receiptForAssistantProjection(session, projection) {
  const client = window.MessageNotificationClient;
  const store = state.messageReceiptStore;
  const canonicalKey = projection?.canonicalConversationKey || '';
  if (!client || !store || !canonicalKey) return null;
  const keys = messageReceiptKeys(session, projection);
  const stored = keys.filter((key) => store.has(key)).map((key) => store.get(key));
  if (!stored.length) {
    const legacy = keys.map((key) => state.legacyMessageReadReceipts?.[key]).find(Boolean);
    if (legacy) {
      return client.migrateLegacyReceipt(legacy, {
        canonicalConversationKey: canonicalKey,
        messages: projection.messages,
        baselineHighWater: projection.latestAssistantSeq,
      });
    }
    return store.get(canonicalKey);
  }
  return client.mergeAliasReceipts({
    canonicalConversationKey: canonicalKey,
    receipts: stored,
    messages: projection.messages,
    sequenceAliases: projection.sequenceAliases,
  });
}

function persistAssistantReceipt(receipt, projection, session = null) {
  const store = state.messageReceiptStore;
  if (!store || !receipt?.canonicalConversationKey) return receipt;
  let saved = null;
  const persist = () => {
    saved = store.set(receipt);
    const aliases = [...new Set([...(projection?.aliases || []), getSessionKey(session)].filter(Boolean))];
    for (const alias of aliases) {
      if (!alias || alias === saved.canonicalConversationKey || !store.has(alias)) continue;
      store.set({ ...saved, canonicalConversationKey: alias });
    }
  };
  if (typeof store.batch === 'function') {
    store.batch(persist);
  } else {
    persist();
  }
  return saved;
}

function broadcastMessageNotificationState(type, payload = {}) {
  state.messageNotificationChannel?.postMessage?.({ type, ...payload });
}

function openMessageNotificationLockDb() {
  if (state.messageNotificationLockDbPromise) return state.messageNotificationLockDbPromise;
  const indexedDb = window.indexedDB;
  if (!indexedDb?.open) return Promise.resolve(null);
  state.messageNotificationLockDbPromise = new Promise((resolve, reject) => {
    let request = null;
    try {
      request = indexedDb.open(MESSAGE_NOTIFICATION_LOCK_DB_NAME, 1);
    } catch (error) {
      reject(error);
      return;
    }
    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(MESSAGE_NOTIFICATION_LOCK_STORE_NAME)) {
        db.createObjectStore(MESSAGE_NOTIFICATION_LOCK_STORE_NAME);
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error || new Error('Notification lock database failed to open'));
    request.onblocked = () => reject(new Error('Notification lock database upgrade is blocked'));
  }).catch((error) => {
    state.messageNotificationLockDbPromise = null;
    reportError(error);
    return null;
  });
  return state.messageNotificationLockDbPromise;
}

async function runMessageNotificationStorageTransaction(key, callback) {
  if (window.navigator?.locks?.request) {
    return window.navigator.locks.request(key, { mode: 'exclusive' }, callback);
  }
  const db = await openMessageNotificationLockDb();
  if (!db) return callback();
  return new Promise((resolve, reject) => {
    let transaction = null;
    let result;
    let failure = null;
    try {
      transaction = db.transaction(MESSAGE_NOTIFICATION_LOCK_STORE_NAME, 'readwrite');
      const store = transaction.objectStore(MESSAGE_NOTIFICATION_LOCK_STORE_NAME);
      const request = store.get(key);
      request.onsuccess = () => {
        try {
          result = callback();
          if (result && typeof result.then === 'function') {
            throw new TypeError('Notification storage critical sections must be synchronous');
          }
          store.put(Date.now(), key);
        } catch (error) {
          failure = error;
          transaction.abort();
        }
      };
      request.onerror = () => {
        failure = request.error || new Error('Notification storage lock request failed');
        transaction.abort();
      };
    } catch (error) {
      reject(error);
      return;
    }
    transaction.oncomplete = () => resolve(result);
    transaction.onabort = () => reject(
      failure || transaction.error || new Error('Notification storage transaction aborted')
    );
  });
}

function isMessageNotificationQuotaError(error) {
  return window.MessageNotificationClient?.isQuotaExceededError?.(error) === true;
}

function scheduleMessageNotificationStoreRetry(kind) {
  const isReceipt = kind === 'receipt';
  const timerField = isReceipt ? 'messageReceiptPersistRetryTimer' : 'messageOutboxPersistRetryTimer';
  const attemptField = isReceipt ? 'messageReceiptPersistRetryAttempt' : 'messageOutboxPersistRetryAttempt';
  if (state[timerField]) return;
  const attempt = Math.max(0, Number(state[attemptField] || 0));
  const delayMs = Math.min(10000, 250 * (2 ** Math.min(attempt, 6)));
  state[attemptField] = attempt + 1;
  state[timerField] = window.setTimeout(async () => {
    state[timerField] = null;
    const store = isReceipt ? state.messageReceiptStore : state.messageNotificationOutbox;
    try {
      await Promise.resolve(store?.flush?.());
      if (!isReceipt) void requestMessageNotificationOutboxDrain();
    } catch (error) {
      if (isMessageNotificationQuotaError(error)) {
        resetMessageNotificationStoreRetry(kind);
        return;
      }
      reportError(error);
      scheduleMessageNotificationStoreRetry(kind);
    }
  }, delayMs);
}

function resetMessageNotificationStoreRetry(kind) {
  const isReceipt = kind === 'receipt';
  const timerField = isReceipt ? 'messageReceiptPersistRetryTimer' : 'messageOutboxPersistRetryTimer';
  const attemptField = isReceipt ? 'messageReceiptPersistRetryAttempt' : 'messageOutboxPersistRetryAttempt';
  if (state[timerField]) window.clearTimeout(state[timerField]);
  state[timerField] = null;
  state[attemptField] = 0;
}

function scheduleMessageNotificationBroadcastFlush(type = '') {
  const normalizedType = String(type || '').trim();
  if (normalizedType === 'receipts-changed' || normalizedType === 'outbox-changed') {
    state.messageNotificationBroadcastTypes.add(normalizedType);
  } else {
    state.messageNotificationBroadcastTypes.add('receipts-changed');
    state.messageNotificationBroadcastTypes.add('outbox-changed');
  }
  if (state.messageNotificationBroadcastTimer) return;
  state.messageNotificationBroadcastTimer = window.setTimeout(() => {
    state.messageNotificationBroadcastTimer = null;
    const changedTypes = new Set(state.messageNotificationBroadcastTypes);
    state.messageNotificationBroadcastTypes.clear();
    if (changedTypes.has('receipts-changed')) {
      state.messageReceiptStore?.reload?.();
      refreshMessageUnreadState();
      queuedUiRenders.messageNotificationBell = true;
      queuedUiRenders.conversationNav = true;
      scheduleQueuedUiFlush();
    }
    if (changedTypes.has('outbox-changed')) {
      state.messageNotificationOutbox?.reload?.();
      void requestMessageNotificationOutboxDrain();
    }
  }, MESSAGE_NOTIFICATION_BROADCAST_DEBOUNCE_MS);
}

function notificationOutboxPresenters() {
  const sessionsByKey = new Map((state.sessions || []).map((session) => [
    getSessionKey(session),
    session,
  ]));
  const advanceNotifiedItem = (item) => {
    const client = window.MessageNotificationClient;
    const projection = state.assistantProjections.get(item.canonicalConversationKey)
      || normalizeAssistantProjection({ canonicalConversationKey: item.canonicalConversationKey });
    const receipt = state.messageReceiptStore?.get(item.canonicalConversationKey);
    if (!client || !receipt) return;
    const session = sessionsByKey.get(makeSessionKey(item.hostId, item.sessionId)) || null;
    persistAssistantReceipt(client.advanceNotifiedReceipt(receipt, projection, item), projection, session);
  };
  return {
    presentInApp: async () => {
      queuedUiRenders.messageNotificationBell = true;
      queuedUiRenders.conversationNav = true;
      scheduleQueuedUiFlush();
    },
    presentSystem: async (item) => {
      const NotificationApi = window.Notification;
      if (!NotificationApi || NotificationApi.permission !== 'granted') {
        return { explicitlyUnavailable: true };
      }
      try {
        const session = sessionsByKey.get(makeSessionKey(item.hostId, item.sessionId)) || null;
        new NotificationApi(session?.title || 'Codex message', {
          body: item.previewText || 'Codex completed a message.',
          tag: item.alertId,
          renotify: false,
        });
        return { presented: true };
      } catch (_) {
        return { presented: false };
      }
    },
    advanceNotified: async (item) => {
      advanceNotifiedItem(item);
      await state.messageReceiptStore?.whenIdle?.();
    },
    advanceNotifiedBatch: async (items) => {
      const advance = () => {
        for (const item of items || []) advanceNotifiedItem(item);
      };
      if (typeof state.messageReceiptStore?.batch === 'function') {
        state.messageReceiptStore.batch(advance);
      } else {
        advance();
      }
      await state.messageReceiptStore?.whenIdle?.();
    },
  };
}

function drainMessageNotificationOutbox() {
  const client = window.MessageNotificationClient;
  if (!client || !state.messageNotificationOutbox) return Promise.resolve(false);
  if (state.messageNotificationDrainPromise) {
    state.messageNotificationDrainRequested = true;
    return state.messageNotificationDrainPromise;
  }
  state.messageNotificationDrainRequested = false;
  const cycle = client.drainOutboxWithElection({
    navigator: window.navigator,
    storage: window.localStorage,
    ownerId: state.messageNotificationTabId,
    leaseKey: MESSAGE_NOTIFICATION_LEASE_STORAGE_KEY,
    reload: true,
    outbox: state.messageNotificationOutbox,
    presenters: notificationOutboxPresenters(),
  });
  let chain = null;
  chain = cycle.then(
    (result) => {
      if (!state.messageNotificationDrainRequested) return result;
      state.messageNotificationDrainRequested = false;
      state.messageNotificationDrainPromise = null;
      return drainMessageNotificationOutbox();
    },
    (error) => {
      const retryRequested = state.messageNotificationDrainRequested;
      state.messageNotificationDrainRequested = false;
      state.messageNotificationDrainPromise = null;
      if (retryRequested) {
        window.setTimeout(() => void requestMessageNotificationOutboxDrain(), 0);
      }
      throw error;
    }
  ).finally(() => {
    if (state.messageNotificationDrainPromise === chain) {
      state.messageNotificationDrainPromise = null;
    }
  });
  state.messageNotificationDrainPromise = chain;
  return state.messageNotificationDrainPromise;
}

function requestMessageNotificationOutboxDrain() {
  const drain = drainMessageNotificationOutbox();
  if (state.messageNotificationObservedDrainPromise === drain) return drain;
  state.messageNotificationObservedDrainPromise = drain;
  drain.then(
    () => {
      if (state.messageNotificationObservedDrainPromise === drain) {
        state.messageNotificationObservedDrainPromise = null;
      }
    },
    (error) => {
      if (state.messageNotificationObservedDrainPromise === drain) {
        state.messageNotificationObservedDrainPromise = null;
      }
      if (!isMessageNotificationQuotaError(error)) reportError(error);
    }
  );
  return drain;
}

function enqueueAssistantProjectionAlerts(session, projection, receipt) {
  const outbox = state.messageNotificationOutbox;
  if (!outbox || !receipt) return;
  const pendingIds = new Set(receipt.unnotifiedAssistantIds || []);
  let enqueued = false;
  for (const message of projection.messages || []) {
    if (message.notifiable === false || !pendingIds.has(message.assistantMessageId)) continue;
    const queued = outbox.enqueue({
      ...message,
      canonicalConversationKey: projection.canonicalConversationKey,
      hostId: session.hostId,
      sessionId: session.sessionId,
    });
    enqueued = queued.changed === true || enqueued;
  }
  if (enqueued) {
    void requestMessageNotificationOutboxDrain();
  }
}

function applyAssistantProjectionForSession(session, projectionValue, options = {}) {
  const client = window.MessageNotificationClient;
  if (!client || !session || !projectionValue?.canonicalConversationKey) return null;
  const projection = rememberAssistantProjection(session, projectionValue);
  const receipt = receiptForAssistantProjection(session, projection);
  if (!receipt) return null;
  const applied = client.applyAssistantProjection(receipt, projection);
  persistAssistantReceipt(applied.receipt, projection, session);
  enqueueAssistantProjectionAlerts(session, projection, applied.receipt);
  if (!options.deferUnreadRefresh) {
    refreshMessageUnreadState();
  }
  if (!options.deferUi) {
    queuedUiRenders.messageNotificationBell = true;
    queuedUiRenders.conversationNav = true;
    scheduleQueuedUiFlush();
  }
  return { ...applied, projection };
}

function finishAssistantProjectionCatchUp(session, projection, options = {}) {
  return options.deferApply
    ? { projection }
    : applyAssistantProjectionForSession(session, projection);
}

function assistantProjectionFetchStart(session, projection) {
  const receipt = receiptForAssistantProjection(session, projection);
  const legacyPending = messageReceiptKeys(session, projection)
    .some((key) => Boolean(state.legacyMessageReadReceipts?.[key]))
    && !state.messageReceiptStore?.has(projection.canonicalConversationKey);
  const aliasReceipts = messageReceiptKeys(session, projection)
    .some((key) => key !== projection.canonicalConversationKey && state.messageReceiptStore?.has(key));
  if (legacyPending || aliasReceipts || projection.cursorUnknown) return 0;
  return Math.min(
    Number(receipt?.readThroughAssistantSeq || 0),
    Number(receipt?.notifiedThroughAssistantSeq || 0)
  );
}

async function catchUpAssistantProjection(session, seedProjection = null, options = {}) {
  if (!session?.hostId || !session?.sessionId) return null;
  const sessionKey = getSessionKey(session);
  const seed = seedProjection || session.assistantProjection || null;
  if (!seed?.canonicalConversationKey) return null;
  const existingRequest = state.messageProjectionRequests.get(sessionKey);
  if (existingRequest) {
    return existingRequest.then((result) => {
      const requestedRevision = Number(seed.projectionRevision || 0);
      if (requestedRevision > Number(result?.projection?.projectionRevision || 0)) {
        return catchUpAssistantProjection(session, seed, options);
      }
      if (!options.deferApply && result?.projection && !result.receipt) {
        return applyAssistantProjectionForSession(session, result.projection);
      }
      return result;
    });
  }

  const request = (async () => {
    let projection = rememberAssistantProjection(session, seed);
    const startAfter = assistantProjectionFetchStart(session, projection);
    const cachedMax = Math.max(0, ...projection.messages.map((message) => Number(message.assistantSeq || 0)));
    const needsFetch = options.force === true
      || projection.cursorUnknown
      || projection.hasMore
      || (projection.latestAssistantSeq > startAfter && cachedMax < projection.latestAssistantSeq);
    if (!needsFetch) return finishAssistantProjectionCatchUp(session, projection, options);

    let afterSeq = startAfter;
    let candidate = null;
    let candidateIdentity = '';
    let restartCount = 0;
    const restartPagination = () => {
      restartCount += 1;
      if (restartCount > ASSISTANT_PROJECTION_MAX_RESTARTS) {
        const error = new Error('Assistant projection changed too often during pagination.');
        error.code = 'assistant_projection_unstable';
        throw error;
      }
      afterSeq = 0;
      candidate = null;
      candidateIdentity = '';
    };
    try {
      while (true) {
        const params = new URLSearchParams({
          hostId: session.hostId,
          afterSeq: String(afterSeq),
          limit: String(ASSISTANT_PROJECTION_PAGE_LIMIT),
        });
        const pageValue = await fetchJson(`/api/sessions/${encodeURIComponent(session.sessionId)}/assistant-messages?${params.toString()}`);
        const page = normalizeAssistantProjection(pageValue);
        if (!page.canonicalConversationKey) {
          throw new Error('Assistant projection page is missing its canonical conversation key.');
        }
        const pageIdentity = `${page.canonicalConversationKey}\0${page.projectionRevision}`;
        if (candidateIdentity && pageIdentity !== candidateIdentity) {
          restartPagination();
          continue;
        }
        candidate = candidate
          ? mergeAssistantProjection(candidate, page)
          : page;
        candidateIdentity = pageIdentity;
        if (!page.hasMore) {
          const current = getAssistantProjectionForSession(session);
          const currentCanonicalKey = String(current?.canonicalConversationKey || '').trim();
          const currentRevision = Number(current?.projectionRevision || 0);
          if (
            currentCanonicalKey
            && (
              (
                currentCanonicalKey === page.canonicalConversationKey
                && currentRevision > page.projectionRevision
              )
              || (
                currentCanonicalKey !== page.canonicalConversationKey
                && currentCanonicalKey !== projection.canonicalConversationKey
              )
            )
          ) {
            restartPagination();
            continue;
          }
          projection = rememberAssistantProjection(session, candidate);
          break;
        }
        const nextAfter = Number(pageValue?.nextAfterSeq);
        if (!Number.isSafeInteger(nextAfter) || nextAfter <= afterSeq) {
          const error = new Error('Assistant projection pagination cursor did not advance.');
          error.code = 'assistant_projection_cursor_stalled';
          throw error;
        }
        afterSeq = nextAfter;
      }
    } catch (error) {
      throw error;
    }
    return finishAssistantProjectionCatchUp(session, projection, options);
  })().finally(() => {
    if (state.messageProjectionRequests.get(sessionKey) === request) {
      state.messageProjectionRequests.delete(sessionKey);
    }
  });
  state.messageProjectionRequests.set(sessionKey, request);
  return request;
}

async function settleWithConcurrency(items, worker, concurrency = 6) {
  const values = Array.isArray(items) ? items : [];
  const results = new Array(values.length);
  let nextIndex = 0;
  const run = async () => {
    while (nextIndex < values.length) {
      const index = nextIndex;
      nextIndex += 1;
      try {
        results[index] = { status: 'fulfilled', value: await worker(values[index], index) };
      } catch (reason) {
        results[index] = { status: 'rejected', reason };
      }
    }
  };
  const workerCount = Math.min(values.length, Math.max(1, Number(concurrency) || 1));
  await Promise.all(Array.from({ length: workerCount }, () => run()));
  return results;
}

async function syncAssistantProjectionsForSessions(sessions = state.sessions, options = {}) {
  const candidates = (sessions || []).filter((session) => (
    session?.assistantProjection?.canonicalConversationKey
  ));
  const settled = await settleWithConcurrency(candidates, (session) => (
    catchUpAssistantProjection(session, session.assistantProjection, { deferApply: true })
  ), options.concurrency || 6);
  const failures = [];
  const applyResults = () => {
    candidates.forEach((session, index) => {
      const result = settled[index];
      const projection = result?.status === 'fulfilled'
        ? result.value?.projection
        : getAssistantProjectionForSession(session) || session.assistantProjection;
      if (result?.status === 'rejected') failures.push(result.reason);
      if (!projection?.canonicalConversationKey) return;
      try {
        applyAssistantProjectionForSession(session, projection, {
          deferUnreadRefresh: true,
          deferUi: true,
        });
      } catch (error) {
        failures.push(error);
      }
    });
  };
  const applyReceiptBatch = () => {
    if (typeof state.messageReceiptStore?.batch === 'function') {
      state.messageReceiptStore.batch(applyResults);
    } else {
      applyResults();
    }
  };
  if (typeof state.messageNotificationOutbox?.batch === 'function') {
    state.messageNotificationOutbox.batch(applyReceiptBatch);
  } else {
    applyReceiptBatch();
  }
  await Promise.all([
    state.messageReceiptStore?.whenIdle?.(),
    state.messageNotificationOutbox?.whenIdle?.(),
  ]);
  refreshMessageUnreadState();
  if (!options.deferUi) {
    queuedUiRenders.messageNotificationBell = true;
    queuedUiRenders.conversationNav = true;
    scheduleQueuedUiFlush();
  }
  if (failures.length) {
    const error = failures[0] instanceof Error ? failures[0] : new Error(String(failures[0] || 'projection sync failed'));
    error.message = `${error.message} (${failures.length} assistant projection sync failure${failures.length === 1 ? '' : 's'})`;
    throw error;
  }
  return { candidateCount: candidates.length };
}

function scheduleAssistantProjectionSync(sessions = state.sessions) {
  if (state.messageProjectionSyncPromise) return state.messageProjectionSyncPromise;
  const snapshot = [...(sessions || [])];
  state.messageProjectionSyncPromise = new Promise((resolve) => window.setTimeout(resolve, 0))
    .then(() => syncAssistantProjectionsForSessions(snapshot))
    .catch(reportError)
    .finally(() => {
      state.messageProjectionSyncPromise = null;
    });
  return state.messageProjectionSyncPromise;
}

function markSessionMessagesRead(sessionOrHostId, sessionId = null, options = {}) {
  const session = typeof sessionOrHostId === 'object'
    ? sessionOrHostId
    : state.sessions.find((item) => item.hostId === sessionOrHostId && item.sessionId === sessionId);
  const projection = getAssistantProjectionForSession(session);
  const client = window.MessageNotificationClient;
  if (!session || !projection || !client || !state.messageReceiptStore) return false;
  const receipt = receiptForAssistantProjection(session, projection);
  persistAssistantReceipt(client.advanceReadReceipt(receipt, projection, {
    clearAllUnread: options.clearAllUnread === true,
  }), projection, session);
  if (!options.deferUnreadRefresh) {
    refreshMessageUnreadState();
  }
  return true;
}

function updateMessageUnreadForSession(sessionOrHostId, sessionId = null) {
  const session = sessionOrHostId && typeof sessionOrHostId === 'object'
    ? sessionOrHostId
    : state.sessions.find((item) => (
      item.hostId === sessionOrHostId && item.sessionId === sessionId
    )) || null;
  const key = getSessionKey(session) || makeSessionKey(sessionOrHostId, sessionId);
  const projection = getAssistantProjectionForSession(session);
  const client = window.MessageNotificationClient;
  if (!projection || !client || !state.messageReceiptStore) {
    state.messageUnread.delete(key);
    return false;
  }
  const receipt = receiptForAssistantProjection(session, projection);
  const unread = client.applyAssistantProjection(receipt, projection).unread;
  state.messageUnread[unread ? 'add' : 'delete'](key);
  return unread;
}

function markSessionMessageNotificationChanged(hostId, sessionId, projection = null) {
  const session = state.sessions.find((item) => getSessionKey(item) === makeSessionKey(hostId, sessionId))
    || { hostId, sessionId, assistantProjection: projection };
  const seed = projection || session.assistantProjection;
  if (!seed?.canonicalConversationKey) return false;
  void catchUpAssistantProjection(session, seed).catch(() => {});
  return true;
}

function refreshMessageUnreadState() {
  state.messageUnread.clear();
  for (const session of state.sessions || []) {
    updateMessageUnreadForSession(session);
  }
}

function getMessageReadGate(session = getSelectedSession()) {
  const key = getSessionKey(session);
  const ClientGate = window.MessageNotificationClient?.ReadEligibilityGate;
  if (!key || !ClientGate) return null;
  if (!state.messageReadGates.has(key)) {
    state.messageReadGates.set(key, new ClientGate());
  }
  return state.messageReadGates.get(key);
}

function establishMessageReadFollow(session, reason) {
  return getMessageReadGate(session)?.establishFollow(reason, { trusted: true }) === true;
}

function noteMessageReadProgrammaticScroll(session = getSelectedSession()) {
  getMessageReadGate(session)?.noteProgrammaticScroll();
}

function noteMessageReadThinkingScroll(session = getSelectedSession()) {
  getMessageReadGate(session)?.noteThinkingScroll();
}

async function maybeAdvanceReadReceipt(session = getSelectedSession(), expectedRenderVersion = null) {
  const key = getSessionKey(session);
  if (!key || key !== getSessionKey(getSelectedSession())) return false;
  const log = el('session-log');
  const renderVersion = Number(state.transcriptNotificationRenderVersions.get(key) || 0);
  if (
    !state.messageReadRenderReady.has(key)
    || log?.dataset?.sessionKey !== key
    || (expectedRenderVersion != null && renderVersion !== expectedRenderVersion)
  ) return false;

  const projection = getAssistantProjectionForSession(session);
  if (projection?.canonicalConversationKey) {
    await catchUpAssistantProjection(session, projection).catch(() => null);
  }
  if (
    key !== getSessionKey(getSelectedSession())
    || Number(state.transcriptNotificationRenderVersions.get(key) || 0) !== renderVersion
  ) return false;
  const currentProjection = getAssistantProjectionForSession(session);
  const renderedAssistantSeq = Number(state.transcriptNotificationRenderedAssistantSeq.get(key) || 0);
  if (Number(currentProjection?.latestAssistantSeq || 0) > renderedAssistantSeq) return false;

  const gate = getMessageReadGate(session);
  const gateState = gate?.state?.() || {};
  const machine = getTranscriptScrollMachine();
  const eligible = gate?.canAdvance({
    selected: true,
    visible: state.messageDocumentVisible && (!document.visibilityState || document.visibilityState === 'visible'),
    focused: state.messageWindowFocused && (typeof document.hasFocus !== 'function' || document.hasFocus()),
    renderCurrent: log?.dataset?.sessionKey === key,
    atReadingBoundary: machine?.state().mode === 'follow' && isTranscriptPinnedAcrossScrollTargets(),
    outerScrollSource: gateState.lastSource === 'user' ? 'user' : 'programmatic',
  });
  if (!eligible) return false;
  const changed = markSessionMessagesRead(session);
  if (changed) {
    renderConversationNav();
    renderMessageNotificationBell();
  }
  return changed;
}

function completeTranscriptNotificationRender(session) {
  const key = getSessionKey(session);
  if (!key) return;
  const version = Number(state.transcriptNotificationRenderVersions.get(key) || 0) + 1;
  state.transcriptNotificationRenderVersions.set(key, version);
  state.transcriptNotificationRenderedAssistantSeq.set(
    key,
    Number(getAssistantProjectionForSession(session)?.latestAssistantSeq || 0)
  );
  const log = el('session-log');
  if (log?.dataset?.sessionKey === key) {
    log.dataset.notificationRenderVersion = String(version);
  }
  window.requestAnimationFrame(() => {
    void maybeAdvanceReadReceipt(session, version);
  });
}

function hasUnreadMessagesForSession(session) {
  const key = getSessionKey(session);
  return Boolean(key && state.messageUnread.has(key));
}

function hasUnreadMessagesForGroup(group) {
  return Boolean((group?.sessions || []).some(hasUnreadMessagesForSession));
}

function getUnreadMessageNotifications() {
  const byCanonical = new Map();
  for (const session of state.sessions || []) {
    if (!hasUnreadMessagesForSession(session)) continue;
    const projection = getAssistantProjectionForSession(session);
    const canonicalKey = projection?.canonicalConversationKey || getSessionKey(session);
    const latest = projection?.messages?.find((message) => (
      message.assistantMessageId === projection.latestAssistantId
    )) || projection?.messages?.at(-1) || null;
    const candidate = {
      session,
      key: canonicalKey,
      title: session.title || session.conversationKey || session.sessionId,
      hostLabel: getHost(session.hostId)?.label || session.hostId,
      text: latest?.previewText || '',
      timestamp: projection?.latestAssistantAt || latest?.assistantAt || '',
    };
    const current = byCanonical.get(canonicalKey);
    if (!current || Date.parse(candidate.timestamp || '') > Date.parse(current.timestamp || '')) {
      byCanonical.set(canonicalKey, candidate);
    }
  }
  return [...byCanonical.values()]
    .sort((a, b) => Date.parse(b.timestamp || '') - Date.parse(a.timestamp || ''));
}

function markAllMessageNotificationsRead() {
  const markAll = () => {
    for (const notification of getUnreadMessageNotifications()) {
      markSessionMessagesRead(notification.session, null, {
        clearAllUnread: true,
        deferUnreadRefresh: true,
      });
    }
  };
  if (typeof state.messageReceiptStore?.batch === 'function') {
    state.messageReceiptStore.batch(markAll);
  } else {
    markAll();
  }
  refreshMessageUnreadState();
  state.messageNotificationOpen = false;
  renderMessageNotificationBell();
  renderConversationNav();
}

function renderMessageNotificationBell() {
  const button = el('message-notification-button');
  const panel = el('message-notification-panel');
  const countEl = el('message-notification-count');
  const list = el('message-notification-list');
  const empty = el('message-notification-empty');
  const notifications = getUnreadMessageNotifications();
  const count = notifications.length;

  if (button) {
    button.classList.toggle('has-unread', count > 0);
    button.setAttribute('aria-expanded', state.messageNotificationOpen ? 'true' : 'false');
    button.title = count > 0 ? `${count} session(s) have unread Codex messages` : 'No unread Codex messages';
  }
  if (countEl) {
    countEl.textContent = String(count);
    countEl.classList.toggle('hidden', count < 1);
  }
  if (!panel || !list || !empty) {
    return;
  }

  panel.classList.toggle('hidden', !state.messageNotificationOpen);
  panel.setAttribute('aria-hidden', state.messageNotificationOpen ? 'false' : 'true');
  list.innerHTML = '';
  empty.classList.toggle('hidden', count > 0);
  if (!count) {
    return;
  }

  for (const notification of notifications) {
    const item = document.createElement('button');
    item.type = 'button';
    item.className = 'message-notification-item';
    item.innerHTML = `
      <span class="message-notification-title">${escapeHtml(notification.title)}</span>
      <span class="message-notification-meta">${escapeHtml(notification.hostLabel)} | ${notification.session.live ? 'live' : 'history'} | ${escapeHtml(formatTime(notification.timestamp) || 'new')}</span>
      <span class="message-notification-preview">${escapeHtml(truncatePreview(notification.text || 'New Codex message'))}</span>
    `;
    item.onclick = async (event) => {
      state.messageNotificationOpen = false;
      await selectSession(notification.session, { trusted: event?.isTrusted === true });
      renderMessageNotificationBell();
      renderConversationNav();
    };
    list.appendChild(item);
  }
}

function dedupeAlerts(entries) {
  const seen = new Set();
  const deduped = [];

  for (const entry of entries || []) {
    if (!entry || !entry.message) {
      continue;
    }

    const normalized = {
      alertId: entry.alertId || null,
      assistantMessageId: entry.assistantMessageId || null,
      assistantSeq: Number(entry.assistantSeq || 0) || null,
      canonicalConversationKey: entry.canonicalConversationKey || null,
      timestamp: entry.timestamp || null,
      severity: entry.severity || 'warning',
      source: entry.source || 'runtime',
      message: String(entry.message || ''),
      sessionId: entry.sessionId || null,
      hostId: entry.hostId || null,
      transient: entry.transient === true,
      turnId: entry.turnId || null,
    };
    const key = normalized.alertId
      || `${normalized.severity}|${normalized.timestamp || ''}|${normalized.message}`;
    if (seen.has(key)) {
      continue;
    }
    seen.add(key);
    deduped.push(normalized);
  }

  return deduped.slice(-100);
}

function setAlertsForSession(hostId, sessionId, alerts) {
  const key = makeSessionKey(hostId, sessionId);
  const retainedAssistantAlerts = (state.alerts.get(key) || []).filter((alert) => alert.alertId);
  state.alerts.set(key, dedupeAlerts([...(alerts || []), ...retainedAssistantAlerts]));
}

function appendAlertForSession(hostId, sessionId, alert) {
  const key = makeSessionKey(hostId, sessionId);
  const existing = state.alerts.get(key) || [];
  state.alerts.set(key, dedupeAlerts([...existing, alert]));
}

function alertFingerprint(entry) {
  if (entry?.alertId) return entry.alertId;
  return [
    entry?.severity || 'warning',
    entry?.source || 'runtime',
    entry?.timestamp || '',
    String(entry?.message || '').trim(),
  ].join('\u0000');
}

function shouldDisplayAlert(entry) {
  const severity = String(entry?.severity || 'warning').trim().toLowerCase();
  const source = String(entry?.source || '').trim().toLowerCase();
  const message = String(entry?.message || '');
  if (!['warning', 'error'].includes(severity)) {
    return false;
  }
  return !(
    source === 'assistant-message'
    || /codex_app_server: failed to initialize sqlite state db/i.test(message)
    || /Codex could not find bubblewrap on PATH/i.test(message)
    || /sandbox prerequisites/i.test(message)
    || /concepts\/sandboxing#prerequisites/i.test(message)
    || /no live session for command session\.(watch|unwatch)\b/i.test(message)
    || /^Session state changed:\s*exited:(?:null|143):(?:SIGTERM|null)$/i.test(message)
    || /^Session state changed:\s*exited:[^:]*:SIGTERM$/i.test(message)
  );
}

function isStaleStartupFailureAlert(entry, session) {
  if (!session?.live) {
    return false;
  }

  const message = String(entry?.message || '');
  if (!/runner: no pipe-in provided|codex app-server exited early|failed to spawn managed session|failed:spawn-error|exited:1:null/i.test(message)) {
    return false;
  }

  const runtime = getRuntimeForSession(session) || session.runtime || null;
  const recoveredAt = Date.parse(runtime?.updatedAt || session.lastUpdatedAt || '');
  const alertAt = Date.parse(entry?.timestamp || '');
  return !Number.isFinite(recoveredAt) || !Number.isFinite(alertAt) || alertAt < recoveredAt;
}

function isRecoveredTransientRetryAlert(entry, session) {
  if (entry?.transient !== true || String(entry?.severity || '').toLowerCase() !== 'warning') {
    return false;
  }
  const message = String(entry?.message || '');
  if (/no live session for command session\.input\b/i.test(message)) {
    return false;
  }
  const alertTurnId = String(entry?.turnId || '').trim();
  if (!alertTurnId) {
    return false;
  }

  const runtime = getRuntimeForSession(session) || session?.runtime || null;
  if (!runtime || String(runtime.lastError || '').trim() || String(runtime.lastCodexError || '').trim()) {
    return false;
  }
  const terminalStates = new Set(['error', 'failed', 'quota-exhausted', 'closed']);
  if ([runtime.phase, runtime.currentTurnStatus]
    .some((value) => terminalStates.has(String(value || '').trim().toLowerCase()))) {
    return false;
  }
  const recoveredAt = Date.parse(runtime.updatedAt || '');
  const alertAt = Date.parse(entry?.timestamp || '');
  if (!Number.isFinite(recoveredAt) || !Number.isFinite(alertAt) || recoveredAt <= alertAt) {
    return false;
  }

  const activeTurnId = String(runtime.activeTurnId || '').trim();
  return activeTurnId !== alertTurnId || runtimeIsActive(runtime);
}

function getAlertsForSession(session) {
  const key = getSessionKey(session);
  const dismissed = key ? state.dismissedAlerts.get(key) : null;
  return key
    ? (state.alerts.get(key) || [])
      .filter(shouldDisplayAlert)
      .filter((entry) => !isStaleStartupFailureAlert(entry, session))
      .filter((entry) => !isRecoveredTransientRetryAlert(entry, session))
      .filter((entry) => !dismissed?.has(alertFingerprint(entry)))
    : [];
}

function clearAlertsForSelectedSession() {
  const session = getSelectedSession();
  const key = getSessionKey(session);
  if (!session || !key) {
    return;
  }
  const visibleAlerts = getAlertsForSession(session);
  if (!visibleAlerts.length) {
    return;
  }

  const dismissed = state.dismissedAlerts.get(key) || new Set();
  for (const alert of visibleAlerts) {
    dismissed.add(alertFingerprint(alert));
  }
  state.dismissedAlerts.set(key, new Set(Array.from(dismissed).slice(-300)));
  persistDismissedAlerts();
  renderSessionDetails();
  renderAlertsWindow();
  renderStatusWindow();
}

function getTranscriptForSession(session) {
  const key = getSessionKey(session);
  return key ? state.transcripts.get(key) || [] : [];
}

function isTranscriptPinnedToBottom(log) {
  if (!log) {
    return true;
  }
  const distanceFromBottom = log.scrollHeight - log.scrollTop - log.clientHeight;
  return distanceFromBottom <= 8;
}

function getScrollableDistance(node) {
  if (!node) {
    return 0;
  }
  return Math.max(0, (node.scrollHeight || 0) - (node.clientHeight || 0));
}

function shouldUsePageTranscriptScroll() {
  return Boolean(window.matchMedia?.('(max-width: 980px), (pointer: coarse), (hover: none)').matches);
}

function getDocumentScrollOwner() {
  return document.scrollingElement || document.documentElement || document.body;
}

function getTranscriptScrollOwner() {
  return shouldUsePageTranscriptScroll() ? getDocumentScrollOwner() : el('session-log');
}

function getTranscriptScrollTargets() {
  const owner = getTranscriptScrollOwner();
  if (!owner) {
    return [];
  }
  return [owner];
}

function isDocumentScrollOwner(node) {
  return Boolean(node && (node === document.scrollingElement || node === document.documentElement || node === document.body));
}

function scrollOwnerTo(node, top, behavior = 'auto') {
  if (!node) {
    return;
  }
  if (isDocumentScrollOwner(node) && typeof window.scrollTo === 'function') {
    window.scrollTo({ top, behavior });
    return;
  }
  if (typeof node.scrollTo === 'function') {
    node.scrollTo({ top, behavior });
  } else {
    node.scrollTop = top;
  }
}

function getScrollOwnerViewportRect(node) {
  if (!node) {
    return null;
  }
  if (isDocumentScrollOwner(node)) {
    const height = window.innerHeight || document.documentElement?.clientHeight || node.clientHeight || 0;
    return { top: 0, bottom: height };
  }
  const rect = node.getBoundingClientRect();
  return { top: rect.top, bottom: rect.bottom };
}

function getScrollOwnerAnchorRoot(node) {
  if (isDocumentScrollOwner(node)) {
    return el('session-log') || document;
  }
  return node;
}

function getTranscriptScrollMachine(node = getTranscriptScrollOwner()) {
  if (!node || !window.RemoteCodexTranscriptScroll?.createScrollMachine) {
    return null;
  }
  let machine = state.transcriptScrollMachines.get(node);
  if (machine) {
    return machine;
  }
  machine = window.RemoteCodexTranscriptScroll.createScrollMachine(node, {
    initialMode: isTranscriptUserDetached() ? 'detached' : 'follow',
    anchorSelector: '[data-viewport-key]',
    anchorDatasetKey: 'viewportKey',
    bottomTolerance: 8,
    anchorRoot: () => getScrollOwnerAnchorRoot(node),
    getViewportRect: () => getScrollOwnerViewportRect(node),
    getScrollTop: () => Number(node.scrollTop || 0),
    setScrollTop: (_, top) => scrollOwnerTo(node, top),
    getScrollHeight: () => isDocumentScrollOwner(node)
      ? Math.max(document.body?.scrollHeight || 0, document.documentElement?.scrollHeight || 0)
      : Number(node.scrollHeight || 0),
    getClientHeight: () => isDocumentScrollOwner(node)
      ? Number(window.innerHeight || document.documentElement?.clientHeight || 0)
      : Number(node.clientHeight || 0),
  });
  state.transcriptScrollMachines.set(node, machine);
  return machine;
}

function datasetKeyToAttributeName(key) {
  return String(key || '').replace(/[A-Z]/g, (letter) => `-${letter.toLowerCase()}`);
}

function captureViewportAnchor(node, selector = '[data-viewport-key]', datasetKey = 'viewportKey') {
  const viewport = getScrollOwnerViewportRect(node);
  const root = getScrollOwnerAnchorRoot(node);
  if (!viewport || !root?.querySelectorAll) {
    return null;
  }
  let best = null;
  for (const candidate of root.querySelectorAll(selector)) {
    const key = candidate.dataset?.[datasetKey] || '';
    if (!key) {
      continue;
    }
    const rect = candidate.getBoundingClientRect();
    if (rect.bottom <= viewport.top + 1 || rect.top >= viewport.bottom - 1) {
      continue;
    }
    const distance = Math.abs(rect.top - viewport.top);
    if (!best || distance < best.distance) {
      best = {
        key,
        datasetKey,
        offset: rect.top - viewport.top,
        distance,
      };
    }
  }
  if (!best) {
    return null;
  }
  return {
    key: best.key,
    datasetKey: best.datasetKey,
    offset: best.offset,
  };
}

function restoreViewportAnchor(node, anchor) {
  if (!node || !anchor?.key) {
    return false;
  }
  const viewport = getScrollOwnerViewportRect(node);
  const root = getScrollOwnerAnchorRoot(node);
  if (!viewport || !root?.querySelector) {
    return false;
  }
  const attributeName = datasetKeyToAttributeName(anchor.datasetKey || 'viewportKey');
  const target = root.querySelector(`[data-${attributeName}="${cssEscape(anchor.key)}"]`);
  if (!target) {
    return false;
  }
  const rect = target.getBoundingClientRect();
  const delta = (rect.top - viewport.top) - (Number(anchor.offset) || 0);
  if (Math.abs(delta) < 0.5) {
    return true;
  }
  const maxScrollTop = getScrollableDistance(node);
  scrollOwnerTo(node, Math.min(Math.max(0, (node.scrollTop || 0) + delta), maxScrollTop));
  return true;
}

function captureViewportElementOffset(element, node = getTranscriptScrollOwner()) {
  if (!element?.isConnected || !node) {
    return null;
  }
  const viewport = getScrollOwnerViewportRect(node);
  const rect = element.getBoundingClientRect();
  if (!viewport || rect.bottom <= viewport.top || rect.top >= viewport.bottom) {
    return null;
  }
  return {
    element,
    node,
    offset: rect.top - viewport.top,
  };
}

function restoreViewportElementOffset(snapshot, element = snapshot?.element) {
  if (!element?.isConnected || !snapshot?.node) {
    return false;
  }
  const viewport = getScrollOwnerViewportRect(snapshot.node);
  if (!viewport) {
    return false;
  }
  const delta = (element.getBoundingClientRect().top - viewport.top) - snapshot.offset;
  if (Math.abs(delta) < 0.5) {
    return true;
  }
  const transcriptOwner = getTranscriptScrollOwner();
  const machine = snapshot.node === transcriptOwner
    ? getTranscriptScrollMachine(snapshot.node)
    : null;
  const apply = () => scrollOwnerTo(
    snapshot.node,
    Math.min(
      Math.max(0, (snapshot.node.scrollTop || 0) + delta),
      getScrollableDistance(snapshot.node)
    )
  );
  if (machine) machine.withProgrammaticScroll(apply);
  else apply();
  return true;
}

function transcriptScrollTargetPinned(node) {
  if (!node || getScrollableDistance(node) <= 4) {
    return true;
  }
  return isTranscriptPinnedToBottom(node);
}

function isTranscriptPinnedAcrossScrollTargets() {
  return getTranscriptScrollTargets().every(transcriptScrollTargetPinned);
}

function captureTranscriptScrollSnapshot() {
  return getTranscriptScrollTargets().map((node) => {
    const machine = getTranscriptScrollMachine(node);
    const machineSnapshot = machine?.capture() || null;
    return {
      node,
      machine,
      machineSnapshot,
      scrollTop: node.scrollTop || 0,
      bottomOffset: Math.max(0, (node.scrollHeight || 0) - (node.scrollTop || 0) - (node.clientHeight || 0)),
      anchor: captureViewportAnchor(node),
    };
  });
}

function restoreTranscriptRawSnapshot(item) {
  noteMessageReadProgrammaticScroll();
  if (item.machine && item.machineSnapshot) {
    item.machine.restore(item.machineSnapshot);
    return;
  }
  const maxScrollTop = getScrollableDistance(item.node);
  const nextScrollTop = Number.isFinite(item.scrollTop)
    ? Math.min(Math.max(0, item.scrollTop), maxScrollTop)
    : Math.max(0, maxScrollTop - (item.bottomOffset || 0));
  scrollOwnerTo(item.node, nextScrollTop);
  restoreViewportAnchor(item.node, item.anchor);
}

function restoreTranscriptScrollSnapshot(snapshot = []) {
  if (!Array.isArray(snapshot) || !snapshot.length) {
    return;
  }
  for (const item of snapshot) {
    if (!item?.node || getScrollableDistance(item.node) <= 4) {
      continue;
    }
    restoreTranscriptRawSnapshot(item);
  }
}

function restoreTranscriptScrollTargetsToBottom() {
  noteMessageReadProgrammaticScroll();
  for (const node of getTranscriptScrollTargets()) {
    if (!node || getScrollableDistance(node) <= 4) {
      continue;
    }
    const machine = getTranscriptScrollMachine(node);
    machine?.establishFollow();
    if (machine) {
      machine.withProgrammaticScroll(() => scrollOwnerTo(node, getScrollableDistance(node)));
    } else {
      scrollOwnerTo(node, getScrollableDistance(node));
    }
  }
}

function restoreTranscriptScroll(log, options = {}) {
  if (!log) {
    return;
  }
  noteMessageReadProgrammaticScroll();
  if (options.forceScroll || options.shouldStickToBottom) {
    restoreTranscriptScrollTargetsToBottom();
    return;
  }
  if (options.preserveScroll && Number.isFinite(options.scrollTop)) {
    const maxScrollTop = Math.max(0, log.scrollHeight - log.clientHeight);
    log.scrollTop = Math.min(Math.max(0, options.scrollTop), maxScrollTop);
    return;
  }
  if (options.preserveScroll && Number.isFinite(options.bottomOffset)) {
    log.scrollTop = Math.max(0, log.scrollHeight - log.clientHeight - options.bottomOffset);
    return;
  }
  if (Number.isFinite(options.scrollTop)) {
    const maxScrollTop = Math.max(0, log.scrollHeight - log.clientHeight);
    log.scrollTop = Math.min(Math.max(0, options.scrollTop), maxScrollTop);
    return;
  }
  const bottomOffset = Number.isFinite(options.bottomOffset) ? options.bottomOffset : 0;
  log.scrollTop = Math.max(0, log.scrollHeight - log.clientHeight - bottomOffset);
}

function updateTranscriptUnreadButton(key = getSessionKey(getSelectedSession()) || '') {
  const button = el('scroll-transcript-bottom-button');
  if (!button) {
    return;
  }
  const hasUnread = Boolean(key && state.transcriptUnread.has(key));
  button.classList.toggle('has-new', hasUnread);
  button.textContent = hasUnread ? 'Bottom *' : 'Bottom';
  button.title = hasUnread ? 'New transcript updates below. Jump to latest.' : 'Jump to latest transcript update.';
}

function clearTranscriptUnread(key = getSessionKey(getSelectedSession()) || '') {
  if (key) {
    state.transcriptUnread.delete(key);
  }
  updateTranscriptUnreadButton(key);
}

function setTranscriptUserDetached(key = getSessionKey(getSelectedSession()) || '', detached = false) {
  if (!key) {
    return;
  }
  if (detached) {
    state.transcriptUserDetached.add(key);
  } else {
    state.transcriptUserDetached.delete(key);
  }
}

function isTranscriptUserDetached(key = getSessionKey(getSelectedSession()) || '') {
  return Boolean(key && state.transcriptUserDetached.has(key));
}

function handleTranscriptScrollDetach() {
  const key = getSessionKey(getSelectedSession()) || '';
  const machine = getTranscriptScrollMachine();
  if (machine?.state().mode === 'follow' && isTranscriptPinnedAcrossScrollTargets()) {
    setTranscriptUserDetached(key, false);
    clearTranscriptUnread(key);
    void maybeAdvanceReadReceipt(getSelectedSession());
  } else if (machine?.state().mode === 'detached') {
    setTranscriptUserDetached(key, true);
  }
}

function recordTranscriptTrustedInteraction(event, phase = 'complete') {
  if (event?.isTrusted !== true || event?.target?.closest?.('.thinking-content')) {
    return;
  }
  const target = event.target;
  const log = el('session-log');
  const documentTarget = target === document.body || target === document.documentElement;
  const transcriptTarget = target === log
    || log?.contains?.(target)
    || Boolean(target?.closest?.('#session-log'));
  if (!documentTarget && !transcriptTarget) {
    return;
  }
  const owner = getTranscriptScrollOwner();
  const machine = getTranscriptScrollMachine(owner);
  if (!machine) {
    return;
  }
  if (phase !== 'end') {
    if (!machine.beginTrustedInteraction()) return;
    setTranscriptUserDetached(getSessionKey(getSelectedSession()) || '', true);
    getMessageReadGate()?.detachByUser();
    handleTranscriptScrollDetach();
  }
  if (phase === 'begin') {
    return;
  }
  window.requestAnimationFrame(() => {
    if (!machine.settleTrustedInteraction()) return;
    if (machine.state().mode === 'follow' && isTranscriptPinnedAcrossScrollTargets()) {
      establishMessageReadFollow(getSelectedSession(), 'outer-user-boundary');
    } else {
      getMessageReadGate()?.detachByUser();
    }
    handleTranscriptScrollDetach();
  });
}

function getTranscriptJumpTargets() {
  const targets = [];
  const seen = new Set();
  const add = (node) => {
    if (!node || seen.has(node)) {
      return;
    }
    seen.add(node);
    targets.push(node);
  };

  const log = el('session-log');
  add(getTranscriptScrollOwner());
  add(el('session-log'));
  add(document.querySelector('.main'));

  let node = log?.parentElement;
  while (node && node !== document.body) {
    const style = window.getComputedStyle(node);
    if (/(auto|scroll|overlay)/.test(style.overflowY) || getScrollableDistance(node) > 4) {
      add(node);
    }
    node = node.parentElement;
  }

  add(document.scrollingElement);
  add(document.documentElement);
  add(document.body);
  return targets;
}

function scrollTranscriptTo(position, options = {}) {
  if (!getTranscriptScrollOwner()) {
    return;
  }
  const behavior = window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth';
  const machine = getTranscriptScrollMachine();
  if (options.trusted === true) {
    machine?.beginTrustedInteraction();
  }
  const applyScroll = () => {
    const key = getSessionKey(getSelectedSession()) || '';
    if (position === 'bottom') {
      machine?.establishFollow();
      if (options.trusted === true) {
        establishMessageReadFollow(getSelectedSession(), 'outer-user-boundary');
      }
    } else {
      machine?.detach();
      if (options.trusted === true) {
        getMessageReadGate()?.detachByUser();
      }
    }
    for (const target of getTranscriptJumpTargets()) {
      const top = position === 'top' ? 0 : getScrollableDistance(target);
      scrollOwnerTo(target, top, behavior);
    }
    if (typeof window.scrollTo === 'function') {
      const viewportHeight = window.innerHeight || document.documentElement?.clientHeight || 0;
      const documentTop = position === 'top'
        ? 0
        : Math.max(
          0,
          Math.max(document.body?.scrollHeight || 0, document.documentElement?.scrollHeight || 0) - viewportHeight
        );
      window.scrollTo({ top: documentTop, behavior });
    }
    if (position === 'bottom') {
      setTranscriptUserDetached(key, false);
      clearTranscriptUnread();
      void maybeAdvanceReadReceipt(getSelectedSession());
    } else if (position === 'top') {
      setTranscriptUserDetached(key, true);
    }
  };

  applyScroll();
  window.requestAnimationFrame(applyScroll);
  window.setTimeout(applyScroll, 180);
}

function stripResumeBootstrapText(value, speaker = '') {
  const text = String(value || '').replace(/\r\n?/g, '\n').trim();
  if (!text) {
    return '';
  }

  const hasPrelude = /Continue this conversation with the following prior context in mind:/i.test(text);
  const requestMatch = text.match(/(?:^|\n)New user request:\s*([\s\S]*)$/i);
  if (!hasPrelude && !requestMatch) {
    return text;
  }

  const requestText = requestMatch ? requestMatch[1].trim() : '';
  if (speaker === 'user') {
    return requestText;
  }

  // App-server fallback resume can make Codex echo the synthetic context
  // prompt. It is transport glue, not useful chat content.
  return '';
}

function cleanTranscriptTextForDisplay(value, speaker = '') {
  let text = String(value || '').replace(/\r\n?/g, '\n').trim();
  if (!text || isInternalTranscriptText(text)) {
    return '';
  }

  text = stripResumeBootstrapText(text, speaker).trim();
  if (!text || isInternalTranscriptText(text)) {
    return '';
  }

  text = stripTranscriptWrapperText(text).trim();
  if (!text || isInternalTranscriptText(text)) {
    return '';
  }

  text = stripEnvironmentContextText(text).trim();
  if (String(speaker || '').toLowerCase() === 'user') {
    text = stripIdeContextText(text).trim();
  }

  return isInternalTranscriptText(text) ? '' : text;
}

function stripTranscriptWrapperText(value) {
  let text = String(value || '').replace(/\r\n?/g, '\n').trim();
  if (!text) {
    return '';
  }

  const wrapperPatterns = [
    /\n?The following is the Codex agent history (?:whose request action you are assessing|added since your last approval assessment)\b[\s\S]*$/i,
    /\n?>>> TRANSCRIPT(?: DELTA)? START\b[\s\S]*$/im,
    /\n?>>> TRANSCRIPT(?: DELTA)? END\b[\s\S]*$/im,
    /\n?>>> APPROVAL REQUEST START\b[\s\S]*$/im,
    /\n?>>> APPROVAL REQUEST END\b[\s\S]*$/im,
    /\n?Reviewed Codex session id:[\s\S]*$/i,
    /\n?The Codex agent has requested the following (?:next action|action below|action):[\s\S]*$/i,
  ];

  for (const pattern of wrapperPatterns) {
    text = text.replace(pattern, '').trim();
  }
  return text;
}

function stripEnvironmentContextText(value) {
  return String(value || '')
    .replace(/<environment_context>[\s\S]*?<\/environment_context>/gi, '')
    .trim();
}

function stripIdeContextText(value) {
  const text = String(value || '').trim();
  const requestMatch = text.match(/(?:^|\n)## My request for Codex:\s*([\s\S]*)$/i);
  return requestMatch ? requestMatch[1].trim() : text;
}

function isInternalTranscriptText(value) {
  const text = String(value || '').trim();
  if (!text) {
    return true;
  }
  if (/^<user_action\b[\s\S]*<\/user_action>$/i.test(text)) {
    return true;
  }
  if (/^<environment_context>[\s\S]*<\/environment_context>$/i.test(text)) {
    return true;
  }
  if (/^The following is the Codex agent history (?:whose request action you are assessing|added since your last approval assessment)\b/i.test(text)) {
    return true;
  }
  if (/^>>>\s+TRANSCRIPT(?:\s+DELTA)?\s+START\b/im.test(text)) {
    return true;
  }
  if (/^\{\s*"(?:risk_level|outcome|user_authorization)"\s*:/.test(text) && /"outcome"\s*:\s*"(?:allow|deny)"/i.test(text)) {
    return true;
  }
  return false;
}

function canonicalTranscriptText(value) {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

function transcriptViewportKey(entry, index) {
  return [
    'transcript',
    Number.isFinite(index) ? index : '',
    entry?.speaker || '',
    entry?.timestamp || '',
  ].join('|');
}

function setRuntimeForSession(hostId, sessionId, runtime, options = {}) {
  const key = makeSessionKey(hostId, sessionId);
  if (!(state.runtimeApplyGenerations instanceof Map)) state.runtimeApplyGenerations = new Map();
  if (!(state.runtimeStreamGenerations instanceof Map)) state.runtimeStreamGenerations = new Map();
  if (!runtime || typeof runtime !== 'object') {
    state.runtime.delete(key);
    state.runtimeApplyGenerations.set(key, (state.runtimeApplyGenerations.get(key) || 0) + 1);
    if (options.source === 'stream') {
      state.runtimeStreamGenerations.set(key, (state.runtimeStreamGenerations.get(key) || 0) + 1);
    }
    return null;
  }

  const previous = state.runtime.get(key) || {};
  const updatedAt = runtime.updatedAt || new Date().toISOString();
  const previousRevision = Number(previous.runtimeRevision || 0);
  const incomingRevision = Number(runtime.runtimeRevision || 0);
  const previousRunId = String(previous.runId || '').trim();
  const incomingRunId = String(runtime.runId || '').trim();
  if (
    options.allowStale !== true
    && Number.isSafeInteger(previousRevision)
    && previousRevision > 0
    && Number.isSafeInteger(incomingRevision)
    && incomingRevision > 0
    && previousRunId
    && incomingRunId
    && previousRunId === incomingRunId
    && incomingRevision <= previousRevision
  ) {
    return previous;
  }
  const previousUpdatedAtMs = Date.parse(previous.updatedAt || '');
  const incomingUpdatedAtMs = Date.parse(updatedAt);
  if (
    options.allowStale !== true
    && Number.isFinite(previousUpdatedAtMs)
    && Number.isFinite(incomingUpdatedAtMs)
    && incomingUpdatedAtMs < previousUpdatedAtMs
  ) {
    return previous;
  }
  const next = {
    ...previous,
    ...runtime,
    updatedAt,
  };

  if (Object.prototype.hasOwnProperty.call(runtime, 'phase')) {
    next.phaseStartedAt = runtime.phase !== previous.phase
      ? updatedAt
      : previous.phaseStartedAt || updatedAt;
  } else {
    next.phaseStartedAt = previous.phaseStartedAt || (next.phase ? updatedAt : null);
  }

  if (Object.prototype.hasOwnProperty.call(runtime, 'busy')) {
    next.busyStartedAt = runtime.busy
      ? (previous.busy ? previous.busyStartedAt || updatedAt : updatedAt)
      : null;
  } else {
    next.busyStartedAt = previous.busyStartedAt || null;
  }

  if (Object.prototype.hasOwnProperty.call(runtime, 'activeTurnId')) {
    next.turnStartedAt = runtime.activeTurnId
      ? (runtime.activeTurnId !== previous.activeTurnId ? updatedAt : previous.turnStartedAt || updatedAt)
      : null;
  } else {
    next.turnStartedAt = previous.turnStartedAt || null;
  }

  if (Object.prototype.hasOwnProperty.call(runtime, 'connection')) {
    next.runtimeConnectionStartedAt = runtime.connection !== previous.connection
      ? updatedAt
      : previous.runtimeConnectionStartedAt || updatedAt;
  } else {
    next.runtimeConnectionStartedAt = previous.runtimeConnectionStartedAt || null;
  }

  if (Object.prototype.hasOwnProperty.call(runtime, 'reasoningSummary') && runtime.reasoningSummary) {
    next.reasoningUpdatedAt = updatedAt;
  } else {
    next.reasoningUpdatedAt = previous.reasoningUpdatedAt || null;
  }

  if (Object.prototype.hasOwnProperty.call(runtime, 'planSummary') && runtime.planSummary) {
    next.planUpdatedAt = updatedAt;
  } else {
    next.planUpdatedAt = previous.planUpdatedAt || null;
  }

  state.runtime.set(key, next);
  state.runtimeApplyGenerations.set(key, (state.runtimeApplyGenerations.get(key) || 0) + 1);
  if (options.source === 'stream') {
    state.runtimeStreamGenerations.set(key, (state.runtimeStreamGenerations.get(key) || 0) + 1);
  }
  return next;
}

function patchRuntimeForSession(hostId, sessionId, patch, options = {}) {
  return setRuntimeForSession(hostId, sessionId, patch, options);
}

function getRuntimeStreamGeneration(hostId, sessionId) {
  const key = makeSessionKey(hostId, sessionId);
  return state.runtimeStreamGenerations instanceof Map
    ? state.runtimeStreamGenerations.get(key) || 0
    : 0;
}

function getRuntimeApplyGeneration(hostId, sessionId) {
  const key = makeSessionKey(hostId, sessionId);
  return state.runtimeApplyGenerations instanceof Map
    ? state.runtimeApplyGenerations.get(key) || 0
    : 0;
}

function restoreRuntimeSnapshotForSession(hostId, sessionId, runtimeSnapshot, options = {}) {
  const key = makeSessionKey(hostId, sessionId);
  const current = state.runtime.get(key) || null;
  const currentApplyGeneration = getRuntimeApplyGeneration(hostId, sessionId);
  const currentStreamGeneration = getRuntimeStreamGeneration(hostId, sessionId);
  if (
    (Number.isSafeInteger(options.expectedApplyGeneration)
      && currentApplyGeneration !== options.expectedApplyGeneration)
    || (Number.isSafeInteger(options.expectedStreamGeneration)
      && currentStreamGeneration !== options.expectedStreamGeneration)
  ) {
    return current;
  }
  if (!runtimeSnapshot || typeof runtimeSnapshot !== 'object') {
    state.runtime.delete(key);
    state.runtimeApplyGenerations.set(key, currentApplyGeneration + 1);
    return null;
  }
  const currentRevision = Number(current?.runtimeRevision || 0);
  const snapshotRevision = Number(runtimeSnapshot.runtimeRevision || 0);
  if (
    current
    && Number.isSafeInteger(currentRevision)
    && Number.isSafeInteger(snapshotRevision)
    && currentRevision > snapshotRevision
    && String(current.runId || '') === String(runtimeSnapshot.runId || '')
  ) {
    return current;
  }
  const restored = { ...runtimeSnapshot };
  state.runtime.set(key, restored);
  state.runtimeApplyGenerations.set(key, currentApplyGeneration + 1);
  return restored;
}

function getRuntimeForSession(session) {
  const key = getSessionKey(session);
  return key ? state.runtime.get(key) || null : null;
}

function normalizeDiagnosticEntry(entry) {
  if (!entry) {
    return null;
  }
  return {
    timestamp: entry.timestamp || null,
    severity: entry.severity || 'info',
    source: entry.source || 'codex',
    kind: entry.kind || 'event',
    method: entry.method || null,
    message: String(entry.message || ''),
    detail: entry.detail || null,
    data: entry.data || null,
    runId: entry.runId || entry.data?.runId || null,
    turnId: entry.turnId || entry.data?.turnId || null,
    itemId: entry.itemId || entry.data?.itemId || null,
    callId: entry.callId || entry.data?.callId || null,
    requestId: entry.requestId || entry.data?.requestId || null,
    status: entry.status || entry.data?.status || null,
    final: entry.final === true,
  };
}

function diagnosticEntryKey(entry) {
  return `${entry.timestamp || ''}|${entry.kind || ''}|${entry.method || ''}|${entry.message || ''}|${entry.detail || ''}|${entry.turnId || ''}|${entry.itemId || entry.callId || entry.requestId || ''}`;
}

function dedupeDiagnostics(entries) {
  const seen = new Set();
  const deduped = [];

  for (const entry of entries || []) {
    const normalized = normalizeDiagnosticEntry(entry);
    if (!normalized) {
      continue;
    }
    const key = diagnosticEntryKey(normalized);
    if (seen.has(key)) {
      continue;
    }
    seen.add(key);
    deduped.push(normalized);
  }

  return deduped
    .sort((a, b) => {
      const left = Date.parse(a.timestamp || '');
      const right = Date.parse(b.timestamp || '');
      if (Number.isFinite(left) && Number.isFinite(right) && left !== right) {
        return left - right;
      }
      if (Number.isFinite(left) !== Number.isFinite(right)) {
        return Number.isFinite(left) ? -1 : 1;
      }
      return 0;
    })
    .slice(-CLIENT_DIAGNOSTIC_ENTRY_LIMIT);
}

function setDiagnosticsForSession(hostId, sessionId, diagnostics) {
  const key = makeSessionKey(hostId, sessionId);
  state.diagnostics.set(key, dedupeDiagnostics(diagnostics));
}

function mergeDiagnosticsForSession(hostId, sessionId, diagnostics) {
  const key = makeSessionKey(hostId, sessionId);
  const existing = state.diagnostics.get(key) || [];
  state.diagnostics.set(key, dedupeDiagnostics([...existing, ...(Array.isArray(diagnostics) ? diagnostics : [])]));
}

function appendDiagnosticForSession(hostId, sessionId, entry) {
  const key = makeSessionKey(hostId, sessionId);
  const existing = state.diagnostics.get(key) || [];
  const normalized = normalizeDiagnosticEntry(entry);
  if (!normalized || !normalized.message) {
    return;
  }
  const fingerprint = diagnosticEntryKey(normalized);
  const recentStart = Math.max(0, existing.length - CLIENT_DIAGNOSTIC_RECENT_DEDUPE_WINDOW);
  for (let index = existing.length - 1; index >= recentStart; index -= 1) {
    if (diagnosticEntryKey(existing[index]) === fingerprint) {
      return;
    }
  }
  existing.push(normalized);
  if (existing.length > CLIENT_DIAGNOSTIC_ENTRY_LIMIT) {
    existing.splice(0, existing.length - CLIENT_DIAGNOSTIC_ENTRY_LIMIT);
  }
  state.diagnostics.set(key, existing);
}

function getDiagnosticsForSession(session) {
  const key = getSessionKey(session);
  return key ? state.diagnostics.get(key) || [] : [];
}

function setRequestsForSession(hostId, sessionId, requests) {
  const key = makeSessionKey(hostId, sessionId);
  const normalized = Array.isArray(requests) ? requests.slice(-40) : [];
  state.requests.set(key, normalized);
  const pendingRequestIds = new Set(normalized
    .filter((request) => request?.status === 'pending')
    .map((request) => String(request.requestId || ''))
    .filter(Boolean));
  for (const draftKey of state.codexControls.inputAnswersByRequest.keys()) {
    const prefix = `${key}::`;
    if (draftKey.startsWith(prefix) && !pendingRequestIds.has(draftKey.slice(prefix.length))) {
      state.codexControls.inputAnswersByRequest.delete(draftKey);
    }
  }
  const activeResponseKeys = new Set(normalized
    .filter((request) => ['pending', 'responding'].includes(request?.status))
    .map((request) => sessionRequestResponseKey({ hostId, sessionId }, request))
    .filter(Boolean));
  for (const responseKey of state.codexControls.respondingRequestKeys) {
    if (responseKey.startsWith(`${key}::`) && !activeResponseKeys.has(responseKey)) {
      state.codexControls.respondingRequestKeys.delete(responseKey);
    }
  }
}

function upsertRequestForSession(hostId, sessionId, request) {
  const key = makeSessionKey(hostId, sessionId);
  const existing = state.requests.get(key) || [];
  const requestId = String(request.requestId || '');
  const index = existing.findIndex((item) => String(item.requestId || '') === requestId);
  const next = {
    ...request,
    requestId,
  };
  if (index === -1) {
    existing.push(next);
  } else {
    existing[index] = {
      ...existing[index],
      ...next,
    };
  }
  state.requests.set(key, existing.slice(-40));
}

function resolveRequestForSession(hostId, sessionId, request) {
  clearInputAnswerDraft(hostId, sessionId, request?.requestId);
  state.codexControls.respondingRequestKeys.delete(sessionRequestResponseKey({ hostId, sessionId }, request));
  upsertRequestForSession(hostId, sessionId, request);
}

function getRequestsForSession(session) {
  const key = getSessionKey(session);
  return key ? state.requests.get(key) || [] : [];
}

function setReceivedFilesForSession(hostId, sessionId, files) {
  const key = makeSessionKey(hostId, sessionId);
  state.receivedFiles.set(key, Array.isArray(files) ? files : []);
}

function getReceivedFilesForSession(session) {
  const key = getSessionKey(session);
  return key ? state.receivedFiles.get(key) || [] : [];
}

function isReceivedFilesLoading(session) {
  const key = getSessionKey(session);
  return key ? state.receivedFilesLoadingKeys.has(key) : false;
}

function setStreamStatusForSession(hostId, sessionId, patch) {
  const key = makeSessionKey(hostId, sessionId);
  const previous = state.streamStatus.get(key) || {};
  const changedAt = patch?.changedAt || new Date().toISOString();
  const next = {
    ...previous,
    ...patch,
  };

  if (Object.prototype.hasOwnProperty.call(patch || {}, 'connection')) {
    next.connectionChangedAt = patch.connection !== previous.connection
      ? changedAt
      : previous.connectionChangedAt || changedAt;
  }

  if (patch?.lastPingAt) {
    next.lastEventAt = patch.lastPingAt;
  }

  state.streamStatus.set(key, next);
}

function getStreamStatusForSession(session) {
  const key = getSessionKey(session);
  return key ? state.streamStatus.get(key) || null : null;
}

function parseStreamTimestamp(value) {
  const time = Date.parse(value || '');
  return Number.isFinite(time) ? time : 0;
}

function checkSelectedSessionStreamHealth() {
  if (!authAllowsRequests()) {
    return;
  }
  const selected = getSelectedSession();
  if (!selected) {
    return;
  }
  void maintainSelectedSessionWatch();
  const selectedKey = getSessionKey(selected);
  if (!selectedKey || state.eventSourceKey !== selectedKey || !state.eventSource) {
    return;
  }
  const stream = getStreamStatusForSession(selected);
  if (!stream?.lastPingAt) {
    return;
  }
  const lastPingAt = parseStreamTimestamp(stream.lastPingAt);
  if (!lastPingAt || Date.now() - lastPingAt < STREAM_STALE_RECONNECT_MS) {
    return;
  }
  setStreamStatusForSession(selected.hostId, selected.sessionId, {
    connection: 'reconnecting',
    staleAt: new Date().toISOString(),
  });
  resumeSelectedSessionRealtime().catch(reportError);
}

function getConnector(connectorId) {
  return state.connectors.find((connector) => connector.connectorId === connectorId) || null;
}

function normalizeMatchText(value) {
  return String(value || '').trim().toLowerCase();
}

function getConnectorForHost(hostId) {
  const host = getHost(hostId);
  return state.connectors.find((connector) => connector.hostId === hostId || connector.runtime?.attachedHostId === hostId)
    || state.connectors.find((connector) => {
      if (!host) {
        return false;
      }
      return normalizeMatchText(connector.label) === normalizeMatchText(host.label);
    })
    || null;
}

