function renderConnectorRunbookList(container, entries, emptyText) {
  container.innerHTML = '';
  const items = Array.isArray(entries) ? entries.filter(Boolean) : [];
  if (!items.length) {
    const empty = document.createElement('div');
    empty.className = 'connector-runbook-item';
    empty.textContent = emptyText;
    container.appendChild(empty);
    return;
  }

  for (const entry of items) {
    const item = document.createElement('div');
    item.className = 'connector-runbook-item';
    item.textContent = entry;
    container.appendChild(item);
  }
}

function renderConnectorRunbook(connector) {
  const command = connector?.plan?.bootstrapCommand || '';
  const smokeCommand = connector?.plan?.sshSmokeTestCommand || '';
  const loginCommand = connector?.plan?.sshLoginCommand || '';
  const summary = connector?.plan?.summary || 'Save a connector to generate its tmux command.';
  const copyButton = el('copy-connector-command-button');
  const copyLoginButton = el('copy-connector-login-button');
  const copySmokeButton = el('copy-connector-smoke-button');
  const runSmokeButton = el('run-connector-smoke-button');
  const runStatusButton = el('run-connector-status-button');
  const runBootstrapButton = el('run-connector-bootstrap-button');
  const runRestartButton = el('run-connector-restart-button');
  const actionResult = el('connector-action-result');
  const actionKey = connector?.connectorId || '';
  const busyAction = state.connectorActionBusy?.connectorId === actionKey
    ? state.connectorActionBusy.action
    : null;
  const actionBusy = Boolean(busyAction);
  const result = actionKey ? state.connectorActionResults.get(actionKey) : null;
  el('connector-runbook-summary').textContent = summary;
  el('connector-login-command').textContent = loginCommand || '(no login command yet)';
  el('connector-smoke-command').textContent = smokeCommand || '(no smoke test yet)';
  el('connector-bootstrap-command').textContent = command || '(no command yet)';
  copyButton.disabled = !command;
  copyLoginButton.disabled = !loginCommand;
  copySmokeButton.disabled = !smokeCommand;
  runSmokeButton.disabled = !connector || actionBusy;
  runStatusButton.disabled = !connector || actionBusy;
  runBootstrapButton.disabled = !connector || actionBusy;
  runRestartButton.disabled = !connector || actionBusy;
  runSmokeButton.textContent = busyAction === 'smoke_test' ? 'Running...' : 'Run Test';
  runStatusButton.textContent = busyAction === 'status' ? 'Checking...' : 'Check Status';
  runBootstrapButton.textContent = busyAction === 'bootstrap' ? 'Starting...' : 'Start Agent';
  runRestartButton.textContent = busyAction === 'restart' ? 'Restarting...' : 'Restart Agent';
  renderConnectorActionResult(actionResult, result, actionBusy);
  renderConnectorRunbookList(el('connector-plan-steps'), connector?.plan?.steps || [], 'No bootstrap steps yet.');
  renderConnectorRunbookList(el('connector-plan-warnings'), connector?.plan?.warnings || [], 'No MFA or auth warnings.');
}

function connectorCodexInstallGuidance(result) {
  if (!result) {
    return [];
  }
  const statusText = [
    result.status,
    result.deploy?.status,
    result.message,
    result.deploy?.message,
  ].filter(Boolean).join(' ');
  if (!/codex_runtime_missing|no .*codex cli|codex cli .*not found|CODEX_REMOTE_CHECK_CODEX=missing/i.test(statusText)) {
    return [];
  }

  return [
    'Remote Codex CLI install guide:',
    'Option A, shared HPC/conda:',
    'conda create -n codex-node -c conda-forge nodejs=20 -y',
    'conda activate codex-node',
    'npm install -g @openai/codex',
    'codex --help',
    '',
    'Option B, personal Linux server:',
    'curl -fsSL https://fnm.vercel.app/install | bash',
    'source ~/.bashrc',
    'fnm install 20',
    'fnm use 20',
    'npm install -g @openai/codex',
    'codex --help',
    '',
    'After installation, run Start Agent again. The remote scanner checks PATH, ~/.codex, common conda/nvm locations, and the uploaded runtime.',
  ];
}

function renderConnectorActionResult(container, result, busy) {
  if (!result && !busy) {
    container.className = 'connector-action-result hidden';
    container.textContent = '';
    return;
  }

  container.className = `connector-action-result ${result?.ok ? 'success' : result ? 'failure' : ''}`.trim();
  const lines = [];
  if (busy) {
    lines.push('Running remote connector action...');
  }
  if (result) {
    lines.push(`${prettyStatusLabel(result.status || result.action || 'Result')}: ${result.message || ''}`.trim());
    if (result.expectedHostId) {
      lines.push(`Expected host: ${result.expectedHostId}`);
    }
    if (result.multiplexFallback) {
      lines.push(`SSH multiplex fallback: ${result.multiplexFallback.reason || 'ControlMaster failed; retried without multiplexing.'}`);
      if (result.multiplexFallback.controlPath) {
        lines.push(`ControlPath: ${result.multiplexFallback.controlPath}`);
      }
    }
    if (typeof result.exitCode !== 'undefined' && result.exitCode !== null) {
      lines.push(`Exit code: ${result.exitCode}`);
    }
    if (result.deploy) {
      lines.push(`deploy: ${prettyStatusLabel(result.deploy.status || 'deploy')} - ${result.deploy.message || ''}`.trim());
      for (const step of result.deploy.steps || []) {
        const stepLines = [`${step.name || 'step'} exit ${step.exitCode}`];
        if (step.stdout) {
          stepLines.push(`stdout:\n${step.stdout}`);
        }
        if (step.stderr) {
          stepLines.push(`stderr:\n${step.stderr}`);
        }
        lines.push(stepLines.join('\n'));
      }
    }
    if (result.stdout) {
      lines.push(`stdout:\n${result.stdout}`);
    }
    if (result.stderr) {
      lines.push(`stderr:\n${result.stderr}`);
    }
    if (result.command && result.status === 'manual_required') {
      lines.push(`manual login:\n${result.command}`);
    }
    if (result.bootstrapCommand && result.status === 'manual_required') {
      lines.push(`manual bootstrap:\n${result.bootstrapCommand}`);
    }
    const installGuidance = connectorCodexInstallGuidance(result);
    if (installGuidance.length) {
      lines.push(installGuidance.join('\n'));
    }
  }

  container.innerHTML = `<pre>${escapeHtml(lines.join('\n\n'))}</pre>`;
}

function renderConnectorManager() {
  const list = el('connector-list');
  const editor = el('connector-editor');
  const overlay = el('connector-manager-overlay');
  const hostMap = new Map(state.hosts.map((host) => [host.hostId, host]));
  list.innerHTML = '';

  if (!state.connectorManagerOpen) {
    overlay.classList.add('hidden');
    editor.classList.add('hidden');
    syncModalBodyState();
    return;
  }

  overlay.classList.remove('hidden');
  editor.classList.remove('hidden');
  syncModalBodyState();

  if (!state.connectors.length) {
    const empty = document.createElement('div');
    empty.className = 'empty-state';
    empty.textContent = 'No saved connectors yet. Add one for HPC, gateway, or passwordless bootstrap.';
    list.appendChild(empty);
  } else {
    for (const connector of state.connectors) {
      const host = connector.hostId ? hostMap.get(connector.hostId) || null : null;
      const item = document.createElement('button');
      item.type = 'button';
      item.className = `connector-card ${connector.connectorId === state.connectorEditorId ? 'active' : ''}`;
      const secretSummary = [
        connector.secretStatus?.hasGatewayPassword ? 'gateway password saved' : '',
        connector.secretStatus?.hasTargetPassword ? 'target password saved' : '',
      ].filter(Boolean).join(' | ') || 'no saved password';
      item.innerHTML = `
        <div class="connector-card-top">
          <div>
            <div class="title">${connector.label}</div>
            <div class="sub">${connectorKindLabel(connector.kind)} | ${connector.authLabel} | ${connector.runtime?.phaseLabel || 'Saved'}</div>
          </div>
          <div class="connector-badge">${connector.runtime?.attachedHostOnline ? 'Live' : 'Saved'}</div>
        </div>
        <div class="connector-meta">${connector.hostId || connector.targetHost || '(unbound target)'}</div>
        <div class="connector-meta">${connector.gatewaySummary} | Gateway ${connector.gatewayAuthLabel || 'Auth'} | Target ${connector.authLabel}</div>
        <div class="connector-meta">${secretSummary}</div>
        <div class="connector-plan">${connector.plan?.summary || 'Saved connector recipe.'}</div>
        <div class="connector-plan">${host ? `Attached host: ${host.label} | ${host.online ? 'online' : 'offline'}` : 'No attached host yet.'}</div>
      `;
      item.onclick = () => {
        state.connectorEditorId = connector.connectorId;
        populateConnectorForm(connector);
        renderConnectorManager();
      };
      list.appendChild(item);
    }
  }

  const connector = state.connectorEditorId ? getConnector(state.connectorEditorId) : null;
  populateConnectorForm(connector || buildConnectorDraft());
  renderConnectorRunbook(connector);
}

function createActionButton(label, className) {
  const button = document.createElement('button');
  button.type = 'button';
  button.className = `action-button ${className}`;
  button.textContent = label;
  return button;
}

function isLocalAgentCandidate(host) {
  if (!host?.hostId) {
    return false;
  }
  if (host.localAgent) {
    return true;
  }
  if (host.localAgentStartEnabled === false) {
    return false;
  }
  if (host.relayLocal) {
    return true;
  }
  const relayPlatform = state.stats?.relay?.platform || '';
  return Boolean(!host.online && (host.relayLocal || (relayPlatform && host.platform === relayPlatform)));
}

const HOST_RECOVERY_COPY = {
  local_agent_start: {
    label: 'Local Agent start',
    offline: 'The local Agent has not registered with the Relay after start.',
  },
  local_agent_restart: {
    label: 'Local Agent restart',
    offline: 'The replacement local Agent has not registered with the Relay after restart.',
  },
  hpc_connector_restart: {
    label: 'HPC connector restart',
    offline: 'The Host is still offline after the HPC connector restart.',
  },
};

function hostRecoveryCopy(recoveryKind) {
  return HOST_RECOVERY_COPY[recoveryKind] || {
    label: 'Host recovery',
    offline: 'The Host is still offline after recovery.',
  };
}

function localAgentRecoveryKind(action) {
  return action === 'restart' ? 'local_agent_restart' : 'local_agent_start';
}

function ownershipPendingDisplay(result) {
  const retryAfterMs = Math.max(0, Number(result?.retryAfterMs || 0) || 0);
  const retryCopy = retryAfterMs > 0
    ? ` Retry in about ${Math.max(1, Math.ceil(retryAfterMs / 1000))} seconds.`
    : '';
  return `${result?.message || 'Local Agent ownership is still pending.'}${retryCopy}`.trim();
}

function setHostRecoveryResult(hostId, result = null) {
  if (!hostId) return;
  const existingTimer = state.hostRecoveryResultTimers.get(hostId);
  if (existingTimer) {
    window.clearTimeout(existingTimer);
    state.hostRecoveryResultTimers.delete(hostId);
  }
  if (!result) {
    state.hostRecoveryResults.delete(hostId);
  } else {
    state.hostRecoveryResults.set(hostId, {
      ...result,
      updatedAt: new Date().toISOString(),
    });
    if (['completed', 'failed', 'cancelled'].includes(result.status)) {
      const timer = window.setTimeout(() => {
        state.hostRecoveryResultTimers.delete(hostId);
        state.hostRecoveryResults.delete(hostId);
        renderHostNav();
      }, 30000);
      state.hostRecoveryResultTimers.set(hostId, timer);
    }
  }
}

function makeHostRecoveryError(hostId, error, code = 'host_recovery_failed') {
  const next = error instanceof Error ? error : new Error(String(error || 'Host recovery failed.'));
  next.code = next.code || code;
  next.hostRecoveryScoped = true;
  next.hostId = hostId;
  return next;
}

function localAgentRecoveryIdentityReady(host, recoveryKind, result) {
  if (!['local_agent_start', 'local_agent_restart'].includes(recoveryKind)) return true;
  const localAgent = host?.localAgent || null;
  const currentPid = Number(localAgent?.pid || 0);
  const referencePid = Number(result?.localAgent?.pid || 0);
  if (localAgent?.status !== 'running' || currentPid <= 0) return false;
  if (recoveryKind === 'local_agent_restart') {
    return referencePid <= 0 || currentPid !== referencePid;
  }
  return referencePid <= 0 || currentPid === referencePid;
}

async function runLocalAgentAction(host, action) {
  if (!host?.hostId || state.localAgentActionBusyId) {
    return;
  }
  state.localAgentActionBusyId = host.hostId;
  const recoveryKind = localAgentRecoveryKind(action);
  const recoveryCopy = hostRecoveryCopy(recoveryKind);
  setHostRecoveryResult(host.hostId, {
    status: 'working',
    message: action === 'stop'
      ? 'Stopping the local Agent...'
      : `${recoveryCopy.label} requested...`,
  });
  renderAll();
  try {
    const result = await fetchJson(`/api/hosts/${encodeURIComponent(host.hostId)}/local-agent`, {
      method: 'POST',
      body: JSON.stringify({
        action,
        label: host.label || host.hostId,
      }),
    });
    if (result?.status === 'ownership_pending') {
      setHostRecoveryResult(host.hostId, {
        status: 'ownership_pending',
        message: ownershipPendingDisplay(result),
        retryAfterMs: result.retryAfterMs || 0,
        ownershipAssessment: result.ownershipAssessment || 'unknown',
      });
      await refreshHostSnapshot().catch(() => null);
      return;
    }
    if (action === 'stop') {
      setHostRecoveryResult(host.hostId, {
        status: 'stopping',
        message: result?.message || 'Waiting for the local Agent to stop.',
      });
      await waitForLocalAgentStopped(host.hostId, { timeoutMs: 60000 });
      setHostRecoveryResult(host.hostId, {
        status: 'completed',
        message: 'Local Agent stopped.',
      });
      await refreshHostSnapshot().catch(() => null);
    } else {
      setHostRecoveryResult(host.hostId, {
        status: 'recovering',
        message: result?.staleOwnershipRecovered
          ? `Recovered stale local Agent ownership. ${recoveryCopy.label} is now in progress.`
          : `${recoveryCopy.label} is in progress.`,
        staleOwnershipRecovered: result?.staleOwnershipRecovered === true,
      });
      await waitForRecoveredHost(host.hostId, {
        timeoutMs: 60000,
        recoveryKind,
        pendingResult: result,
      });
      setHostRecoveryResult(host.hostId, {
        status: 'completed',
        message: `${recoveryCopy.label} completed; the Host is online.`,
        staleOwnershipRecovered: result?.staleOwnershipRecovered === true,
      });
      await refreshHostSnapshot().catch(() => null);
    }
  } catch (error) {
    setHostRecoveryResult(host.hostId, {
      status: 'failed',
      message: error.message,
    });
  } finally {
    state.localAgentActionBusyId = null;
    renderAll();
  }
}

function getHostLifecycleAction(host) {
  const base = {
    label: 'Restart',
    className: 'secondary-button',
    disabled: true,
    title: 'No saved connector or relay-managed local agent can restart this host yet.',
    kind: 'none',
  };
  if (!host?.hostId) {
    return base;
  }

  if (isLocalAgentCandidate(host)) {
    const localAgent = host.localAgent || null;
    const localBusy = state.localAgentActionBusyId === host.hostId;
    const localAction = localAgent?.status === 'running' || localAgent?.status === 'starting' ? 'restart' : 'start';
    return {
      ...base,
      kind: 'local',
      action: localAction,
      label: localBusy
        ? 'Working...'
        : localAction === 'restart'
          ? 'Restart Local'
          : 'Start Local',
      className: localAction === 'restart' ? 'secondary-button' : '',
      disabled: localBusy,
      title: localAgent?.message || 'Manage the host-agent running on this relay machine.',
    };
  }

  const connector = getConnectorForHost(host.hostId);
  if (connector?.connectorId) {
    const busy = state.hostRestartBusyId === host.hostId
      || state.connectorActionBusy?.connectorId === connector.connectorId;
    return {
      ...base,
      kind: 'connector',
      connector,
      label: busy ? 'Restarting...' : 'Restart',
      disabled: busy,
      title: `Restart through saved connector: ${connector.label || connector.connectorId}.`,
    };
  }

  if (host.relayLocal) {
    return {
      ...base,
      title: 'This local host is connected, but it was not started by the relay. Restart its launcher or start a relay-managed local agent first.',
    };
  }

  return base;
}

async function runHostConnectorRestart(host, connector) {
  if (!host?.hostId || !connector?.connectorId || state.hostRestartBusyId) {
    return;
  }
  state.hostRestartBusyId = host.hostId;
  setHostRecoveryResult(host.hostId, {
    status: 'working',
    message: 'HPC connector restart requested...',
  });
  renderAll();
  try {
    const result = await executeConnectorAction(connector, 'restart', connector, {
      refreshAfter: false,
      selectEditor: false,
      reportErrors: false,
      returnCancellationResult: true,
    });
    if (result?.ok) {
      await waitForRecoveredHost(host.hostId, {
        timeoutMs: 90000,
        recoveryKind: 'hpc_connector_restart',
        pendingResult: result,
      });
      setHostRecoveryResult(host.hostId, {
        status: 'completed',
        message: 'HPC connector restart completed; the Host is online.',
      });
      await refreshHostAndConnectorSnapshots().catch(() => null);
      return;
    }
    if (result?.status === 'cancelled') {
      setHostRecoveryResult(host.hostId, {
        status: 'cancelled',
        message: result.message || 'HPC connector restart was cancelled.',
      });
    } else if (result) {
      const error = new Error(`HPC connector restart failed for ${host.label || host.hostId}:\n${connectorActionResultSummary(result)}`);
      setHostRecoveryResult(host.hostId, { status: 'failed', message: error.message });
    } else {
      setHostRecoveryResult(host.hostId, {
        status: 'cancelled',
        message: 'HPC connector restart was cancelled.',
      });
    }
  } catch (error) {
    setHostRecoveryResult(host.hostId, { status: 'failed', message: error.message });
  } finally {
    state.hostRestartBusyId = null;
    renderAll();
  }
}

async function runHostLifecycleAction(host) {
  const action = getHostLifecycleAction(host);
  if (action.disabled) {
    return;
  }
  if (action.kind === 'local') {
    await runLocalAgentAction(host, action.action);
    return;
  }
  if (action.kind === 'connector') {
    await runHostConnectorRestart(host, action.connector);
  }
}

const ACTIVE_HOST_CODEX_UPDATE_STATUSES = new Set([
  'planned',
  'stopping_sessions',
  'updating',
  'checking',
  'installing',
  'verifying',
  'updated',
  'update_failed',
  'resuming',
  'interrupted',
]);

function codexInstallationSourceLabel(source) {
  return {
    npm_global: 'npm global',
    npm_local: 'project local',
    cursor_extension: 'Cursor extension',
    bundled_runtime: 'bundled runtime',
    explicit_unknown: 'explicit binary',
    unknown: 'unknown source',
  }[String(source || '').trim()] || 'unknown source';
}

function codexRuntimeCompatibilityLabel(runtime = {}) {
  const platformArch = [runtime.platform, runtime.arch].filter(Boolean).join('/');
  if (runtime.error) {
    return `${platformArch || 'architecture unknown'} | probe failed`;
  }
  if (runtime.version) {
    return `${platformArch || 'architecture unknown'} | executable verified`;
  }
  return `${platformArch || 'architecture unknown'} | compatibility unknown`;
}

function getHostCodexUpdateDisplay(host) {
  const local = state.hostCodexUpdates.get(host?.hostId) || null;
  const persisted = host?.codexUpdate || null;
  const persistedStatus = String(persisted?.status || persisted?.phase || '').trim().toLowerCase();
  const persistedTerminal = ['completed', 'completed_with_resume_failures', 'failed', 'cancelled'].includes(persistedStatus);
  const sameOperation = local?.operationId && local.operationId === persisted?.operationId;
  const localIsNewer = sameOperation
    && Date.parse(String(local.updatedAt || '')) > Date.parse(String(persisted.updatedAt || ''));
  const operation = persistedTerminal ? persisted : (localIsNewer ? local : (persisted || local));
  if (!operation) return null;
  return {
    ...operation,
    status: String(operation.status || operation.phase || '').trim().toLowerCase(),
    message: String(operation.message || '').trim(),
  };
}

function setHostCodexUpdateDisplay(hostId, patch = null) {
  if (!patch) {
    state.hostCodexUpdates.delete(hostId);
  } else {
    state.hostCodexUpdates.set(hostId, {
      ...(state.hostCodexUpdates.get(hostId) || {}),
      ...patch,
      updatedAt: new Date().toISOString(),
    });
  }
  renderHostNav();
}

function getHostCodexUpdateAction(host) {
  const operation = getHostCodexUpdateDisplay(host);
  const status = operation?.status || '';
  const busy = state.hostCodexUpdateBusyId === host?.hostId;
  const recoverableStatus = [
    'planned',
    'stopping_sessions',
    'updated',
    'update_failed',
    'resuming',
    'interrupted',
  ].includes(status);
  if (recoverableStatus && !busy) {
    const maintenanceStatus = String(host?.codexMaintenance?.status || '').trim().toLowerCase();
    const updaterActive = ['checking', 'updating', 'installing', 'verifying'].includes(maintenanceStatus);
    return {
      label: updaterActive ? maintenanceStatus.replaceAll('_', ' ') : 'Recover Sessions',
      disabled: updaterActive || !host?.online,
      recover: !updaterActive,
      title: updaterActive
        ? (host.codexMaintenance?.message || 'The Host updater is still active.')
        : (operation.message || 'Recover stopped Sessions and finish the interrupted maintenance operation.'),
    };
  }
  if (ACTIVE_HOST_CODEX_UPDATE_STATUSES.has(status)) {
    return {
      label: status.replaceAll('_', ' '),
      disabled: true,
      recover: false,
      title: operation.message || `Codex maintenance is ${status}.`,
    };
  }
  if (!host?.online) {
    return { label: 'Update Codex', disabled: true, recover: false, title: 'Start or reconnect this Host first.' };
  }
  if (host.capabilities?.codexUpdateV1 !== true) {
    return { label: 'Update Codex', disabled: true, recover: false, title: 'Restart this Host Agent with the development build to enable Codex updates.' };
  }
  if (!host.codexRuntime) {
    return { label: 'Update Codex', disabled: true, recover: false, title: 'Codex version has not been reported by this Host yet.' };
  }
  if (host.codexRuntime.canAutoUpdate !== true) {
    return {
      label: 'Update Codex',
      disabled: true,
      recover: false,
      title: host.codexRuntime.updateReason || 'This Codex installation cannot be updated automatically.',
    };
  }
  return {
    label: busy ? 'Preparing...' : 'Update Codex',
    disabled: busy,
    recover: false,
    title: 'Update this Host npm-global Codex installation to the latest release.',
  };
}

function findCurrentCodexUpdateSession(snapshot) {
  const key = getSessionKey(snapshot);
  return state.sessions.find((session) => getSessionKey(session) === key) || null;
}

function codexUpdateSessionIsStopping(session) {
  const runtime = getRuntimeForSession(session) || session?.runtime || {};
  return String(session?.state || '').trim().toLowerCase() === 'ending'
    || String(runtime.phase || '').trim().toLowerCase() === 'ending'
    || String(runtime.connection || '').trim().toLowerCase() === 'closing'
    || String(runtime.currentTurnStatus || '').trim().toLowerCase() === 'stopping';
}

function openHostCodexRecoveryDialog(host, operation) {
  const sessions = (operation?.sessions || []).map((snapshot) => {
    const current = findCurrentCodexUpdateSession(snapshot);
    return current ? { ...snapshot, ...current } : { ...snapshot, source: 'managed', live: false };
  });
  openSessionActionDialog({
    mode: 'codex-update',
    hostId: host.hostId,
    codexRuntime: host.codexRuntime,
    codexUpdateOperation: operation,
    title: `Recover Sessions on ${host.label || host.hostId}`,
    subtitle: 'Resume every Session that was stopped by the interrupted Codex maintenance operation, then release the maintenance gate.',
    actionLabel: 'Recover Sessions',
    sessions,
  });
  for (const session of sessions) {
    state.sessionActionDialog.resultsByKey.set(getSessionKey(session), session.live
      ? (codexUpdateSessionIsStopping(session)
        ? { status: 'stopping', message: 'Waiting for the pending Stop to finish' }
        : { status: 'resumed', message: 'Already live' })
      : { status: 'left-stopped', message: 'Waiting for recovery' });
  }
  state.sessionActionDialog.phase = 'recovery';
  state.sessionActionDialog.updateResult = {
    message: operation.message || 'Interrupted maintenance requires Session recovery.',
  };
  renderSessionActionDialog();
}

function openHostCodexUpdateDialog(host) {
  const sessions = getRelayManagedLiveSessions([host.hostId]);
  openSessionActionDialog({
    mode: 'codex-update',
    hostId: host.hostId,
    codexRuntime: host.codexRuntime,
    title: `Update Codex on ${host.label || host.hostId}`,
    subtitle: sessions.length
      ? `All ${sessions.length} managed live Session(s) on this Host will stop, Codex will update, then each Session will resume.`
      : 'Codex will update after the Host confirms that no managed Session is live.',
    actionLabel: 'Stop, update, and resume',
    sessions,
  });
  for (const session of sessions) {
    if (isFreshLiveManagedSessionWithoutHistory(session)) {
      state.sessionActionDialog.resultsByKey.set(getSessionKey(session), {
        status: 'blocked',
        message: 'Send the first message or end this empty Session before updating Codex.',
      });
    }
  }
  renderSessionActionDialog();
}

async function runHostCodexUpdateAction(host) {
  const action = getHostCodexUpdateAction(host);
  if (action.disabled) return;
  if (action.recover) {
    const operation = getHostCodexUpdateDisplay(host);
    openHostCodexRecoveryDialog(host, operation);
    return;
  }
  openHostCodexUpdateDialog(host);
}

function renderHostNav() {
  const hostList = el('host-overview-list');
  hostList.innerHTML = '';

  for (const host of state.hosts) {
    const item = document.createElement('div');
    item.className = `host-card ${host.hostId === state.selectedHostId ? 'active' : ''}`;
    const localAgentLabel = host.localAgent?.status
      ? ` | local ${host.localAgent.status}`
      : '';
    const codexRuntime = host.codexRuntime || {};
    const codexLabel = codexRuntime.version ? `Codex ${codexRuntime.version}` : 'Codex unknown';
    const codexSource = codexInstallationSourceLabel(codexRuntime.source);
    const codexCompatibility = codexRuntimeCompatibilityLabel(codexRuntime);
    const codexUpdate = getHostCodexUpdateDisplay(host);
    const hostRecovery = state.hostRecoveryResults.get(host.hostId) || null;
    const hostRecoveryHtml = hostRecovery
      ? `<div class="host-recovery-status ${escapeHtml(hostRecovery.status || '')}">${escapeHtml(hostRecovery.message || '')}</div>`
      : '';

    const top = document.createElement('div');
    top.className = 'host-card-top';
    top.innerHTML = `
      <div>
        <div class="title">${escapeHtml(host.label || host.hostId)}</div>
        <div class="sub">${escapeHtml(host.platform || 'unknown')} | ${host.online ? 'online' : 'offline'}${escapeHtml(localAgentLabel)} | ${host.sessionCount || 0} dialogs</div>
        <div class="host-codex-status ${escapeHtml(codexUpdate?.status || '')}" title="${escapeHtml(codexRuntime.error || codexRuntime.updateReason || codexRuntime.realPath || codexRuntime.binPath || '')}">${escapeHtml(codexLabel)} | ${escapeHtml(codexSource)} | ${escapeHtml(codexCompatibility)}${codexUpdate ? ` | ${escapeHtml(codexUpdate.message || codexUpdate.status)}` : ''}</div>
        ${hostRecoveryHtml}
      </div>
    `;

    const actions = document.createElement('div');
    actions.className = 'host-actions';

    const switchButton = createActionButton('Switch', 'secondary-button');
    switchButton.disabled = state.hostSwitchBusyId === host.hostId;
    switchButton.textContent = state.hostSwitchBusyId === host.hostId ? 'Checking...' : 'Switch';
    switchButton.onclick = async (event) => {
      event.stopPropagation();
      try {
        await setSelectedHost(host.hostId);
      } catch (error) {
        reportError(error);
      }
    };

    const restartButton = createActionButton('Restart', 'secondary-button');
    const lifecycleAction = getHostLifecycleAction(host);
    restartButton.textContent = lifecycleAction.label;
    restartButton.className = `action-button ${lifecycleAction.className}`;
    restartButton.disabled = lifecycleAction.disabled;
    restartButton.title = lifecycleAction.title;
    restartButton.onclick = async (event) => {
      event.stopPropagation();
      await runHostLifecycleAction(host);
    };

    const codexUpdateButton = createActionButton('Update Codex', 'secondary-button');
    const codexUpdateAction = getHostCodexUpdateAction(host);
    codexUpdateButton.textContent = codexUpdateAction.label;
    codexUpdateButton.disabled = codexUpdateAction.disabled;
    codexUpdateButton.title = codexUpdateAction.title;
    codexUpdateButton.onclick = async (event) => {
      event.stopPropagation();
      try {
        await runHostCodexUpdateAction(host);
      } catch (error) {
        reportError(error);
      }
    };

    let stopLocalButton = null;
    if (host.localAgent?.status === 'running' || host.localAgent?.status === 'starting') {
      const localAgent = host.localAgent || null;
      const localBusy = state.localAgentActionBusyId === host.hostId;
      stopLocalButton = createActionButton('Stop Local', 'danger-button');
      stopLocalButton.disabled = localBusy;
      stopLocalButton.title = localAgent?.message || 'Stop the relay-managed local host-agent.';
      stopLocalButton.onclick = async (event) => {
        event.stopPropagation();
        await runLocalAgentAction(host, 'stop');
      };
    }

    const deleteButton = createActionButton('Delete', 'danger-button');
    deleteButton.onclick = async (event) => {
      event.stopPropagation();
      await deleteHost(host.hostId);
    };

    actions.append(switchButton, restartButton, codexUpdateButton);
    if (stopLocalButton) {
      actions.appendChild(stopLocalButton);
    }
    actions.appendChild(deleteButton);
    item.append(top, actions);
    item.onclick = () => {
      setSelectedHost(host.hostId).catch(reportError);
    };
    hostList.appendChild(item);
  }
}

function renderHostSwitcher() {
  const switcher = el('host-switcher');
  const button = el('host-switcher-button');
  const menu = el('host-switcher-menu');
  const selectedHostId = state.selectedHostId || '';
  switcher.innerHTML = '';

  if (!state.hosts.length) {
    const option = document.createElement('option');
    option.value = '';
    option.textContent = 'No hosts available';
    switcher.appendChild(option);
    switcher.disabled = true;
    renderMobileSelectMenu({
      button,
      menu,
      label: 'No hosts available',
      options: [],
      selectedValue: '',
      open: false,
      disabled: true,
    });
    return;
  }

  const mobileOptions = [];
  for (const host of state.hosts) {
    const option = document.createElement('option');
    option.value = host.hostId;
    option.textContent = `${host.label} (${host.online ? 'online' : 'offline'})`;
    switcher.appendChild(option);
    mobileOptions.push({
      value: host.hostId,
      label: option.textContent,
      disabled: Boolean(state.hostSwitchBusyId),
    });
  }

  switcher.disabled = Boolean(state.hostSwitchBusyId);
  switcher.value = selectedHostId;
  const selectedHost = getHost(selectedHostId) || state.hosts[0];
  const buttonLabel = state.hostSwitchBusyId
    ? 'Checking host...'
    : selectedHost
      ? `${selectedHost.label} (${selectedHost.online ? 'online' : 'offline'})`
      : 'Select host';
  renderMobileSelectMenu({
    button,
    menu,
    label: buttonLabel,
    options: mobileOptions,
    selectedValue: selectedHostId,
    open: state.mobileMenus.hostSwitcher,
    disabled: Boolean(state.hostSwitchBusyId),
    onSelect: async (hostId) => {
      if (hostId) {
        await setSelectedHost(hostId);
      }
    },
  });
}

function getVariantLabels(sessions) {
  const labels = new Map();
  const counters = {
    live: 0,
    resumeLive: 0,
    forkLive: 0,
    managed: 0,
    resumed: 0,
    fork: 0,
    starting: 0,
  };

  function nextLabel(key, single, multiPrefix) {
    counters[key] += 1;
    return counters[key] === 1 ? single : `${multiPrefix} ${counters[key]}`;
  }

  let liveIndex = 0;

  for (const session of sessions) {
    if (session.source !== 'managed') {
      labels.set(session.sessionId, 'History');
      continue;
    }

    if (session.state === 'starting') {
      labels.set(session.sessionId, nextLabel('starting', 'Starting', 'Starting'));
      continue;
    }

    if (session.launchMode === 'resume') {
      labels.set(
        session.sessionId,
        session.live
          ? nextLabel('resumeLive', 'Resumed Live', 'Resumed Live')
          : nextLabel('resumed', 'Resumed', 'Resumed')
      );
      continue;
    }

    if (session.launchMode === 'fork') {
      labels.set(
        session.sessionId,
        session.live
          ? nextLabel('forkLive', 'Fork Live', 'Fork Live')
          : nextLabel('fork', 'Fork', 'Fork')
      );
      continue;
    }

    if (session.live) {
      liveIndex += 1;
      labels.set(session.sessionId, liveIndex === 1 ? 'Live' : `Live ${liveIndex}`);
      continue;
    }

    labels.set(session.sessionId, nextLabel('managed', 'Managed', 'Managed'));
  }

  return labels;
}

function renderVariantButtons(container, conversation, selectedSessionId) {
  container.innerHTML = '';

  if (!conversation || !conversation.sessions.length) {
    const empty = document.createElement('div');
    empty.className = 'empty-state';
    empty.textContent = 'No variants are available for this conversation yet.';
    container.appendChild(empty);
    return;
  }

  const labels = getVariantLabels(conversation.sessions);
  for (const session of conversation.sessions) {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = `variant-chip ${session.live ? 'live' : 'history'} ${session.sessionId === selectedSessionId ? 'active' : ''}`.trim();
    button.textContent = labels.get(session.sessionId) || 'Session';
    button.title = `${session.title || session.sessionId}\n${session.sessionId}`;
    button.onclick = (event) => {
      event.stopPropagation();
      selectSession(session, { trusted: event.isTrusted === true }).catch(reportError);
    };
    container.appendChild(button);
  }
}

function renderCollectionTabs() {
  const select = el('session-collection-select');
  const button = el('session-collection-button');
  const menu = el('session-collection-menu');
  const popover = el('collection-manager-popover');
  const list = el('collection-manager-list');
  if (!select) {
    return;
  }

  select.innerHTML = '';
  const mobileOptions = [];
  for (const collection of state.sessionCollections) {
    const option = document.createElement('option');
    option.value = collection.collectionId;
    option.textContent = `${collection.name || 'Collection'} (${collection.itemCount || 0})`;
    select.appendChild(option);
    mobileOptions.push({
      value: collection.collectionId,
      label: option.textContent,
    });
  }
  select.value = state.selectedCollectionId;
  const selectedCollection = getSelectedCollection();
  renderMobileSelectMenu({
    button,
    menu,
    label: selectedCollection
      ? `${selectedCollection.name || 'Collection'} (${selectedCollection.itemCount || 0})`
      : 'Default',
    options: mobileOptions,
    selectedValue: state.selectedCollectionId,
    open: state.mobileMenus.collection,
    onSelect: async (collectionId) => {
      state.selectedCollectionId = collectionId || 'default';
      renderAll();
    },
  });

  if (popover) {
    popover.classList.toggle('hidden', !state.collectionManagerOpen);
  }
  if (!list) {
    return;
  }
  list.innerHTML = '';
  for (const collection of state.sessionCollections) {
    const row = document.createElement('div');
    row.className = 'collection-manager-row';
    const isDefault = collection.collectionId === DEFAULT_COLLECTION_ID;
    const isTrash = collection.collectionId === TRASH_COLLECTION_ID;
    row.innerHTML = `
      <div class="collection-manager-copy">
        <strong>${escapeHtml(collection.name || 'Collection')}</strong>
        <span>${escapeHtml(isDefault
          ? 'Default collection keeps every visible session.'
          : isTrash
            ? `${collection.itemCount || 0} conversation${collection.itemCount === 1 ? '' : 's'} waiting for restore or discard.`
            : `${collection.itemCount || 0} saved conversation${collection.itemCount === 1 ? '' : 's'}.`)}</span>
      </div>
    `;
    const actions = document.createElement('div');
    actions.className = 'collection-manager-actions';
    if (isTrash) {
      const emptyButton = document.createElement('button');
      emptyButton.type = 'button';
      emptyButton.className = 'danger-button';
      emptyButton.textContent = 'Empty trash';
      emptyButton.disabled = !Number(collection.itemCount || 0);
      emptyButton.onclick = async () => {
        if (!window.confirm('Empty trash? These conversations will disappear from this app and cannot be restored from Trash. Codex history files will not be deleted.')) {
          return;
        }
        try {
          await emptyTrashCollection();
        } catch (error) {
          reportError(error);
        }
      };
      actions.appendChild(emptyButton);
    } else if (!isDefault) {
      const renameButton = document.createElement('button');
      renameButton.type = 'button';
      renameButton.className = 'secondary-button';
      renameButton.textContent = 'Rename';
      renameButton.onclick = async () => {
        const currentName = collection.name || 'Collection';
        const nextName = window.prompt(`Rename collection "${currentName}" to:`, currentName);
        const trimmed = String(nextName || '').trim();
        if (!trimmed || trimmed === currentName) {
          return;
        }
        if (!window.confirm(`Rename "${currentName}" to "${trimmed}"?`)) {
          return;
        }
        try {
          await renameSessionCollection(collection.collectionId, trimmed);
        } catch (error) {
          reportError(error);
        }
      };
      const deleteButton = document.createElement('button');
      deleteButton.type = 'button';
      deleteButton.className = 'danger-button';
      deleteButton.textContent = 'Delete';
      deleteButton.onclick = async () => {
        if (!window.confirm(`Delete collection "${collection.name || 'Collection'}"? Sessions will stay in Default.`)) {
          return;
        }
        try {
          await deleteSessionCollection(collection.collectionId);
        } catch (error) {
          reportError(error);
        }
      };
      actions.append(renameButton, deleteButton);
    } else {
      const badge = document.createElement('span');
      badge.className = 'collection-manager-badge';
      badge.textContent = 'System';
      actions.appendChild(badge);
    }
    row.appendChild(actions);
    list.appendChild(row);
  }
}

function renderConversationNav() {
  const list = el('session-list');
  list.innerHTML = '';

  const host = getHost(state.selectedHostId);
  el('selected-host-title').textContent = host ? host.label : 'No host selected';
  el('selected-host-meta').textContent = host ? `${host.platform} | ${host.online ? 'online' : 'offline'}` : '';
  renderHostSwitcher();
  renderCollectionTabs();

  const collection = getSelectedCollection();
  const groups = getConversationGroupsForCollection(collection);
  const visibleGroups = sortConversationGroups(filterConversationGroupsWithSearch(groups));
  const searchInput = el('session-search-input');
  const searchMode = el('session-search-mode');
  const searchModeButton = el('session-search-mode-button');
  const searchModeMenu = el('session-search-mode-menu');
  const sortMode = el('session-sort-mode');
  const sortModeButton = el('session-sort-mode-button');
  const sortModeMenu = el('session-sort-mode-menu');
  const sortDirButton = el('session-sort-dir-button');
  const searchSummary = el('session-search-summary');
  const clearSearchButton = el('clear-session-search-button');
  if (searchInput && document.activeElement !== searchInput) {
    searchInput.value = state.sessionSearchQuery;
  }
  if (searchMode) {
    searchMode.value = state.sessionSearchMode;
  }
  renderMobileSelectMenu({
    button: searchModeButton,
    menu: searchModeMenu,
    label: getSessionSearchModeLabel(state.sessionSearchMode),
    options: Object.entries(SESSION_SEARCH_MODE_LABELS).map(([value, label]) => ({ value, label })),
    selectedValue: state.sessionSearchMode,
    open: state.mobileMenus.searchMode,
    onSelect: async (mode) => {
      setSessionSearchMode(mode);
    },
  });
  if (sortMode) {
    sortMode.value = state.sessionSortBy;
  }
  renderMobileSelectMenu({
    button: sortModeButton,
    menu: sortModeMenu,
    label: getSessionSortLabel(state.sessionSortBy),
    options: Object.entries(SESSION_SORT_LABELS).map(([value, label]) => ({ value, label })),
    selectedValue: state.sessionSortBy,
    open: state.mobileMenus.sortBy,
    onSelect: async (mode) => {
      setSessionSortBy(mode);
    },
  });
  if (sortDirButton) {
    sortDirButton.textContent = state.sessionSortDir === 'asc' ? 'Asc' : 'Desc';
    sortDirButton.title = state.sessionSortDir === 'asc' ? 'Oldest or smallest first' : 'Newest or largest first';
  }
  if (searchSummary) {
    const query = state.sessionSearchQuery.trim();
    const scope = collection.collectionId === DEFAULT_COLLECTION_ID
      ? `Default on ${host?.label || 'selected host'}`
      : collection.name;
    const fullMatchCount = state.sessionSearchResults.length;
    const loadingText = state.sessionSearchLoading ? ' Searching full history...' : '';
    searchSummary.textContent = query
      ? `${visibleGroups.length} of ${groups.length} in ${scope} match "${query}"${fullMatchCount ? ` | ${fullMatchCount} full-history hits` : ''}.${loadingText}`
      : groups.length
        ? `${groups.length} conversations in ${scope}`
        : '';
  }
  if (clearSearchButton) {
    clearSearchButton.classList.toggle('hidden', !state.sessionSearchQuery.trim());
  }

  if (!groups.length) {
    const empty = document.createElement('div');
    empty.className = 'empty-state';
    empty.textContent = collection.collectionId === DEFAULT_COLLECTION_ID
      ? 'Import a host or start a managed session to see conversations here.'
      : collection.collectionId === TRASH_COLLECTION_ID
        ? 'Trash is empty.'
        : 'This collection is empty. Save a conversation into it from Default.';
    list.appendChild(empty);
    return;
  }
  if (!visibleGroups.length) {
    const empty = document.createElement('div');
    empty.className = 'empty-state';
    empty.textContent = 'No conversations match this search.';
    list.appendChild(empty);
    return;
  }

  for (const group of visibleGroups) {
    const apiSummary = getSessionApiProfileSummary(group.preferredSession || group.sessions?.[0] || {
      hostId: group.hostId,
      apiProfile: group.apiProfile,
    });
    const preview = group.latestUserMessage
      ? `You: ${truncatePreview(group.latestUserMessage)}`
      : group.latestAgentMessage
        ? `Codex: ${truncatePreview(group.latestAgentMessage)}`
        : 'No prompt preview available';

    const item = document.createElement('div');
    item.className = `conversation-card ${group.liveCount > 0 ? 'live' : 'history'} ${hasUnreadMessagesForGroup(group) ? 'message-unread' : ''} ${group.conversationKey === state.selectedConversationKey ? 'active' : ''}`.trim();
    const createdLabel = formatTime(group.createdAt) || 'Unknown';
    const updatedLabel = formatTime(group.lastUpdatedAt) || 'Unknown';
    const messageCount = Number(group.messageCount || 0);
    item.innerHTML = `
      <div class="conversation-card-top">
        <div>
          <div class="title">${escapeHtml(group.title || group.conversationKey)}</div>
          <div class="sub">${escapeHtml(group.hostLabel || getHost(group.hostId)?.label || group.hostId)} | ${group.liveCount > 0 ? `${group.liveCount} live` : 'history only'} | ${group.totalCount} variants</div>
        </div>
        <div class="conversation-stats">
          <div class="count">${group.totalCount}</div>
          <div class="label">sessions</div>
        </div>
      </div>
      <div class="path">${escapeHtml(group.cwd || '(unknown path)')}</div>
      <div class="conversation-tag-row">
        <span class="api-profile-chip ${apiSummary.source === 'recorded' ? 'recorded' : 'fallback'}" title="${escapeHtml(apiSummary.title)}">${escapeHtml(apiSummary.label)}</span>
      </div>
      <div class="conversation-time-grid">
        <span><strong>Created</strong>${escapeHtml(createdLabel)}</span>
        <span><strong>Updated</strong>${escapeHtml(updatedLabel)}</span>
        <span><strong>Messages</strong>${messageCount}</span>
      </div>
      <div class="conversation-summary">
        <span>${escapeHtml(formatTime(group.lastUpdatedAt) || 'No recent activity')}</span>
        <span>${group.liveCount > 0 ? 'Joinable live session' : 'History can be resumed'}</span>
      </div>
      <div class="preview">${escapeHtml(preview)}</div>
    `;

    const variantRow = document.createElement('div');
    variantRow.className = 'variant-row';
    renderVariantButtons(variantRow, group, state.selectedSessionId);
    if (group.liveCount > 0) {
      const liveDot = document.createElement('span');
      liveDot.className = 'conversation-live-dot';
      liveDot.title = 'Live session';
      item.appendChild(liveDot);
    }
    item.appendChild(variantRow);

    const searchResults = getSearchResultsForGroup(group);
    if (searchResults.length) {
      item.appendChild(renderConversationSearchHits(group, searchResults));
    }

    const actions = document.createElement('div');
    actions.className = 'conversation-card-actions';
    const moveKey = `${group.hostId}::${group.conversationKey}`;
    const moveOpen = state.mobileMenus.collectionMoveKey === moveKey;
    item.classList.toggle('collection-menu-open', moveOpen);
    const moveAnchor = document.createElement('div');
    moveAnchor.className = 'mobile-select-anchor collection-move-anchor';
    const collectionSelect = document.createElement('select');
    collectionSelect.className = 'collection-move-select native-select-control mobile-replaced-select';
    collectionSelect.innerHTML = '<option value="">Save to collection...</option>';
    const isTrashCollection = collection.collectionId === TRASH_COLLECTION_ID;
    const collectionTargets = state.sessionCollections.filter((entry) => entry.collectionId !== DEFAULT_COLLECTION_ID && entry.collectionId !== TRASH_COLLECTION_ID);
    for (const target of collectionTargets) {
      const option = document.createElement('option');
      option.value = target.collectionId;
      option.textContent = target.name;
      collectionSelect.appendChild(option);
    }
    collectionSelect.disabled = isTrashCollection || group.collectionOnly || collectionTargets.length < 1;
    collectionSelect.onclick = (event) => event.stopPropagation();
    collectionSelect.onchange = async (event) => {
      event.stopPropagation();
      const targetCollectionId = event.target.value;
      event.target.value = '';
      if (!targetCollectionId) {
        return;
      }
      try {
        await addConversationToCollection(targetCollectionId, group);
      } catch (error) {
        reportError(error);
      }
    };
    const moveButton = document.createElement('button');
    moveButton.type = 'button';
    moveButton.className = 'secondary-button mobile-select-button collection-move-button';
    moveButton.textContent = 'Save to collection...';
    moveButton.disabled = collectionSelect.disabled;
    moveButton.setAttribute('aria-expanded', moveOpen ? 'true' : 'false');
    moveButton.onclick = (event) => {
      event.preventDefault();
      event.stopPropagation();
      if (!moveButton.disabled) {
        toggleMobileSelectMenu('collectionMoveKey', moveKey);
      }
    };
    const moveMenu = document.createElement('div');
    moveMenu.className = `mobile-select-menu collection-move-menu ${moveOpen ? '' : 'hidden'}`.trim();
    moveMenu.setAttribute('role', 'menu');
    renderMobileSelectMenu({
      button: moveButton,
      menu: moveMenu,
      label: 'Save to collection...',
      options: collectionTargets.map((target) => ({
        value: target.collectionId,
        label: target.name || 'Collection',
      })),
      selectedValue: '',
      open: moveOpen,
      disabled: collectionSelect.disabled,
      onSelect: async (targetCollectionId) => {
        if (targetCollectionId) {
          await addConversationToCollection(targetCollectionId, group);
        }
      },
    });
    moveAnchor.append(collectionSelect, moveButton, moveMenu);
    actions.appendChild(moveAnchor);
    if (isTrashCollection) {
      const restoreButton = document.createElement('button');
      restoreButton.type = 'button';
      restoreButton.className = 'secondary-button collection-restore-button';
      restoreButton.textContent = 'Restore';
      restoreButton.onclick = async (event) => {
        event.stopPropagation();
        const conversationTitle = group.title || group.conversationKey || 'this conversation';
        const sources = Array.isArray(group.collectionItem?.trashedFrom) ? group.collectionItem.trashedFrom : [];
        const sourceText = sources.length
          ? sources.map((source) => source.name || source.collectionId).join(', ')
          : 'its original collections';
        if (!window.confirm(`Restore "${conversationTitle}" to ${sourceText}?`)) {
          return;
        }
        try {
          await restoreConversationFromTrash(group);
        } catch (error) {
          reportError(error);
        }
      };
      actions.appendChild(restoreButton);
    } else if (collection.collectionId !== DEFAULT_COLLECTION_ID) {
      const removeButton = document.createElement('button');
      removeButton.type = 'button';
      removeButton.className = 'secondary-button collection-remove-button';
      removeButton.textContent = 'Remove';
      removeButton.onclick = async (event) => {
        event.stopPropagation();
        const conversationTitle = group.title || group.conversationKey || 'this conversation';
        const collectionName = collection.name || 'this collection';
        if (!window.confirm(`Remove "${conversationTitle}" from collection "${collectionName}"?`)) {
          return;
        }
        try {
          await removeConversationFromCollection(collection.collectionId, group);
        } catch (error) {
          reportError(error);
        }
      };
      actions.appendChild(removeButton);
    }
    if (!isTrashCollection) {
      const trashButton = document.createElement('button');
      trashButton.type = 'button';
      trashButton.className = 'danger-button collection-trash-button';
      trashButton.textContent = 'Move to trash';
      trashButton.disabled = group.collectionOnly;
      trashButton.onclick = async (event) => {
        event.stopPropagation();
        const conversationTitle = group.title || group.conversationKey || 'this conversation';
        try {
          const previewResult = await previewConversationTrash(group);
          const sources = previewResult.previousCollections || [];
          const sourceText = sources.length
            ? sources.map((source) => source.name || source.collectionId).join(', ')
            : 'no saved collection';
          if (!window.confirm(`Move "${conversationTitle}" to Trash? It currently exists in: ${sourceText}. It will be removed from those collections and can be restored later.`)) {
            return;
          }
          await moveConversationToTrash(group);
        } catch (error) {
          reportError(error);
        }
      };
      actions.appendChild(trashButton);
    }
    item.appendChild(actions);

    item.onclick = (event) => {
      if (!group.collectionOnly) {
        selectConversation(group, { trusted: event.isTrusted === true }).catch(reportError);
      }
    };
    list.appendChild(item);
  }
}

function renderConversationSearchHits(group, results) {
  const box = document.createElement('div');
  box.className = 'conversation-search-hits';
  const query = state.sessionSearchQuery;
  const matches = [];
  for (const result of results.slice(0, 3)) {
    for (const match of (result.matches || []).slice(0, 3)) {
      matches.push({ result, match });
      if (matches.length >= 4) {
        break;
      }
    }
    if (matches.length >= 4) {
      break;
    }
  }

  for (const { result, match } of matches) {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'conversation-search-hit';
    button.dataset.searchHostId = result.hostId;
    button.dataset.searchSessionId = result.sessionId;
    button.dataset.searchEntryIndex = String(match.entryIndex ?? -1);
    button.innerHTML = `
      <span class="conversation-search-hit-meta">${escapeHtml(match.speaker || match.type || 'match')} ${escapeHtml(formatTime(match.timestamp) || '')}</span>
      <span class="conversation-search-hit-snippet">${highlightSearchSnippet(match.snippet || '', query)}</span>
    `;
    button.onclick = async (event) => {
      event.preventDefault();
      event.stopPropagation();
      try {
        await openSearchResult(result, match, group);
      } catch (error) {
        reportError(error);
      }
    };
    box.appendChild(button);
  }
  return box;
}

function modelCatalogRunId(session) {
  const runtimeConfig = session?.runtimeConfig || {};
  return String(runtimeConfig.runId
    || runtimeConfig.activeRunId
    || session?.activeRunId
    || session?.runId
    || session?.nativeThreadId
    || 'history');
}

function modelCacheKey(session) {
  const bindingFingerprint = sessionApiBinding(session)?.bindingFingerprint || 'unknown';
  return [
    session?.hostId || 'none',
    session?.sessionId || 'none',
    bindingFingerprint,
    sessionApiProviderKind(session),
    modelCatalogRunId(session),
  ].map((value) => encodeURIComponent(String(value))).join('::');
}

function sessionApiProviderKind(session) {
  const binding = sessionApiBinding(session);
  if (binding?.providerKind) {
    return inferApiProviderKind({ providerKind: binding.providerKind });
  }
  const profile = binding?.kind === 'profile'
    ? (state.ui.apiProfiles || []).find((candidate) => (
      candidate.profileId === binding.profileId
      && apiBindingMatchesProfileIdentity(binding, candidate)
    ))
    : null;
  return inferApiProviderKind(profile || {
    provider: binding?.provider || binding?.modelProviderHint || '',
  });
}

function localConfigRevision(value) {
  const text = String(value || '');
  const hashes = [0x811c9dc5, 0x9e3779b9, 0x85ebca6b, 0xc2b2ae35];
  const multipliers = [0x01000193, 0x27d4eb2d, 0x165667b1, 0x85ebca77];
  for (let index = 0; index < text.length; index += 1) {
    const code = text.charCodeAt(index);
    for (let lane = 0; lane < hashes.length; lane += 1) {
      hashes[lane] = Math.imul(
        hashes[lane] ^ (code + Math.imul(index + 1, lane + 1)),
        multipliers[lane]
      );
      hashes[lane] ^= hashes[lane] >>> (11 + lane);
    }
  }
  const digest = hashes.map((hash, lane) => {
    let value32 = hash ^ (hash >>> 16);
    value32 = Math.imul(value32, multipliers[(lane + 1) % multipliers.length]);
    value32 ^= value32 >>> 13;
    return (value32 >>> 0).toString(16).padStart(8, '0');
  }).join('');
  return `${text.length}-${digest}`;
}

function rebindProfilePreviewIdentity(profile) {
  const config = apiProfileRequestConfig(profile) || {};
  return [
    config.profileId || '',
    config.providerKind || '',
    String(config.provider || 'OpenAI').trim().toLowerCase(),
    effectiveApiBaseUrl(config),
    localConfigRevision(config.apiKey),
  ].map((value) => encodeURIComponent(String(value))).join(':');
}

function activeModelCatalogKey(session) {
  return modelCacheKey(session);
}

function getActiveModelCatalog(session) {
  if (!session) {
    return null;
  }
  return state.codexControls.modelCatalogByKey.get(activeModelCatalogKey(session)) || null;
}

function getSessionControlModelCatalog(session) {
  return getActiveModelCatalog(session);
}

function modelIsSelectableCatalogMember(model) {
  return Boolean(
    model
    && model.selectable !== false
    && model.availability !== 'unavailable'
    && model.cliSupported !== false
  );
}

function selectableCatalogModels(catalog) {
  return (catalog?.models || []).filter(modelIsSelectableCatalogMember);
}

function modelCatalogSourceModelCount(catalog, originSource) {
  const origin = String(originSource || '').trim();
  const sources = (catalog?.sources || [])
    .filter((source) => (
      !source?.error
      && (source?.source === origin || source?.originSource === origin)
      && Array.isArray(source.models)
    ))
    .sort((left, right) => Number(right.source === origin && right.stale !== true)
      - Number(left.source === origin && left.stale !== true));
  return sources[0]?.models?.length || 0;
}

function preferredModelForApiSwitch(catalog, options = {}) {
  const models = (catalog?.models || []).filter((model) => (
    modelIsSelectableCatalogMember(model)
    && model?.visible !== false
    && model?.hidden !== true
  ));
  const modelsById = new Map(models.map((model) => [
    String(model?.id || model?.model || '').trim(),
    model,
  ]).filter(([id]) => id));
  const usableId = (candidate) => {
    const id = String(candidate?.id || candidate?.model || candidate || '').trim();
    return id && modelsById.has(id) ? id : '';
  };
  const providerModels = (catalog?.sources || [])
    .filter((source) => (
      (source?.source === 'provider' || source?.originSource === 'provider')
      && !source?.error
      && (options.requireFreshProvider !== true || (
        source?.source === 'provider'
        && source?.stale !== true
      ))
    ))
    .flatMap((source) => Array.isArray(source.models) ? source.models : []);
  const providerDefault = providerModels.find((model) => model?.isDefault === true && usableId(model));
  if (providerDefault) {
    return usableId(providerDefault);
  }
  for (const model of providerModels) {
    const id = usableId(model);
    if (id) {
      return id;
    }
  }
  if (options.requireFreshProvider === true) {
    return '';
  }
  const catalogDefault = usableId(catalog?.defaultModel);
  if (catalogDefault) {
    return catalogDefault;
  }
  const mergedDefault = models.find((model) => model?.isDefault === true);
  return usableId(mergedDefault) || usableId(models[0]);
}

function captureModelCatalogRequest(session) {
  return {
    key: modelCacheKey(session),
    sessionKey: getSessionKey(session),
    hostId: String(session?.hostId || ''),
    sessionId: String(session?.sessionId || ''),
    runId: modelCatalogRunId(session),
    bindingFingerprint: String(sessionApiBinding(session)?.bindingFingerprint || ''),
  };
}

function modelCatalogResponseMatchesRequest(request, response) {
  if (!request || !response || typeof response !== 'object') {
    return false;
  }
  return String(response.hostId || '') === request.hostId
    && String(response.sessionId || '') === request.sessionId
    && String(response.runId || '') === request.runId
    && String(response.sessionBinding?.bindingFingerprint || '') === request.bindingFingerprint;
}

function applyModelCatalogResponse(request, response) {
  const current = state.sessions.find((session) => getSessionKey(session) === request?.sessionKey) || null;
  if (!current || modelCacheKey(current) !== request.key) {
    return null;
  }
  if (!modelCatalogResponseMatchesRequest(request, response)) {
    if (!state.codexControls.modelOptionsRetryAfterBySession.has(request.key)) {
      deferAutoLoadOptions(state.codexControls.modelOptionsRetryAfterBySession, request.key);
    }
    return null;
  }
  const catalog = {
    ...response,
    models: Array.isArray(response.models) ? response.models : [],
    sources: Array.isArray(response.sources) ? response.sources : [],
  };
  state.codexControls.modelCatalogByKey.set(request.key, catalog);
  state.codexControls.modelOptionsRetryAfterBySession.delete(request.key);
  return catalog;
}

function formatBytes(value) {
  const bytes = Number(value || 0);
  if (!Number.isFinite(bytes) || bytes <= 0) {
    return '';
  }
  if (bytes >= 1024 * 1024) {
    return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  }
  if (bytes >= 1024) {
    return `${Math.round(bytes / 1024)} KB`;
  }
  return `${bytes} B`;
}

function textByteLength(value) {
  const text = String(value || '');
  if (typeof TextEncoder !== 'undefined') {
    return new TextEncoder().encode(text).length;
  }
  return unescape(encodeURIComponent(text)).length;
}

function formatTokenNumber(value) {
  const number = Number(value || 0);
  return Number.isFinite(number) && number > 0 ? number.toLocaleString() : '';
}

function fileExtension(name) {
  const text = String(name || '').trim().toLowerCase();
  const index = text.lastIndexOf('.');
  return index === -1 ? '' : text.slice(index + 1);
}

function isTextLikeFile(file) {
  const type = String(file?.type || '').toLowerCase();
  if (type.startsWith('text/')) {
    return true;
  }
  if (type === 'application/json' || type === 'application/x-ndjson' || type === 'application/xml') {
    return true;
  }
  return TEXT_FILE_EXTENSIONS.has(fileExtension(file?.name));
}

function isImageFileRef(file) {
  const mime = String(file?.mime || file?.type || '').toLowerCase();
  return mime.startsWith('image/') || IMAGE_FILE_EXTENSIONS.has(fileExtension(file?.name || file?.path));
}

function formatHostCapabilityName(host) {
  return host?.label || host?.hostId || 'selected host';
}

function isDownloadablePath(value) {
  const text = String(value || '').trim();
  if (!text || /^(https?:|data:|mailto:)/i.test(text)) {
    return false;
  }
  return DOWNLOADABLE_FILE_EXTENSIONS.has(fileExtension(text));
}

function isBareDownloadableFilename(value) {
  const text = String(value || '').trim();
  return Boolean(text)
    && !/[\\/]/.test(text)
    && !/^[A-Za-z]:/.test(text)
    && !text.startsWith('~')
    && isDownloadablePath(text);
}

function stripPathPunctuation(value) {
  let text = String(value || '')
    .trim()
    .replace(/^["'`]+|["'`]+$/g, '')
    .trim();
  if (text.startsWith('<') && text.endsWith('>')) {
    text = text.slice(1, -1).trim();
  }
  return text.replace(/[>)\].,;:!?]+$/g, '');
}

function normalizeRemoteFilePath(value) {
  return String(value || '')
    .trim()
    .replace(/^[\\/]+([A-Za-z]:[\\/])/, '$1');
}

function decodePathCandidate(value) {
  const cleaned = stripPathPunctuation(value);
  try {
    return normalizeRemoteFilePath(decodeURIComponent(cleaned));
  } catch {
    return normalizeRemoteFilePath(cleaned);
  }
}

function extractFileRefsFromText(text) {
  const source = String(text || '');
  const refs = [];
  const addRef = (candidate, label = '') => {
    const pathValue = decodePathCandidate(candidate);
    if (!isDownloadablePath(pathValue)) {
      return;
    }
    if (refs.some((entry) => entry.path === pathValue)) {
      return;
    }
    refs.push({
      name: label || basename(pathValue) || pathValue,
      path: pathValue,
      mime: '',
      size: 0,
      isImage: IMAGE_FILE_EXTENSIONS.has(fileExtension(pathValue)),
    });
  };

  const markdownLinkPattern = /!?\[([^\]]*)\]\(([^)]+)\)/g;
  let match = null;
  while ((match = markdownLinkPattern.exec(source))) {
    addRef(match[2], match[1]);
  }

  const explicitPattern = /remote-codex-file:([^\s"'<>`]+)/g;
  while ((match = explicitPattern.exec(source))) {
    addRef(match[1]);
  }

  // Assistants commonly put output paths in inline code instead of Markdown
  // links. Bare names stay ambiguous; only paths with directory context become
  // file cards.
  const inlineCodePattern = /`([^`\r\n]+)`/g;
  while ((match = inlineCodePattern.exec(source))) {
    const pathValue = decodePathCandidate(match[1]);
    if (!isBareDownloadableFilename(pathValue)) {
      addRef(pathValue);
    }
  }

  const extensionPattern = Array.from(DOWNLOADABLE_FILE_EXTENSIONS).join('|');
  const unixPattern = new RegExp(`(?:~|\\/)[^\\s"'<>\\|` + '`' + `]+?\\.(${extensionPattern})(?=[\\s\\)\\]\\},.;:!?]|$)`, 'gi');
  while ((match = unixPattern.exec(source))) {
    addRef(match[0]);
  }

  const windowsPattern = new RegExp(`[A-Za-z]:\\\\[^\\n"'<>\\|` + '`' + `]+?\\.(${extensionPattern})(?=[\\s\\)\\]\\},.;:!?]|$)`, 'gi');
  while ((match = windowsPattern.exec(source))) {
    addRef(match[0]);
  }

  const relativePattern = new RegExp(
    `(?:^|[\\s\\(\\[\\{])((?:\\.{1,2}[\\\\/])?(?:[A-Za-z0-9_.@+~-]+[\\\\/])*[A-Za-z0-9_.@+~-]+\\.(${extensionPattern}))(?=[\\s\\)\\]\\},.;:!?]|$)`,
    'gi'
  );
  while ((match = relativePattern.exec(source))) {
    const pathValue = decodePathCandidate(match[1]);
    // Markdown labels like [plot.png] are often just display names for an
    // absolute path listed nearby. Treating bare names as paths makes the
    // browser auto-preview missing files and spam repeated download errors.
    if (!isBareDownloadableFilename(pathValue)) {
      addRef(pathValue);
    }
  }

  return refs;
}

function extractDirectoryRefsFromText(text) {
  const source = String(text || '');
  const refs = [];
  const addRef = (candidate) => {
    const pathValue = decodePathCandidate(candidate);
    if (!pathValue || isDownloadablePath(pathValue) || !/[\\/]/.test(pathValue)) {
      return;
    }
    const normalized = normalizeRemoteFilePath(pathValue).replace(/[\\/]+$/, '');
    if (normalized && !refs.includes(normalized)) {
      refs.push(normalized);
    }
  };
  const markdownLinkPattern = /!?\[[^\]]*\]\(([^)]+)\)/g;
  let match = null;
  while ((match = markdownLinkPattern.exec(source))) {
    addRef(match[1]);
  }
  return refs;
}

function receivedFileToTranscriptRef(file) {
  const pathValue = normalizeRemoteFilePath(file?.remotePath || file?.path || '');
  if (!pathValue || !isDownloadablePath(pathValue)) {
    return null;
  }
  return {
    fileId: file.fileId || '',
    name: file.name || basename(pathValue) || pathValue,
    path: pathValue,
    mime: file.mime || '',
    size: Number(file.size || 0) || 0,
    isImage: Boolean(file.isImage) || isImageFileRef({ name: file.name, path: pathValue, mime: file.mime }),
    cached: true,
  };
}

function getCachedReceivedFileRefForPath(session, filePath) {
  const normalizedPath = normalizeRemoteFilePath(filePath || '');
  if (!normalizedPath) {
    return null;
  }
  for (const file of getReceivedFilesForSession(session)) {
    const cachedPath = normalizeRemoteFilePath(file?.remotePath || file?.path || '');
    if (cachedPath !== normalizedPath) {
      continue;
    }
    return receivedFileToTranscriptRef(file);
  }
  return null;
}

function getCachedFileRefsForMentionedDirectories(session, entry) {
  const directories = extractDirectoryRefsFromText(entry?.text || '');
  if (!directories.length) {
    return [];
  }
  const receivedFiles = getReceivedFilesForSession(session);
  if (!receivedFiles.length) {
    return [];
  }
  const refs = [];
  for (const file of receivedFiles) {
    const pathValue = normalizeRemoteFilePath(file?.remotePath || file?.path || '');
    if (!pathValue) {
      continue;
    }
    const matched = directories.some((directory) => pathValue === directory || pathValue.startsWith(`${directory}/`));
    if (!matched) {
      continue;
    }
    const ref = receivedFileToTranscriptRef(file);
    if (ref) {
      refs.push(ref);
    }
  }
  return refs;
}

function getTranscriptFileRefs(session, entry) {
  const explicit = normalizeTranscriptFiles(entry?.files || entry?.attachments || []);
  const extracted = extractFileRefsFromText(entry?.text || '');
  const cachedFromDirectories = getCachedFileRefsForMentionedDirectories(session, entry);
  const seen = new Set();
  const merged = [];
  for (const file of [...explicit, ...extracted, ...cachedFromDirectories]) {
    const key = file.path || file.name;
    if (!key || seen.has(key) || isBareDownloadableFilename(file.path || '')) {
      continue;
    }
    seen.add(key);
    merged.push(file);
  }
  return merged;
}

function buildHostFileUrl(session, file, inline = false) {
  const params = new URLSearchParams({
    path: normalizeRemoteFilePath(file.path || ''),
    sessionId: session?.sessionId || '',
  });
  if (session?.cwd) {
    params.set('cwd', session.cwd);
  }
  if (inline) {
    params.set('inline', '1');
  }
  return `/api/hosts/${encodeURIComponent(session.hostId)}/files/download?${params.toString()}`;
}

function buildReceivedFileUrl(file, inline = false) {
  const params = new URLSearchParams();
  if (inline) {
    params.set('inline', '1');
  }
  return `/api/received-files/${encodeURIComponent(file.fileId)}${params.toString() ? `?${params.toString()}` : ''}`;
}

function normalizeModelOption(model) {
  const modelId = String(model?.model || model?.id || '').trim();
  if (!modelId) {
    return null;
  }
  return {
    ...model,
    id: String(model?.id || modelId).trim(),
    model: modelId,
    displayName: String(model?.displayName || modelId).trim(),
    description: String(model?.description || '').trim(),
    inputModalities: Array.isArray(model?.inputModalities) ? model.inputModalities.map(String) : [],
    reasoningLevels: Array.isArray(model?.reasoningLevels)
      ? model.reasoningLevels.map((value) => String(value || '').trim()).filter(Boolean)
      : [],
    capabilityKnown: model?.capabilityKnown === true,
    capabilitySource: String(model?.capabilitySource || model?.capabilityAuthority || '').trim() || null,
    allowManualEffort: model?.allowManualEffort === true,
    selectable: model?.selectable !== false,
    availability: String(model?.availability || 'unknown'),
    cliSupported: model?.cliSupported ?? 'unknown',
    providerAdvertised: model?.providerAdvertised ?? 'unknown',
    defaultReasoningEffort: String(model?.defaultReasoningEffort || '').trim(),
    hidden: model?.visible === false || Boolean(model?.hidden),
    isDefault: Boolean(model?.isDefault),
    supportsPersonality: model?.supportsPersonality === true,
  };
}

function providerInputForModelCatalog(session) {
  const binding = sessionApiBinding(session);
  if (binding?.providerKind) {
    return {
      provider: binding.provider || binding.modelProviderHint || '',
      providerKind: binding.providerKind,
    };
  }
  if (binding?.kind === 'profile') {
    const matchingProfile = getApiProfiles().find((profile) => (
      profile.profileId === binding.profileId
      && apiBindingMatchesProfileIdentity(binding, profile)
    ));
    return matchingProfile || {
      provider: binding.provider || '',
      providerKind: inferApiProviderKind({ provider: binding.provider || '' }),
    };
  }
  return {
    provider: binding?.provider || binding?.modelProviderHint || '',
    providerKind: inferApiProviderKind({ provider: binding?.provider || binding?.modelProviderHint || '' }),
  };
}

function decorateModelOptionForProvider(session, rawModel) {
  if (rawModel?.capabilityKnown === true) {
    return rawModel;
  }
  const registry = providerCapabilitiesRegistry();
  if (!registry?.resolveModelCapability) {
    return rawModel;
  }
  const modelId = String(rawModel?.model || rawModel?.id || '').trim();
  const capability = registry.resolveModelCapability({
    providerKind: inferApiProviderKind(providerInputForModelCatalog(session)),
    modelId,
  });
  return {
    ...rawModel,
    reasoningLevels: capability.reasoningLevels,
    capabilityKnown: capability.capabilityKnown,
    capabilitySource: capability.source,
    defaultReasoningEffort: capability.defaultReasoningEffort || rawModel?.defaultReasoningEffort || '',
    allowManualEffort: capability.allowManualEffort,
  };
}

function getModelOptions(session) {
  const seen = new Set();
  const models = [];
  const catalog = getSessionControlModelCatalog(session);
  for (const rawModel of catalog?.models || []) {
    const model = normalizeModelOption(decorateModelOptionForProvider(session, rawModel));
    if (!model || seen.has(model.model)) {
      continue;
    }
    seen.add(model.model);
    models.push(model);
  }
  return models;
}

function findModelOption(session, modelId) {
  const normalized = String(modelId || '').trim();
  if (!normalized) {
    return getModelOptions(session).find((model) => model.isDefault) || null;
  }
  return getModelOptions(session).find((model) => model.model === normalized || model.id === normalized) || null;
}

function inferModelCategory(model) {
  const id = String(model?.model || model?.id || '').toLowerCase();
  if (model?.isDefault) {
    return 'Recommended / 默认推荐';
  }
  if (model?.hidden) {
    return 'Hidden / System';
  }
  if (/mini|nano|small|lite/.test(id)) {
    return 'Small / Fast';
  }
  if (/codex|code/.test(id)) {
    return 'Codex / Coding';
  }
  if (/^gpt[-_.]?\d/.test(id)) {
    return 'GPT / General';
  }
  return 'Other';
}

function modelSelectLabel(model) {
  const badges = [];
  if (model.isDefault) {
    badges.push('default');
  }
  if (model.inputModalities.includes('image')) {
    badges.push('img');
  }
  if (model.defaultReasoningEffort) {
    badges.push(model.defaultReasoningEffort);
  }
  return `${model.displayName || model.model}${badges.length ? ` | ${badges.join(' | ')}` : ''}`;
}

function syncModelSelectFromInput(session) {
  const select = el('codex-model-select');
  const input = el('codex-model-input');
  if (!select || !input) {
    return;
  }
  const value = input.value.trim();
  const matched = value
    ? Array.from(select.options || []).find((option) => option.value === value)
    : null;
  const nextValue = matched ? value : '';
  if (select.value !== nextValue) {
    select.value = nextValue;
  }
}

function renderComposerModelOptions(session) {
  const datalist = el('codex-model-options');
  const select = el('codex-model-select');
  if (!datalist || !select) {
    return;
  }

  const allModels = getModelOptions(session);
  const models = allModels.filter(modelIsSelectableCatalogMember);
  const defaultModel = models.find((model) => model.isDefault) || null;
  const defaultLabel = defaultModel
    ? `Auto: ${defaultModel.displayName || defaultModel.model}`
    : models.length
      ? formatUiText('models.autoRuntimeAvailable', { count: models.length })
      : 'Model: auto/default';
  const datalistSpecs = [];
  const grouped = new Map();
  for (const model of models) {
    const effort = model.defaultReasoningEffort ? ` | effort ${model.defaultReasoningEffort}` : '';
    datalistSpecs.push({
      value: model.model,
      text: '',
      label: `${model.displayName || model.model}${model.isDefault ? ' | default' : ''}${effort}${model.description ? ` | ${model.description}` : ''}`,
      disabled: model.selectable === false,
    });

    const category = inferModelCategory(model);
    if (!grouped.has(category)) {
      grouped.set(category, []);
    }
    grouped.get(category).push(model);
  }
  const selectSpecs = [{ value: '', text: defaultLabel }];
  const storedCurrentModel = String(getComposerOptionsForSession(session).model || '').trim();
  const visibleCurrentModel = String(el('codex-model-input')?.value || '').trim();
  const currentModel = storedCurrentModel || visibleCurrentModel;
  const currentModelOption = currentModel
    ? allModels.find((model) => model.model === currentModel || model.id === currentModel)
    : null;
  if (currentModel && !modelIsSelectableCatalogMember(currentModelOption)) {
    const catalog = getSessionControlModelCatalog(session);
    const unavailable = currentModelOption?.selectable === false || modelCatalogIsAuthoritative(catalog);
    selectSpecs.push({
      label: 'Current selection',
      options: [{
        value: currentModel,
        text: `Current: ${currentModel}${unavailable ? ' | unavailable' : ' | not in loaded catalog'}`,
        disabled: unavailable,
      }],
    });
  }
  for (const [category, categoryModels] of grouped.entries()) {
    selectSpecs.push({
      label: category,
      options: categoryModels.map((model) => ({
        value: model.model,
        text: modelSelectLabel(model),
        disabled: model.selectable === false,
      })),
    });
  }
  syncOptionTree(datalist, datalistSpecs);
  syncSelectOptions(select, selectSpecs, select.value);
  syncModelSelectFromInput(session);
}

function supportedEffortValues(model) {
  if (model?.capabilityKnown !== true) {
    return [];
  }
  return (model.reasoningLevels || [])
    .map((effort) => String(effort || '').trim())
    .filter(Boolean);
}

function reasoningEffortLabel(value, locale = currentLocale()) {
  const effort = String(value || '').trim().toLowerCase();
  const labels = {
    en: {
      none: 'Off',
      minimal: 'Minimal',
      low: 'Low',
      medium: 'Medium',
      high: 'High',
      xhigh: 'Very high',
      max: 'Maximum',
      ultra: 'Ultra / automatic delegation',
    },
    'zh-CN': {
      none: '关闭',
      minimal: '最低',
      low: '轻度',
      medium: '中',
      high: '高',
      xhigh: '很高',
      max: '极高',
      ultra: '极致 / 自动委派',
    },
  };
  return labels[locale]?.[effort] || labels.en[effort] || effort;
}

function providerAllowsManualEffortWhenUnknown(session) {
  const providerKind = inferApiProviderKind(providerInputForModelCatalog(session));
  return providerCapabilitiesRegistry()?.getProviderPolicy?.(providerKind)?.allowManualEffortWhenUnknown === true;
}

function reasoningCapabilityForModel(session, modelId = '') {
  const selectedModel = findModelOption(session, modelId);
  if (selectedModel) {
    return selectedModel;
  }
  const capability = providerCapabilitiesRegistry()?.resolveModelCapability?.({
    providerKind: inferApiProviderKind(providerInputForModelCatalog(session)),
    modelId,
  });
  return capability ? normalizeModelOption({
    id: modelId || '__auto__',
    ...capability,
  }) : null;
}

function reasoningCapabilityForSelection(session) {
  return reasoningCapabilityForModel(session, el('codex-model-input')?.value.trim() || '');
}

function assertEffortSelectionIsValid(session, selection = {}) {
  const submitted = String(selection.effort || '').trim().toLowerCase();
  if (!submitted) {
    return;
  }
  if (!REASONING_EFFORT_PATTERN.test(submitted)) {
    throw sessionContractError(
      'session_effort_invalid',
      'Thinking effort must start with a letter and contain only lowercase letters, digits, underscores, or hyphens (maximum 32 characters).'
    );
  }
  const capability = reasoningCapabilityForModel(session, String(selection.model || '').trim());
  const supported = supportedEffortValues(capability);
  if (capability?.capabilityKnown === true && !supported.includes(submitted)) {
    throw sessionContractError(
      'session_effort_unsupported',
      `Thinking effort "${submitted}" is not supported by the selected model.`
    );
  }
  if (capability?.capabilityKnown !== true && !providerAllowsManualEffortWhenUnknown(session)) {
    throw sessionContractError(
      'session_effort_unsupported',
      'Manual effort values for unknown models are available only for Custom API providers.'
    );
  }
  if (capability?.capabilityKnown !== true && selection.allowUnverifiedEffort !== true) {
    throw sessionContractError(
      'session_effort_unverified',
      'Confirm "Allow unverified effort" before using a value that the current model metadata cannot verify.'
    );
  }
}

function renderManualEffortControlState(session) {
  const select = el('codex-effort-select');
  const manualInput = el('codex-effort-manual-input');
  const unverifiedRow = el('codex-effort-unverified-row');
  const manualControls = el('composer-manual-effort-controls');
  if (!select || !manualInput || !unverifiedRow) {
    return;
  }
  const manualMode = select.value === '__manual__';
  const capability = reasoningCapabilityForSelection(session);
  const requiresUnverified = manualMode
    && capability?.capabilityKnown !== true
    && providerAllowsManualEffortWhenUnknown(session);
  manualInput.classList.toggle('hidden', !manualMode);
  unverifiedRow.classList.toggle('hidden', !requiresUnverified);
  manualControls?.classList.toggle('hidden', !manualMode);
  if (!requiresUnverified) {
    el('codex-effort-unverified-checkbox').checked = false;
  }
}

function readEffortControlValue(session = getSelectedSession(), options = {}) {
  const selectValue = String(el('codex-effort-select')?.value || '');
  const manualMode = selectValue === '__manual__';
  const submitted = manualMode
    ? String(el('codex-effort-manual-input')?.value || '').trim().toLowerCase()
    : selectValue.trim().toLowerCase();
  const capability = reasoningCapabilityForSelection(session);
  const allowUnverifiedEffort = manualMode
    && capability?.capabilityKnown !== true
    && providerAllowsManualEffortWhenUnknown(session)
    && el('codex-effort-unverified-checkbox')?.checked === true;

  if (options.validate !== false) {
    assertEffortSelectionIsValid(session, {
      model: el('codex-model-input')?.value.trim() || '',
      effort: submitted,
      allowUnverifiedEffort,
    });
  }
  return {
    effort: submitted,
    effortMode: submitted ? 'manual' : 'auto',
    allowUnverifiedEffort: Boolean(submitted && allowUnverifiedEffort),
  };
}

function renderReasoningEffortOptions(session) {
  const select = el('codex-effort-select');
  if (!select) {
    return;
  }

  const stored = getComposerOptionsForSession(session);
  const current = stored.effort || (select.value === '__manual__' ? el('codex-effort-manual-input')?.value : select.value) || '';
  const selectedModel = findModelOption(session, el('codex-model-input')?.value.trim());
  const capability = selectedModel || reasoningCapabilityForSelection(session);
  const supported = capability ? supportedEffortValues(capability) : [];
  const options = supported.map((value) => ({ value, label: reasoningEffortLabel(value) }));

  const defaultLabel = selectedModel?.defaultReasoningEffort
    ? `Auto / model default (${reasoningEffortLabel(selectedModel.defaultReasoningEffort)})`
    : 'Auto / model default';
  const selectSpecs = [
    { value: '', text: defaultLabel },
    ...options.map((optionSpec) => ({ value: optionSpec.value, text: optionSpec.label })),
  ];
  if (capability?.capabilityKnown !== true && providerAllowsManualEffortWhenUnknown(session)) {
    selectSpecs.push({ value: '__manual__', text: 'Manual effort...' });
  }

  const supportedCurrent = options.some((optionSpec) => optionSpec.value === current);
  const manualUnknownAllowed = capability?.capabilityKnown !== true
    && providerAllowsManualEffortWhenUnknown(session);
  if (current && !supportedCurrent && !manualUnknownAllowed) {
    selectSpecs.push({
      value: current,
      text: `Current: ${reasoningEffortLabel(current)} | ${capability?.capabilityKnown === true ? 'unsupported' : 'unverified'}`,
      disabled: true,
    });
  }
  const nextValue = supportedCurrent
    ? current
    : current && manualUnknownAllowed
      ? '__manual__'
      : current || '';
  syncSelectOptions(select, selectSpecs, nextValue);
  if (el('codex-effort-manual-input')) {
    const manualValue = select.value === '__manual__' ? current : '';
    if (el('codex-effort-manual-input').value !== manualValue) {
      el('codex-effort-manual-input').value = manualValue;
    }
  }
  renderManualEffortControlState(session);
}

function modelCatalogIsAuthoritative(catalog) {
  return (catalog?.sources || []).some((source) => (
    source?.authority === 'authoritative'
    && source?.complete === true
    && source?.truncated !== true
    && !source?.nextCursor
    && source?.stale !== true
    && !source?.error
  ));
}

function assertModelSelectionIsSelectable(session, modelId) {
  const selectedModelId = String(modelId || '').trim();
  if (!selectedModelId) {
    return;
  }
  const model = findModelOption(session, selectedModelId);
  const catalog = getSessionControlModelCatalog(session);
  const authoritativeAbsence = !model && modelCatalogIsAuthoritative(catalog);
  if (authoritativeAbsence) {
    throw sessionContractError(
      'session_model_unavailable',
      `Model "${selectedModelId}" is not available for this Session.`,
      { sessionBinding: sessionApiBinding(session), canRebind: true }
    );
  }
  if (model?.selectable === false) {
    throw sessionContractError(
      model.availability === 'unavailable' ? 'session_model_unavailable' : 'session_model_unsupported',
      `Model "${selectedModelId}" is not available for this Session.`,
      { sessionBinding: sessionApiBinding(session), canRebind: true }
    );
  }
}

function normalizeComposerOptionValues(options = {}) {
  const effort = String(options.effort || '').trim().toLowerCase();
  const requestedEffortMode = String(options.effortMode || '').trim().toLowerCase();
  const effortMode = ['auto', 'manual'].includes(requestedEffortMode)
    ? requestedEffortMode
    : effort ? 'manual' : 'auto';
  return {
    ...DEFAULT_COMPOSER_OPTIONS,
    model: String(options.model || '').trim(),
    effort: effortMode === 'manual' ? effort : '',
    effortMode,
    allowUnverifiedEffort: effortMode === 'manual' && Boolean(effort) && options.allowUnverifiedEffort === true,
    summary: String(options.summary || '').trim(),
    mode: String(options.mode || '').trim() || DEFAULT_COMPOSER_OPTIONS.mode,
    approvalPolicy: typeof options.approvalPolicy === 'object'
      ? options.approvalPolicy
      : String(options.approvalPolicy || '').trim() || DEFAULT_COMPOSER_OPTIONS.approvalPolicy,
    approvalsReviewer: String(options.approvalsReviewer || '').trim() || DEFAULT_COMPOSER_OPTIONS.approvalsReviewer,
    sandboxMode: String(options.sandboxMode || '').trim() || DEFAULT_COMPOSER_OPTIONS.sandboxMode,
    personality: String(options.personality || '').trim(),
  };
}

function inferComposerOptionsFromText(text) {
  const source = String(text || '');
  const inferred = {};
  const effortMatch = source.match(/\b(?:effort|reasoning(?: effort)?)\s*[:=]\s*([a-z][a-z0-9_-]*)\b/i);
  if (effortMatch) {
    inferred.effort = effortMatch[1].toLowerCase();
  }
  const reviewerMatch = source.match(/\b(?:reviewer|approvalsReviewer|approvals reviewer)\s*[:=]\s*(auto[_-]?review|user)\b/i);
  if (reviewerMatch) {
    inferred.approvalsReviewer = reviewerMatch[1].replace('-', '_').toLowerCase();
  }
  return inferred;
}

function inferComposerOptionsFromSession(session) {
  if (!session) {
    return { ...DEFAULT_COMPOSER_OPTIONS };
  }
  const runtime = getRuntimeForSession(session) || session.runtime || {};
  const diagnostics = getDiagnosticsForSession(session);
  const latestTurnControl = [...diagnostics].reverse().find((entry) => (
    entry?.kind === 'control'
    && entry?.method === 'turn/start'
    && entry?.data
  ));
  const textInferred = inferComposerOptionsFromText([
    session.latestUserMessage,
    session.latestAgentMessage,
    ...(Array.isArray(session.transcriptPreview) ? session.transcriptPreview.map((entry) => entry.text) : []),
  ].filter(Boolean).join('\n'));
  return normalizeComposerOptionValues({
    ...textInferred,
    ...(session.codexOptions || {}),
    ...(latestTurnControl?.data || {}),
    model: runtime.model || latestTurnControl?.data?.model || session.codexOptions?.model || session.requestedSelection?.model || '',
    effort: runtime.effort || latestTurnControl?.data?.effort || session.codexOptions?.effort || session.requestedSelection?.effort || textInferred.effort || '',
    effortMode: runtime.effort || latestTurnControl?.data?.effort || session.codexOptions?.effort || session.requestedSelection?.effort || textInferred.effort
      ? 'manual'
      : 'auto',
    allowUnverifiedEffort: session.codexOptions?.allowUnverifiedEffort === true,
    summary: runtime.summary || latestTurnControl?.data?.summary || session.codexOptions?.summary || '',
    approvalPolicy: runtime.approvalPolicy || latestTurnControl?.data?.approvalPolicy || session.codexOptions?.approvalPolicy || '',
    approvalsReviewer: runtime.approvalsReviewer || latestTurnControl?.data?.approvalsReviewer || session.codexOptions?.approvalsReviewer || textInferred.approvalsReviewer || '',
    sandboxMode: runtime.sandboxMode || session.codexOptions?.sandboxMode || '',
    personality: runtime.personality || session.codexOptions?.personality || '',
  });
}

function getComposerOptionsForSession(session) {
  const key = resolveComposerSessionKey(getSessionKey(session));
  if (!key) {
    return { ...DEFAULT_COMPOSER_OPTIONS };
  }
  if (!state.codexControls.sessionOptionsByKey.has(key)) {
    state.codexControls.sessionOptionsByKey.set(key, inferComposerOptionsFromSession(session));
  }
  return state.codexControls.sessionOptionsByKey.get(key);
}

function refreshInferredComposerOptionsForSession(session) {
  const key = resolveComposerSessionKey(getSessionKey(session));
  if (!key || state.codexControls.persistedSessionOptionKeys.has(key)) {
    return;
  }
  state.codexControls.sessionOptionsByKey.set(key, inferComposerOptionsFromSession(session));
}

function persistComposerSessionOptions() {
  const serialized = {};
  for (const [key, value] of state.codexControls.sessionOptionsByKey.entries()) {
    if (!state.codexControls.persistedSessionOptionKeys.has(key)) {
      continue;
    }
    serialized[key] = normalizeComposerOptionValues(value);
  }
  writeLocalStorageJson(COMPOSER_SESSION_OPTIONS_STORAGE_KEY, serialized);
}

function setSelectIfAvailable(id, value) {
  const node = el(id);
  if (!node) {
    return;
  }
  const stringValue = String(value || '');
  const hasValue = Array.from(node.options || []).some((option) => option.value === stringValue);
  const nextValue = hasValue ? stringValue : '';
  if (node.value !== nextValue) {
    node.value = nextValue;
  }
}

function applyComposerOptionsToControls(session) {
  const options = getComposerOptionsForSession(session);
  const modelInput = el('codex-model-input');
  if (modelInput && modelInput.value !== (options.model || '')) {
    modelInput.value = options.model || '';
  }
  const effortSelect = el('codex-effort-select');
  const effortManual = el('codex-effort-manual-input');
  const effortUnverified = el('codex-effort-unverified-checkbox');
  if (effortSelect) {
    const hasSupportedValue = Array.from(effortSelect.options || []).some((option) => option.value === options.effort);
    const hasManualOption = Array.from(effortSelect.options || []).some((option) => option.value === '__manual__');
    const nextEffort = options.effortMode === 'manual' && options.effort && hasSupportedValue
      ? options.effort
      : options.effortMode === 'manual' && options.effort && hasManualOption
        ? '__manual__'
        : hasSupportedValue ? options.effort : '';
    if (effortSelect.value !== nextEffort) {
      effortSelect.value = nextEffort;
    }
  }
  if (effortManual) {
    const nextManualEffort = options.effortMode === 'manual' ? options.effort : '';
    if (effortManual.value !== nextManualEffort) {
      effortManual.value = nextManualEffort;
    }
  }
  if (effortUnverified && effortUnverified.checked !== (options.allowUnverifiedEffort === true)) {
    effortUnverified.checked = options.allowUnverifiedEffort === true;
  }
  renderManualEffortControlState(session);
  setSelectIfAvailable('codex-summary-select', options.summary);
  setSelectIfAvailable('codex-mode-select', options.mode);
  setSelectIfAvailable('codex-approval-policy-select', options.approvalPolicy);
  setSelectIfAvailable('codex-reviewer-select', options.approvalsReviewer);
  setSelectIfAvailable('codex-sandbox-mode-select', options.sandboxMode);
  setSelectIfAvailable('codex-personality-select', options.personality);
  syncModelSelectFromInput(session);
}

function readComposerOptionsFromControls(session = getSelectedSession()) {
  const effortSelection = readEffortControlValue(session, { validate: false });
  return normalizeComposerOptionValues({
    model: el('codex-model-input')?.value.trim() || '',
    effort: effortSelection.effort,
    effortMode: effortSelection.effortMode,
    allowUnverifiedEffort: effortSelection.allowUnverifiedEffort,
    summary: el('codex-summary-select')?.value || '',
    mode: el('codex-mode-select')?.value || 'default',
    approvalPolicy: el('codex-approval-policy-select')?.value || 'on-request',
    approvalsReviewer: el('codex-reviewer-select')?.value || '',
    sandboxMode: el('codex-sandbox-mode-select')?.value || 'workspaceWrite',
    personality: el('codex-personality-select')?.value || '',
  });
}

function saveComposerOptionsFromControls(session = getSelectedSession()) {
  const key = getSessionKey(session);
  if (!key) {
    return null;
  }
  const next = readComposerOptionsFromControls(session);
  state.codexControls.sessionOptionsByKey.set(key, next);
  state.codexControls.persistedSessionOptionKeys.add(key);
  persistComposerSessionOptions();
  return next;
}

function makeObjectPreviewUrl(file) {
  if (!file || !isImageFileRef(file) || !window.URL?.createObjectURL) {
    return '';
  }
  try {
    return window.URL.createObjectURL(file);
  } catch (_) {
    return '';
  }
}

function revokeComposerAttachmentPreview(attachment) {
  if (attachment?.previewObjectUrl && attachment.previewUrl && window.URL?.revokeObjectURL) {
    window.URL.revokeObjectURL(attachment.previewUrl);
  }
}

function getComposerAttachmentPreviewUrl(attachment) {
  if (!attachment) {
    return '';
  }
  if (attachment.type === 'image') {
    return attachment.url || '';
  }
  if (attachment.previewUrl && isImageFileRef(attachment)) {
    return attachment.previewUrl;
  }
  return '';
}

function openImagePreview({ src, title = 'Image preview', subtitle = '', downloadUrl = '' } = {}) {
  if (!src) {
    return;
  }
  state.imagePreview = {
    open: true,
    src,
    title,
    subtitle,
    downloadUrl: downloadUrl || src,
  };
  renderImagePreview();
}

function closeImagePreview() {
  state.imagePreview = {
    open: false,
    src: '',
    title: '',
    subtitle: '',
    downloadUrl: '',
  };
  renderImagePreview();
}

function renderImagePreview() {
  const overlay = el('image-preview-overlay');
  if (!overlay) {
    return;
  }
  const preview = state.imagePreview || {};
  const isOpen = Boolean(preview.open && preview.src);
  overlay.classList.toggle('hidden', !isOpen);
  overlay.setAttribute('aria-hidden', isOpen ? 'false' : 'true');

  const image = el('image-preview-img');
  if (image) {
    image.src = isOpen ? preview.src : '';
    image.alt = preview.title || 'Image preview';
  }
  const title = el('image-preview-title');
  if (title) {
    title.textContent = preview.title || 'Image preview';
  }
  const subtitle = el('image-preview-subtitle');
  if (subtitle) {
    subtitle.textContent = preview.subtitle || '';
  }
  const openLink = el('image-preview-open-link');
  if (openLink) {
    openLink.href = preview.src || '#';
    openLink.classList.toggle('hidden', !isOpen);
  }
  const saveLink = el('image-preview-save-link');
  if (saveLink) {
    saveLink.href = preview.downloadUrl || preview.src || '#';
    saveLink.download = preview.title || 'image';
    saveLink.classList.toggle('hidden', !isOpen);
  }
  syncModalBodyState();
}

function shouldMountTranscriptControlsGlobally() {
  return Boolean(window.matchMedia?.('(max-width: 980px), (pointer: coarse), (hover: none)').matches);
}

function ensureTranscriptScrollControlsMounted() {
  const controls = document.querySelector('.transcript-scroll-controls');
  const panel = document.querySelector('.transcript-panel');
  if (!controls || !panel) {
    return;
  }

  if (shouldMountTranscriptControlsGlobally()) {
    if (controls.parentElement !== document.body) {
      document.body.appendChild(controls);
    }
    return;
  }

  if (controls.parentElement !== panel) {
    panel.insertBefore(controls, panel.firstChild);
  }
}

function renderAttachmentChips() {
  const container = el('codex-attachment-chips');
  if (!container) {
    return;
  }

  container.innerHTML = '';
  for (const [index, attachment] of state.codexControls.attachments.entries()) {
    const chip = document.createElement('div');
    chip.className = `attachment-chip ${['uploadFile', 'textFile', 'skill', 'promptCard'].includes(attachment.type) ? 'file' : ''}`.trim();
    const previewUrl = getComposerAttachmentPreviewUrl(attachment);
    if (previewUrl) {
      chip.classList.add('image');
    }
    const label = attachment.remotePath
      ? 'Uploaded'
      : attachment.type === 'skill'
        ? 'Skill'
        : attachment.type === 'promptCard'
          ? 'Prompt'
          : attachment.type === 'image'
            ? 'Image'
            : 'File';
    const progress = typeof attachment.uploadProgress === 'number' && !attachment.remotePath
      ? ` uploading ${Math.round(Math.max(0, Math.min(1, attachment.uploadProgress)) * 100)}%`
      : '';
    const note = attachment.remotePath ? ` -> ${attachment.remotePath}` : progress;
    const text = attachment.type === 'skill'
      ? `${label}: ${attachment.displayName || attachment.name}${attachment.scope ? ` (${formatSkillScopeLabel(attachment.scope)})` : ''}`
      : attachment.type === 'promptCard'
        ? `${label}: ${attachment.title || 'Prompt card'}`
        : `${label}: ${attachment.name || 'attached file'}${attachment.size ? ` (${formatBytes(attachment.size)})` : ''}${note}`;
    if (previewUrl) {
      const previewButton = document.createElement('button');
      previewButton.type = 'button';
      previewButton.className = 'attachment-chip-preview';
      previewButton.title = 'Preview image';
      previewButton.innerHTML = `
        <img class="attachment-chip-thumbnail" src="${escapeHtml(previewUrl)}" alt="${escapeHtml(attachment.name || 'attached image')}" />
        <span>${escapeHtml(text)}</span>
      `;
      previewButton.onclick = (event) => {
        event.stopPropagation();
        openImagePreview({
          src: previewUrl,
          title: attachment.name || 'attached image',
          subtitle: attachment.size ? formatBytes(attachment.size) : 'Composer attachment',
          downloadUrl: previewUrl,
        });
      };
      chip.appendChild(previewButton);
    } else {
      const span = document.createElement('span');
      span.textContent = text;
      if (attachment.type === 'skill' && attachment.path) {
        span.title = attachment.path;
      }
      if (attachment.type === 'promptCard' && attachment.text) {
        span.title = attachment.text;
      }
      chip.appendChild(span);
    }
    const remove = document.createElement('button');
    remove.className = 'attachment-chip-remove';
    remove.type = 'button';
    remove.dataset.attachmentIndex = String(index);
    remove.setAttribute('aria-label', `Remove ${attachment.name || 'attachment'}`);
    remove.textContent = 'x';
    chip.appendChild(remove);
    container.appendChild(chip);
  }

  const localPath = el('codex-local-image-path')?.value.trim();
  if (localPath) {
    const chip = document.createElement('div');
    chip.className = 'attachment-chip muted';
    chip.innerHTML = `
      <span>Host image: ${escapeHtml(localPath)}</span>
      <button class="attachment-chip-remove" type="button" data-clear-local-image="true" aria-label="Remove host image path">x</button>
    `;
    container.appendChild(chip);
  }

  container.classList.toggle('hidden', container.childElementCount === 0);
  rememberMountedComposerDraft();
}

function isComposerPlanMode() {
  return (el('codex-mode-select')?.value || 'default') === 'plan';
}

function getComposerSubmission(session = getSelectedSession()) {
  const key = resolveComposerSessionKey(session);
  return key ? state.codexControls.composerSubmissionsBySession.get(key) || null : null;
}

function pruneComposerSubmissions() {
  const now = Date.now();
  for (const submission of state.codexControls.composerSubmissionsBySession.values()) {
    const startedAtMs = Date.parse(submission?.startedAt || '');
    if (!Number.isFinite(startedAtMs) || now - startedAtMs > COMPOSER_PENDING_SUBMISSION_TTL_MS) {
      submission.confirmationDelayed = true;
    }
  }
}

function isComposerSubmitting(session = getSelectedSession()) {
  pruneComposerSubmissions();
  return Boolean(getComposerSubmission(session));
}

function setComposerSubmission(submission, session = getSelectedSession()) {
  const key = resolveComposerSessionKey(submission?.sessionKey || session);
  if (key) {
    if (submission) {
      submission.sessionKey = key;
      state.codexControls.composerSubmissionsBySession.set(key, submission);
    } else {
      state.codexControls.composerSubmissionsBySession.delete(key);
    }
  }
  renderSessionDetails();
  renderComposerModeBanner();
  renderComposerTurnNotice();
}

function clearComposerSubmissionForSession(sessionOrKey, submissionId = '') {
  const key = resolveComposerSessionKey(sessionOrKey);
  if (!key) {
    return false;
  }
  const current = state.codexControls.composerSubmissionsBySession.get(key);
  if (submissionId && current?.id !== submissionId) {
    return false;
  }
  state.codexControls.composerSubmissionsBySession.delete(key);
  renderSessionDetails();
  renderComposerModeBanner();
  renderComposerTurnNotice();
  return true;
}

function pruneRecentComposerSubmissions() {
  const now = Date.now();
  for (const [key, entry] of state.codexControls.recentSubmissions.entries()) {
    if (!entry?.createdAtMs || now - entry.createdAtMs > COMPOSER_RECENT_SUBMISSION_TTL_MS) {
      state.codexControls.recentSubmissions.delete(key);
    }
  }
}

function composerSubmissionSignature(session, draft) {
  const attachmentKeys = (Array.isArray(draft?.attachments) ? draft.attachments : [])
    .map(composerAttachmentKey)
    .filter(Boolean)
    .sort();
  return JSON.stringify({
    sessionKey: resolveComposerSessionKey(getSessionKey(session) || ''),
    text: canonicalTranscriptText(draft?.text || ''),
    localImagePath: String(draft?.localImagePath || '').trim(),
    attachments: attachmentKeys,
    options: getComposerOptions(),
  });
}

function getOrCreateComposerSubmissionId(signature) {
  pruneRecentComposerSubmissions();
  const id = `composer-${makeClientId()}`;
  state.codexControls.recentSubmissions.set(signature, {
    id,
    createdAtMs: Date.now(),
  });
  return id;
}

function setComposerPlanMode(enabled) {
  setSelectValue('codex-mode-select', enabled ? 'plan' : 'default');
  renderComposerModeBanner();
}

function toggleComposerPlanMode() {
  setComposerPlanMode(!isComposerPlanMode());
}

function pressComposerPlanModeButton() {
  const button = el('codex-plan-button');
  if (button) {
    if (!button.disabled) {
      button.click();
    }
    return;
  }
  toggleComposerPlanMode();
  focusComposerInput();
}

function renderComposerModeBanner() {
  const banner = el('composer-plan-mode-banner');
  const sendButton = el('codex-send-button');
  const planButton = el('codex-plan-button');
  const session = getSelectedSession();
  const runtime = getRuntimeForSession(session) || session?.runtime || {};
  const activeTurn = Boolean(session?.live && runtimeIsActive(runtime));
  const planMode = isComposerPlanMode();
  const submitting = isComposerSubmitting(session);
  const submission = submitting ? getComposerSubmission(session) : null;
  const submissionLabel = submission?.stage === 'confirming'
    ? 'Confirming...'
    : submission?.stage === 'queued'
      ? 'Queued...'
    : submission?.stage === 'starting'
      ? 'Starting...'
      : 'Sending...';
  const submissionTitle = submission?.stage === 'confirming'
    ? 'The request may already be queued. Waiting for a matching Relay or Host confirmation.'
    : submission?.stage === 'queued'
      ? 'The Relay accepted this prompt. Waiting for the Host to start it.'
    : submission?.stage === 'starting'
      ? 'The Host is submitting this prompt to Codex.'
      : 'Sending this prompt to the Relay.';

  if (banner) {
    banner.classList.toggle('hidden', !planMode);
  }
  if (sendButton) {
    sendButton.textContent = submitting
      ? submissionLabel
      : planMode
      ? activeTurn ? 'Queue Plan' : 'Send Plan'
      : activeTurn ? 'Queue' : 'Send';
    sendButton.title = submitting
      ? submissionTitle
      : planMode
      ? 'Plan mode is on. Prompts will ask Codex to plan only until you exit plan mode.'
      : '';
  }
  if (planButton) {
    planButton.textContent = planMode ? 'Exit Plan' : 'Plan';
    planButton.title = planMode ? 'Exit plan mode' : 'Enter plan mode';
    planButton.setAttribute('aria-pressed', planMode ? 'true' : 'false');
  }
}

function renderComposerControls(session, disabled) {
  const submitting = isComposerSubmitting(session);
  const supportsTurnSelection = sessionSupportsTurnSelectionControls(session);
  refreshInferredComposerOptionsForSession(session);
  applyComposerOptionsToControls(session);
  renderComposerModelOptions(session);
  applyComposerOptionsToControls(session);
  renderReasoningEffortOptions(session);
  applyComposerOptionsToControls(session);
  renderAttachmentChips();
  renderComposerModeBanner();
  requestModelOptionsForSession(session);
  requestSkillOptionsForSession(session);
  renderComposerTurnNotice();

  const controlIds = [
    'codex-model-input',
    'codex-model-select',
    'codex-effort-select',
    'codex-effort-manual-input',
    'codex-effort-unverified-checkbox',
    'codex-summary-select',
    'codex-mode-select',
    'codex-approval-policy-select',
    'codex-reviewer-select',
    'codex-sandbox-mode-select',
    'codex-personality-select',
    'input-text',
    'codex-file-picker-button',
    'codex-image-files',
    'codex-local-image-path',
    'codex-clear-attachments-button',
    'codex-plan-button',
    'codex-goal-button',
    'composer-exit-plan-mode-button',
    'codex-send-button',
  ];
  for (const id of controlIds) {
    const node = el(id);
    if (node) {
      node.disabled = disabled || submitting;
    }
  }

  for (const id of [
    'codex-model-input',
    'codex-model-select',
    'codex-effort-select',
    'codex-effort-manual-input',
    'codex-effort-unverified-checkbox',
  ]) {
    const node = el(id);
    if (node) {
      node.disabled = disabled || submitting || !supportsTurnSelection;
    }
  }

  const modelButton = el('codex-model-refresh-button');
  if (modelButton) {
    const loadingModels = isModelOptionsLoading(session);
    const canRefresh = Boolean(
      supportsTurnSelection
      && session?.live
      && sessionApiBinding(session)?.bindingFingerprint
    );
    modelButton.disabled = disabled || submitting || !canRefresh || loadingModels;
    modelButton.textContent = loadingModels ? '\u2026' : '\u21bb';
    modelButton.title = canRefresh
      ? loadingModels ? 'Refreshing current Session models...' : 'Refresh current Session models.'
      : supportsTurnSelection
        ? 'Current model refresh requires a live Session with a verified API binding.'
        : 'This runtime does not support per-turn model selection.';
    modelButton.setAttribute('aria-busy', loadingModels ? 'true' : 'false');
  }

  const reviewButton = el('codex-review-button');
  if (reviewButton) {
    reviewButton.disabled = disabled || submitting || !session?.live;
  }

  const runtime = getRuntimeForSession(session) || session?.runtime || {};
  const activeTurn = Boolean(session?.live && runtimeIsActive(runtime));
  const interruptButton = el('codex-interrupt-button');
  if (interruptButton) {
    const interruptBusy = state.codexControls.interruptBusyKeys?.has(resolveComposerSessionKey(session));
    interruptButton.classList.toggle('hidden', !activeTurn);
    interruptButton.disabled = disabled || interruptBusy || !activeTurn;
  }
  const sendButton = el('codex-send-button');
  if (sendButton) {
    renderComposerModeBanner();
  }
  maybeScheduleQueuedPromptSend(session);
}

function getSelectedSteerQueue() {
  const selectedKey = getSessionKey(getSelectedSession());
  if (!selectedKey) {
    return [];
  }
  return state.codexControls.steerQueue.filter((item) => item.sessionKey === selectedKey);
}

function findSteerQueueItem(itemId) {
  return state.codexControls.steerQueue.find((item) => item.id === itemId) || null;
}

function getSteerQueueText(item) {
  return String(item?.text || item?.payload?.displayText || item?.payload?.composerDraft?.text || item?.payload?.text || '');
}

function setSteerQueueItemText(item, text) {
  if (!item) {
    return;
  }
  const previousPayload = item.payload || {};
  const previousDisplayText = String(previousPayload.displayText || item.text || previousPayload.composerDraft?.text || '');
  const previousPayloadText = String(previousPayload.text || '');
  const hasStructuredInputs = Boolean(
    previousPayload.inputItems?.length
    || previousPayload.uploadedFiles?.length
    || previousPayload.inlineFiles?.length
  );
  const nextText = String(text || '');
  item.text = nextText;
  item.updatedAt = new Date().toISOString();
  const nextPayload = {
    ...previousPayload,
    displayText: nextText,
  };
  if (!hasStructuredInputs && (!previousPayloadText || previousPayloadText === previousDisplayText)) {
    nextPayload.text = nextText;
  }
  item.payload = {
    ...nextPayload,
  };
  if (item.payload.composerDraft) {
    item.payload.composerDraft = {
      ...item.payload.composerDraft,
      text: nextText,
    };
  }
}

function addSteerQueueItem(session, payload, steerText) {
  const text = String(steerText || payload?.displayText || payload?.composerDraft?.text || '').trim();
  const item = {
    id: makeClientId(),
    sessionKey: getSessionKey(session),
    hostId: session.hostId,
    sessionId: session.sessionId,
    text,
    payload: {
      ...payload,
      displayText: payload?.displayText || text,
    },
    createdAt: new Date().toISOString(),
    sentAt: null,
    status: 'queued',
    sending: false,
    forceSending: false,
    error: '',
  };
  state.codexControls.steerQueue.push(item);
  return item;
}

function removeSteerQueueItem(itemId) {
  state.codexControls.steerQueue = state.codexControls.steerQueue.filter((item) => item.id !== itemId);
}

function clearSteerQueueForSession(session) {
  const key = getSessionKey(session);
  if (!key) {
    return;
  }
  state.codexControls.steerQueue = state.codexControls.steerQueue.filter((item) => item.sessionKey !== key);
}

function summarizeQueuedPayload(payload) {
  const pieces = [];
  const uploadedCount = Array.isArray(payload?.uploadedFiles) ? payload.uploadedFiles.length : 0;
  const itemCount = Array.isArray(payload?.inputItems) ? payload.inputItems.length : 0;
  if (uploadedCount) {
    pieces.push(`${uploadedCount} file${uploadedCount === 1 ? '' : 's'}`);
  }
  if (itemCount) {
    pieces.push(`${itemCount} input item${itemCount === 1 ? '' : 's'}`);
  }
  if (payload?.mode && payload.mode !== 'default') {
    pieces.push(payload.mode);
  }
  return pieces.join(' | ');
}

function getFirstQueuedPrompt(session = getSelectedSession()) {
  const sessionKey = getSessionKey(session);
  if (!sessionKey) {
    return null;
  }
  return state.codexControls.steerQueue.find((item) => (
    item.sessionKey === sessionKey
    && item.status === 'queued'
    && !item.sending
    && !item.forceSending
  )) || null;
}

function getQueueStatusLabel(item) {
  if (item.forceSending) {
    return 'interrupting';
  }
  if (item.sending) {
    return 'sending';
  }
  if (item.status === 'guided') {
    return 'guided';
  }
  if (item.status === 'failed') {
    return 'failed';
  }
  return 'waiting';
}

function renderComposerTurnNotice() {
  const notice = el('composer-turn-notice');
  if (!notice) {
    return;
  }
  const queue = getSelectedSteerQueue();
  const steerNotice = state.codexControls.steerNotice;
  const interruptOperation = getInterruptOperation(getSelectedSession());
  const show = Boolean(queue.length || steerNotice || interruptOperation);
  notice.classList.toggle('hidden', !show);
  if (!show) {
    return;
  }

  const title = el('composer-turn-notice-title');
  const copy = el('composer-turn-notice-copy');
  const forceButton = el('composer-force-send-button');
  const list = el('composer-steer-queue-list');
  if (queue.length) {
    const waitingCount = queue.filter((item) => item.status === 'queued').length;
    title.textContent = `Pending queue (${queue.length})`;
    copy.textContent = waitingCount
      ? 'These prompts are waiting in order. Edit or remove them, guide one into the current turn, or interrupt and send one immediately.'
      : 'These prompts were guided into the current turn. They stay visible so you can edit, remove, or force-send a fresh turn if needed.';
    forceButton.classList.remove('hidden');
    forceButton.disabled = queue.some((item) => item.forceSending);
    forceButton.textContent = 'Interrupt & Send First';
  } else {
    const interruptPresentation = interruptOperationPresentation(interruptOperation);
    title.textContent = interruptOperation
      ? interruptPresentation.title
      : steerNotice?.title || 'Active turn updated';
    copy.textContent = interruptOperation
      ? interruptPresentation.message
      : steerNotice?.message || 'Your message was added to the current Codex turn.';
    forceButton.classList.add('hidden');
    forceButton.disabled = true;
  }

  if (!list) {
    return;
  }
  list.innerHTML = '';
  list.classList.toggle('hidden', !queue.length);
  for (const [index, item] of queue.entries()) {
    const card = document.createElement('div');
    card.className = 'steer-queue-item';

    const header = document.createElement('div');
    header.className = 'steer-queue-item-header';

    const label = document.createElement('div');
    label.className = 'steer-queue-item-label';
    label.textContent = `#${index + 1} | ${getQueueStatusLabel(item)}`;
    header.appendChild(label);

    const meta = summarizeQueuedPayload(item.payload);
    if (meta) {
      const metaNode = document.createElement('div');
      metaNode.className = 'steer-queue-item-meta';
      metaNode.textContent = meta;
      header.appendChild(metaNode);
    }
    card.appendChild(header);

    const textarea = document.createElement('textarea');
    textarea.className = 'steer-queue-text';
    textarea.dataset.steerQueueText = item.id;
    textarea.rows = 3;
    textarea.value = getSteerQueueText(item);
    textarea.placeholder = 'Edit this waiting prompt before it is sent or guided...';
    card.appendChild(textarea);

    if (item.error) {
      const error = document.createElement('div');
      error.className = 'steer-queue-error';
      error.textContent = item.error;
      card.appendChild(error);
    }

    const actions = document.createElement('div');
    actions.className = 'steer-queue-actions';

    const force = document.createElement('button');
    force.type = 'button';
    force.className = 'secondary-button';
    force.dataset.forceSteerQueueId = item.id;
    force.disabled = item.forceSending || item.sending;
    force.textContent = item.forceSending ? 'Interrupting...' : 'Interrupt & Send';
    actions.appendChild(force);

    const guide = document.createElement('button');
    guide.type = 'button';
    guide.className = 'secondary-button';
    guide.dataset.guideSteerQueueId = item.id;
    guide.disabled = item.forceSending || item.sending || item.status === 'guided' || !runtimeIsActive(getRuntimeForSession(getSelectedSession()) || getSelectedSession()?.runtime || {});
    guide.textContent = item.status === 'guided' ? 'Guided' : 'Guide';
    actions.appendChild(guide);

    const remove = document.createElement('button');
    remove.type = 'button';
    remove.className = 'secondary-button';
    remove.dataset.removeSteerQueueId = item.id;
    remove.disabled = item.forceSending || item.sending;
    remove.textContent = 'Remove';
    actions.appendChild(remove);

    card.appendChild(actions);
    list.appendChild(card);
  }
}

function getComposerDraftAttachments(draft = null) {
  return Array.isArray(draft?.attachments) ? draft.attachments : state.codexControls.attachments;
}

function getComposerInputItems(uploadedFiles = [], draft = null) {
  const attachments = getComposerDraftAttachments(draft);
  const inputItems = attachments
    .filter((attachment) => attachment.type === 'image')
    .map((attachment) => ({
      type: 'image',
      url: attachment.url,
      name: attachment.name || 'image',
    }));
  for (const file of uploadedFiles.filter(isImageFileRef)) {
    if (!file.path) {
      continue;
    }
    inputItems.push({
      type: 'localImage',
      path: file.path,
      name: file.name || basename(file.path),
    });
  }
  const localImagePath = String(draft ? draft.localImagePath || '' : el('codex-local-image-path')?.value || '').trim();
  if (localImagePath) {
    inputItems.push({
      type: 'localImage',
      path: localImagePath,
      name: basename(localImagePath),
    });
  }
  for (const attachment of attachments.filter((item) => item.type === 'skill')) {
    if (!attachment.name || !attachment.path) {
      continue;
    }
    inputItems.push({
      type: 'skill',
      name: attachment.name,
      path: attachment.path,
    });
  }
  return inputItems;
}

function getDefaultTextForInputItems(inputItems = []) {
  const hasSkill = inputItems.some((item) => item.type === 'skill');
  if (hasSkill) {
    return 'Use the selected skill(s).';
  }
  const hasImage = inputItems.some((item) => item.type === 'image' || item.type === 'localImage');
  if (hasImage) {
    return 'Please inspect the attached image(s).';
  }
  return 'Please inspect the attached file(s).';
}

function buildComposerDisplayText(rawText, inputItems = [], uploadedFiles = [], draft = null) {
  const userVisibleText = String(rawText || '').trim();
  const attachments = getComposerDraftAttachments(draft);
  const summaries = [];

  const historyNames = attachments
    .filter((attachment) => attachment.source === 'historyImport')
    .map((attachment) => attachment.name || 'conversation history');
  if (historyNames.length) {
    summaries.push(`Attached history: ${historyNames.slice(0, 3).join(', ')}${historyNames.length > 3 ? ` and ${historyNames.length - 3} more` : ''}`);
  }

  const promptCards = attachments
    .filter((attachment) => attachment.type === 'promptCard')
    .map((attachment) => attachment.title || 'Prompt card');
  if (promptCards.length) {
    summaries.push(`Prompt card: ${promptCards.slice(0, 3).join(', ')}${promptCards.length > 3 ? ` and ${promptCards.length - 3} more` : ''}`);
  }

  const textFiles = attachments
    .filter((attachment) => attachment.type === 'textFile' && attachment.source !== 'historyImport')
    .map((attachment) => attachment.name || 'text file');
  if (textFiles.length) {
    summaries.push(`Attached text: ${textFiles.slice(0, 3).join(', ')}${textFiles.length > 3 ? ` and ${textFiles.length - 3} more` : ''}`);
  }

  const images = inputItems
    .filter((item) => item.type === 'image' || item.type === 'localImage')
    .map((item) => item.name || item.path || 'image');
  if (images.length) {
    summaries.push(`Attached image: ${images.slice(0, 3).join(', ')}${images.length > 3 ? ` and ${images.length - 3} more` : ''}`);
  }

  const skills = inputItems
    .filter((item) => item.type === 'skill')
    .map((item) => item.name || 'skill');
  if (skills.length) {
    summaries.push(`Skill: ${skills.slice(0, 3).join(', ')}${skills.length > 3 ? ` and ${skills.length - 3} more` : ''}`);
  }

  const uploads = uploadedFiles
    .map((file) => file.name || basename(file.path) || 'file');
  if (uploads.length) {
    summaries.push(`Uploaded file: ${uploads.slice(0, 3).join(', ')}${uploads.length > 3 ? ` and ${uploads.length - 3} more` : ''}`);
  }

  if (userVisibleText && summaries.length) {
    return [userVisibleText, ...summaries].join('\n\n');
  }
  if (userVisibleText) {
    return userVisibleText;
  }
  if (summaries.length) {
    return summaries.join('\n\n');
  }
  return inputItems.length ? getDefaultTextForInputItems(inputItems) : '';
}

function getComposerTextFileSections(draft = null) {
  return getComposerDraftAttachments(draft)
    .filter((attachment) => attachment.type === 'textFile')
    .map((attachment) => [
      `Attached file: ${attachment.name || 'untitled'}`,
      '```text',
      String(attachment.text || '').replace(/```/g, '` ` `'),
      '```',
    ].join('\n'));
}

function getComposerInlineFiles(draft = null) {
  return getComposerDraftAttachments(draft)
    .filter((attachment) => attachment.type === 'textFile')
    .map((attachment) => ({
      name: attachment.name || 'attachment.txt',
      size: Number(attachment.size || 0) || textByteLength(attachment.text || ''),
      mime: 'text/plain; charset=utf-8',
      text: String(attachment.text || ''),
    }))
    .filter((file) => file.text || file.name);
}

function getComposerPromptCardSections(draft = null) {
  return getComposerDraftAttachments(draft)
    .filter((attachment) => attachment.type === 'promptCard' && String(attachment.text || '').trim())
    .map((attachment) => [
      `Prompt card: ${attachment.title || 'Prompt card'}`,
      String(attachment.text || '').trim(),
    ].join('\n'));
}

function getComposerUploadedFileSections(uploadedFiles = []) {
  if (!uploadedFiles.length) {
    return [];
  }
  return [
    [
      'Files uploaded to the selected host:',
      ...uploadedFiles.map((file) => `- ${file.name || basename(file.path)}: ${file.path}${file.size ? ` (${formatBytes(file.size)})` : ''}`),
      '',
      'Use these remote host paths directly. For images, inspect the attached localImage items; for other files, open/read the paths as needed.',
    ].join('\n'),
  ];
}

function getComposerOptions() {
  const effortSelection = readEffortControlValue(getSelectedSession(), { validate: false });
  return {
    model: el('codex-model-input')?.value.trim() || null,
    effort: effortSelection.effort || null,
    effortMode: effortSelection.effortMode,
    allowUnverifiedEffort: effortSelection.allowUnverifiedEffort,
    summary: el('codex-summary-select')?.value || null,
    mode: el('codex-mode-select')?.value || 'default',
    approvalPolicy: el('codex-approval-policy-select')?.value || 'on-request',
    approvalsReviewer: el('codex-reviewer-select')?.value || 'auto_review',
    sandboxMode: el('codex-sandbox-mode-select')?.value || 'workspaceWrite',
    personality: el('codex-personality-select')?.value || null,
  };
}

function resolveComposerSessionKey(sessionOrKey) {
  let key = typeof sessionOrKey === 'string'
    ? String(sessionOrKey || '')
    : String(getSessionKey(sessionOrKey) || '');
  if (!key) return '';
  const aliases = state.codexControls.composerSessionKeyAliases;
  const seen = new Set();
  while (aliases.has(key) && !seen.has(key)) {
    seen.add(key);
    key = String(aliases.get(key) || key);
  }
  return key;
}

function findSessionForResolvedComposerKey(sessionOrKey, fallback = null) {
  const resolvedKey = resolveComposerSessionKey(sessionOrKey);
  if (!resolvedKey) return fallback;
  return state.sessions.find((candidate) => getSessionKey(candidate) === resolvedKey)
    || state.sessions.find((candidate) => (
      resolveComposerSessionKey(getSessionKey(candidate)) === resolvedKey
    ))
    || fallback;
}

function getMountedComposerSessionKey() {
  return resolveComposerSessionKey(
    state.codexControls.mountedComposerSessionKey || getSessionKey(getSelectedSession()) || ''
  );
}

function cloneComposerAttachment(attachment) {
  return {
    ...attachment,
  };
}

function cloneComposerDraft(draft = {}) {
  return {
    ...draft,
    text: String(draft.text || ''),
    localImagePath: String(draft.localImagePath || ''),
    attachments: Array.isArray(draft.attachments)
      ? draft.attachments.map(cloneComposerAttachment)
      : [],
  };
}

function composerDraftHasTemporaryContent(draft) {
  return Boolean(
    String(draft?.text || '')
    || String(draft?.localImagePath || '').trim()
    || (Array.isArray(draft?.attachments) && draft.attachments.length)
  );
}

function releaseComposerDraftResources(draft) {
  for (const attachment of Array.isArray(draft?.attachments) ? draft.attachments : []) {
    revokeComposerAttachmentPreview(attachment);
  }
}

function pruneComposerDrafts() {
  const drafts = state.codexControls.composerDraftsBySession;
  while (drafts.size > COMPOSER_DRAFT_SESSION_LIMIT) {
    const candidate = Array.from(drafts.keys())
      .find((key) => key !== state.codexControls.mountedComposerSessionKey);
    if (!candidate) break;
    const removed = drafts.get(candidate);
    drafts.delete(candidate);
    releaseComposerDraftResources(removed);
  }
}

function setComposerDraftForSessionKey(sessionKey, draft) {
  const key = resolveComposerSessionKey(sessionKey);
  if (!key) return null;
  const drafts = state.codexControls.composerDraftsBySession;
  if (!composerDraftHasTemporaryContent(draft)) {
    drafts.delete(key);
    return null;
  }
  const next = cloneComposerDraft(draft);
  drafts.delete(key);
  drafts.set(key, next);
  pruneComposerDrafts();
  return next;
}

function snapshotComposerDraft(rawText) {
  const input = el('input-text');
  return {
    text: String(rawText || ''),
    attachments: state.codexControls.attachments.map(cloneComposerAttachment),
    localImagePath: el('codex-local-image-path')?.value || '',
    options: getComposerOptions(),
    selectionStart: Number.isInteger(input?.selectionStart) ? input.selectionStart : null,
    selectionEnd: Number.isInteger(input?.selectionEnd) ? input.selectionEnd : null,
    createdAt: new Date().toISOString(),
  };
}

function getComposerDraftForSessionKey(sessionKey) {
  const key = resolveComposerSessionKey(sessionKey);
  if (!key) return cloneComposerDraft();
  if (getMountedComposerSessionKey() === key) {
    return snapshotComposerDraft(el('input-text')?.value || '');
  }
  return cloneComposerDraft(
    state.codexControls.pendingComposerDraftsBySession.get(key)
    || state.codexControls.composerDraftsBySession.get(key)
    || {}
  );
}

function appendComposerAttachmentsForSessionKey(sessionKey, attachments = []) {
  const key = resolveComposerSessionKey(sessionKey);
  const incoming = attachments.filter(Boolean).map(cloneComposerAttachment);
  if (!key || !incoming.length) return false;
  if (getMountedComposerSessionKey() === key) {
    state.codexControls.attachments.push(...incoming);
    renderAttachmentChips();
    return true;
  }
  const hadPending = state.codexControls.pendingComposerDraftsBySession.has(key);
  const draft = getComposerDraftForSessionKey(key);
  draft.attachments.push(...incoming);
  const saved = setComposerDraftForSessionKey(key, draft);
  if (hadPending && saved) {
    state.codexControls.pendingComposerDraftsBySession.set(key, cloneComposerDraft(saved));
  }
  return true;
}

function patchComposerAttachmentForSessionKey(sessionKey, attachmentIdentity, patch = {}) {
  const key = resolveComposerSessionKey(sessionKey);
  if (!key || !attachmentIdentity) return false;
  const applyPatch = (attachments) => {
    const attachment = attachments.find((candidate) => (
      composerAttachmentKey(candidate) === attachmentIdentity
      || candidate.fileId === attachmentIdentity
    ));
    if (!attachment) return false;
    Object.assign(attachment, patch);
    return true;
  };
  if (getMountedComposerSessionKey() === key) {
    if (!applyPatch(state.codexControls.attachments)) return false;
    renderAttachmentChips();
    return true;
  }
  const hadPending = state.codexControls.pendingComposerDraftsBySession.has(key);
  const draft = getComposerDraftForSessionKey(key);
  if (!applyPatch(draft.attachments)) return false;
  const saved = setComposerDraftForSessionKey(key, draft);
  if (hadPending && saved) {
    state.codexControls.pendingComposerDraftsBySession.set(key, cloneComposerDraft(saved));
  }
  return true;
}

function clearComposerDraftForSessionKey(sessionKey) {
  const key = resolveComposerSessionKey(sessionKey);
  if (!key) return false;
  if (getMountedComposerSessionKey() === key) {
    state.codexControls.mountingComposerDraft = true;
    try {
      for (const attachment of state.codexControls.attachments) {
        revokeComposerAttachmentPreview(attachment);
      }
      state.codexControls.attachments = [];
      const input = el('input-text');
      if (input) {
        input.value = '';
        input.selectionStart = 0;
        input.selectionEnd = 0;
      }
      const localImageInput = el('codex-local-image-path');
      if (localImageInput) localImageInput.value = '';
      const fileInput = el('codex-image-files');
      if (fileInput) fileInput.value = '';
      state.codexControls.composerDraftsBySession.delete(key);
      state.codexControls.pendingComposerDraftsBySession.delete(key);
      renderAttachmentChips();
    } finally {
      state.codexControls.mountingComposerDraft = false;
    }
    updateSlashMenuFromInput();
    return true;
  }
  const saved = state.codexControls.composerDraftsBySession.get(key);
  const pending = state.codexControls.pendingComposerDraftsBySession.get(key);
  if (saved) releaseComposerDraftResources(saved);
  if (pending && pending !== saved) releaseComposerDraftResources(pending);
  state.codexControls.composerDraftsBySession.delete(key);
  state.codexControls.pendingComposerDraftsBySession.delete(key);
  return true;
}

function rememberMountedComposerDraft() {
  if (state.codexControls.mountingComposerDraft) return null;
  const key = resolveComposerSessionKey(state.codexControls.mountedComposerSessionKey);
  if (!key) return null;
  return setComposerDraftForSessionKey(
    key,
    snapshotComposerDraft(el('input-text')?.value || '')
  );
}

function applyMountedComposerDraft(sessionKey, draft = null) {
  const key = resolveComposerSessionKey(sessionKey);
  const next = cloneComposerDraft(draft || {});
  const input = el('input-text');
  const localImageInput = el('codex-local-image-path');
  state.codexControls.mountingComposerDraft = true;
  state.codexControls.mountedComposerSessionKey = key;
  try {
    state.codexControls.attachments = next.attachments;
    if (input) {
      input.value = next.text;
      const maximum = input.value.length;
      const selectionStart = Number.isInteger(next.selectionStart)
        ? Math.max(0, Math.min(maximum, next.selectionStart))
        : maximum;
      const selectionEnd = Number.isInteger(next.selectionEnd)
        ? Math.max(selectionStart, Math.min(maximum, next.selectionEnd))
        : selectionStart;
      input.selectionStart = selectionStart;
      input.selectionEnd = selectionEnd;
    }
    if (localImageInput) localImageInput.value = next.localImagePath;
    renderAttachmentChips();
  } finally {
    state.codexControls.mountingComposerDraft = false;
  }
  updateSlashMenuFromInput();
  return next;
}

function syncMountedComposerDraftSession(session = getSelectedSession()) {
  const nextKey = resolveComposerSessionKey(getSessionKey(session) || '');
  const previousKey = resolveComposerSessionKey(state.codexControls.mountedComposerSessionKey);
  if (nextKey === previousKey) return false;
  if (!previousKey && nextKey) {
    const browserRestoredDraft = snapshotComposerDraft(el('input-text')?.value || '');
    if (composerDraftHasTemporaryContent(browserRestoredDraft)) {
      state.codexControls.mountedComposerSessionKey = nextKey;
      setComposerDraftForSessionKey(nextKey, browserRestoredDraft);
      return true;
    }
  }
  rememberMountedComposerDraft();
  const pending = nextKey
    ? state.codexControls.pendingComposerDraftsBySession.get(nextKey) || null
    : null;
  const saved = nextKey
    ? pending || state.codexControls.composerDraftsBySession.get(nextKey) || null
    : null;
  applyMountedComposerDraft(nextKey, saved);
  if (pending) {
    state.codexControls.pendingComposerDraftsBySession.delete(nextKey);
    setComposerDraftForSessionKey(nextKey, pending);
  }
  return true;
}

function moveComposerDraftSessionKey(previousKeyValue, nextKeyValue) {
  const rawPreviousKey = String(previousKeyValue || '');
  const rawNextKey = String(nextKeyValue || '');
  const previousKey = resolveComposerSessionKey(rawPreviousKey);
  const nextKey = resolveComposerSessionKey(rawNextKey);
  if (!previousKey || !nextKey || previousKey === nextKey) return false;
  if (resolveComposerSessionKey(state.codexControls.mountedComposerSessionKey) === previousKey) {
    rememberMountedComposerDraft();
    state.codexControls.mountedComposerSessionKey = nextKey;
  }
  const aliases = state.codexControls.composerSessionKeyAliases;
  for (const [alias, target] of aliases) {
    if (target === previousKey) aliases.set(alias, nextKey);
  }
  aliases.set(rawPreviousKey, nextKey);
  aliases.set(previousKey, nextKey);
  while (aliases.size > COMPOSER_DRAFT_SESSION_LIMIT * 4) {
    aliases.delete(aliases.keys().next().value);
  }
  for (const drafts of [
    state.codexControls.composerDraftsBySession,
    state.codexControls.pendingComposerDraftsBySession,
    state.codexControls.activeDraftsBySession,
    state.codexControls.sentDraftSnapshotsBySession,
  ]) {
    if (!drafts.has(previousKey)) continue;
    const draft = drafts.get(previousKey);
    drafts.delete(previousKey);
    drafts.set(nextKey, draft);
  }
  if (!(state.transcriptTombstones instanceof Map)) state.transcriptTombstones = new Map();
  const previousTranscriptTombstones = state.transcriptTombstones.get(previousKey) || null;
  if (previousTranscriptTombstones) {
    const nextTranscriptTombstones = state.transcriptTombstones.get(nextKey) || new Map();
    for (const [requestId, removedAt] of previousTranscriptTombstones.entries()) {
      nextTranscriptTombstones.set(
        requestId,
        Math.max(Number(nextTranscriptTombstones.get(requestId) || 0), Number(removedAt || 0))
      );
    }
    state.transcriptTombstones.delete(previousKey);
    state.transcriptTombstones.set(nextKey, nextTranscriptTombstones);
    pruneTranscriptTombstones(nextKey);
  }
  const submission = state.codexControls.composerSubmissionsBySession.get(previousKey) || null;
  if (submission) {
    state.codexControls.composerSubmissionsBySession.delete(previousKey);
    submission.sessionKey = nextKey;
    state.codexControls.composerSubmissionsBySession.set(nextKey, submission);
  }
  for (const [signature, recent] of Array.from(state.codexControls.recentSubmissions.entries())) {
    let parsed = null;
    try {
      parsed = JSON.parse(signature);
    } catch (_) {
      continue;
    }
    if (![rawPreviousKey, previousKey].includes(String(parsed?.sessionKey || ''))) continue;
    const nextSignature = JSON.stringify({ ...parsed, sessionKey: nextKey });
    const existingRecent = state.codexControls.recentSubmissions.get(nextSignature);
    state.codexControls.recentSubmissions.delete(signature);
    state.codexControls.recentSubmissions.set(nextSignature, existingRecent || recent);
    if (submission?.signature === signature) submission.signature = nextSignature;
  }
  const moveMapEntry = (map) => {
    if (!map || typeof map.has !== 'function' || !map.has(previousKey)) return false;
    const value = map.get(previousKey);
    map.delete(previousKey);
    map.set(nextKey, value);
    return true;
  };
  const moveSetEntry = (set) => {
    if (!set || typeof set.has !== 'function' || !set.has(previousKey)) return false;
    set.delete(previousKey);
    set.add(nextKey);
    return true;
  };
  const movedSessionOptions = moveMapEntry(state.codexControls.sessionOptionsByKey);
  moveSetEntry(state.codexControls.persistedSessionOptionKeys);
  moveMapEntry(state.codexControls.apiSwitchNoticesBySession);
  moveMapEntry(state.codexControls.interruptOperationsBySession);
  moveSetEntry(state.codexControls.interruptBusyKeys);
  moveSetEntry(state.sessionApiRebindBusyKeys);
  moveSetEntry(state.sessionTranscriptFallbackBusyKeys);
  moveMapEntry(state.sessionRebindFailures);
  if (movedSessionOptions && typeof persistComposerSessionOptions === 'function') {
    persistComposerSessionOptions();
  }
  return true;
}

function pruneSentDraftSnapshots() {
  const snapshots = state.codexControls.sentDraftSnapshotsBySession;
  const cutoff = Date.now() - SENT_DRAFT_SNAPSHOT_TTL_MS;
  for (const [key, snapshot] of snapshots.entries()) {
    const sentAtMs = Date.parse(snapshot?.sentAt || '');
    if (!Number.isFinite(sentAtMs) || sentAtMs < cutoff) snapshots.delete(key);
  }
  while (snapshots.size > SENT_DRAFT_SNAPSHOT_LIMIT) {
    snapshots.delete(snapshots.keys().next().value);
  }
}

function setSentDraftSnapshotForSessionKey(sessionKey, payload) {
  const key = resolveComposerSessionKey(sessionKey);
  const draft = payload?.composerDraft;
  if (!key || !draft) return null;
  const snapshot = {
    ...cloneComposerDraft(draft),
    text: String(draft.text || payload.displayText || payload.text || ''),
    clientRequestId: String(payload.clientRequestId || '').trim() || null,
    submissionSignature: String(payload.submissionSignature || '').trim() || null,
    sentAt: new Date().toISOString(),
    restoreOnInterruptRequestId: null,
  };
  const snapshots = state.codexControls.sentDraftSnapshotsBySession;
  snapshots.delete(key);
  snapshots.set(key, snapshot);
  pruneSentDraftSnapshots();
  return snapshot;
}

function getSentDraftSnapshotForSession(sessionOrKey) {
  pruneSentDraftSnapshots();
  const key = resolveComposerSessionKey(sessionOrKey);
  return key ? state.codexControls.sentDraftSnapshotsBySession.get(key) || null : null;
}

function markSentDraftSnapshotForInterrupt(sessionOrKey, interruptRequestId, clientRequestId = '') {
  const snapshot = getSentDraftSnapshotForSession(sessionOrKey);
  const expectedClientRequestId = String(clientRequestId || '').trim();
  if (!snapshot || (expectedClientRequestId && snapshot.clientRequestId !== expectedClientRequestId)) return false;
  snapshot.restoreOnInterruptRequestId = String(interruptRequestId || '').trim() || null;
  return Boolean(snapshot.restoreOnInterruptRequestId);
}

function clearSentDraftSnapshotInterruptMarker(sessionOrKey, interruptRequestId = '') {
  const snapshot = getSentDraftSnapshotForSession(sessionOrKey);
  const expected = String(interruptRequestId || '').trim();
  if (!snapshot || (expected && snapshot.restoreOnInterruptRequestId !== expected)) return false;
  snapshot.restoreOnInterruptRequestId = null;
  return true;
}

function clearSentDraftSnapshotForSessionRequest(sessionOrKey, clientRequestId = '', options = {}) {
  const key = resolveComposerSessionKey(sessionOrKey);
  const snapshot = key ? state.codexControls.sentDraftSnapshotsBySession.get(key) || null : null;
  const expected = String(clientRequestId || '').trim();
  if (!key || !snapshot || (expected && snapshot.clientRequestId !== expected)) return false;
  if (snapshot.restoreOnInterruptRequestId && options.force !== true) return false;
  state.codexControls.sentDraftSnapshotsBySession.delete(key);
  return true;
}

function setActiveDraftForSessionKey(sessionKey, payload) {
  const key = resolveComposerSessionKey(sessionKey);
  const draft = payload?.composerDraft;
  if (!key || !draft) {
    return;
  }
  const activeDraft = {
    ...draft,
    text: String(draft.text || payload.displayText || payload.text || ''),
    clientRequestId: String(payload.clientRequestId || '').trim() || null,
    submissionSignature: String(payload.submissionSignature || '').trim() || null,
  };
  state.codexControls.activeDraftsBySession.set(key, activeDraft);
  setSentDraftSnapshotForSessionKey(key, {
    ...payload,
    composerDraft: activeDraft,
  });
}

function setActiveDraftForSession(session, payload) {
  setActiveDraftForSessionKey(resolveComposerSessionKey(session), payload);
}

function clearActiveDraftForSession(session) {
  const key = resolveComposerSessionKey(session);
  if (key) {
    state.codexControls.activeDraftsBySession.delete(key);
  }
}

function clearActiveDraftForSessionRequest(session, clientRequestId = '') {
  const key = resolveComposerSessionKey(session);
  const expected = String(clientRequestId || '').trim();
  const activeDraft = key ? state.codexControls.activeDraftsBySession.get(key) || null : null;
  if (!key || !expected || activeDraft?.clientRequestId !== expected) return false;
  state.codexControls.activeDraftsBySession.delete(key);
  return true;
}

function composerDraftContentIdentity(draft = {}) {
  return JSON.stringify({
    text: String(draft.text || ''),
    localImagePath: String(draft.localImagePath || '').trim(),
    attachments: (Array.isArray(draft.attachments) ? draft.attachments : [])
      .map(composerAttachmentKey)
      .filter(Boolean)
      .sort(),
  });
}

function clearComposerDraftIfMatching(sessionOrKey, expectedDraft) {
  const key = resolveComposerSessionKey(sessionOrKey);
  if (!key || !expectedDraft) return false;
  const currentDraft = getComposerDraftForSessionKey(key);
  if (composerDraftContentIdentity(currentDraft) !== composerDraftContentIdentity(expectedDraft)) {
    return false;
  }
  return clearComposerDraftForSessionKey(key);
}

function acknowledgeComposerSubmissionForSession(sessionOrKey, clientRequestId = '', options = {}) {
  const key = resolveComposerSessionKey(sessionOrKey);
  const expectedRequestId = String(clientRequestId || '').trim();
  if (!key || !expectedRequestId) return false;
  const submission = state.codexControls.composerSubmissionsBySession.get(key) || null;
  const activeDraft = state.codexControls.activeDraftsBySession.get(key) || null;
  const submissionMatches = submission?.id === expectedRequestId;
  const activeDraftMatches = activeDraft?.clientRequestId === expectedRequestId;
  if (!submissionMatches && !activeDraftMatches) return false;

  const retainedDraft = activeDraftMatches ? activeDraft : submission?.draft || null;
  if (!activeDraftMatches && retainedDraft) {
    setActiveDraftForSessionKey(key, {
      clientRequestId: expectedRequestId,
      submissionSignature: submission?.signature || '',
      composerDraft: retainedDraft,
      displayText: retainedDraft.text,
    });
  }
  clearComposerDraftIfMatching(key, retainedDraft);

  if (options.turnActive === true) {
    clearActiveDraftForSessionRequest(key, expectedRequestId);
    completeComposerSubmissionForSession(key, expectedRequestId);
    return true;
  }

  if (submissionMatches) {
    submission.stage = options.stage || submission.stage || 'queued';
    submission.acceptedAt ||= new Date().toISOString();
    submission.confirmationDelayed = false;
    setComposerSubmission(submission, key);
  }
  return true;
}

function stashPendingComposerDraftForSession(sessionOrKey, draft) {
  const key = resolveComposerSessionKey(sessionOrKey);
  if (!key || !draft) {
    return;
  }
  state.codexControls.pendingComposerDraftsBySession.set(key, {
    ...draft,
    text: String(draft.text || ''),
  });
}

function restoreComposerDraft(draft, options = {}) {
  if (!draft) {
    return false;
  }
  const input = el('input-text');
  if (input) {
    const draftText = String(options.textOverride ?? draft.text ?? '');
    if (options.replace || !input.value.trim()) {
      input.value = draftText;
    } else if (draftText) {
      input.value = `${input.value.trimEnd()}\n\n${draftText}`;
    }
    const maximum = input.value.length;
    const restoreSavedSelection = options.replace || input.value === draftText;
    const selectionStart = restoreSavedSelection && Number.isInteger(draft.selectionStart)
      ? Math.max(0, Math.min(maximum, draft.selectionStart))
      : maximum;
    const selectionEnd = restoreSavedSelection && Number.isInteger(draft.selectionEnd)
      ? Math.max(selectionStart, Math.min(maximum, draft.selectionEnd))
      : selectionStart;
    input.selectionStart = selectionStart;
    input.selectionEnd = selectionEnd;
    input.dispatchEvent(new Event('input', { bubbles: true }));
  }

  const nextAttachments = Array.isArray(draft.attachments)
    ? draft.attachments.map(cloneComposerAttachment)
    : [];
  if (options.replace) {
    for (const attachment of state.codexControls.attachments) {
      revokeComposerAttachmentPreview(attachment);
    }
    state.codexControls.attachments = [];
  }
  if (nextAttachments.length) {
    const existingKeys = new Set(state.codexControls.attachments.map(composerAttachmentKey));
    for (const attachment of nextAttachments) {
      if (attachment.type === 'uploadFile' && attachment.fileObject && isImageFileRef(attachment) && (attachment.previewObjectUrl || !attachment.previewUrl)) {
        attachment.previewUrl = makeObjectPreviewUrl(attachment.fileObject);
        attachment.previewObjectUrl = Boolean(attachment.previewUrl);
      }
      const key = composerAttachmentKey(attachment);
      if (!existingKeys.has(key)) {
        state.codexControls.attachments.push(attachment);
        existingKeys.add(key);
      }
    }
  }

  const localImageInput = el('codex-local-image-path');
  if (localImageInput && (options.replace || (draft.localImagePath && !localImageInput.value.trim()))) {
    localImageInput.value = String(draft.localImagePath || '');
    localImageInput.dispatchEvent(new Event('input', { bubbles: true }));
  }
  renderAttachmentChips();
  return true;
}

function restorePendingComposerDraftForSession(session) {
  const key = resolveComposerSessionKey(session);
  if (!key) {
    return false;
  }
  const draft = state.codexControls.pendingComposerDraftsBySession.get(key);
  if (!draft) {
    return false;
  }
  const input = el('input-text');
  if (input?.value.trim() || state.codexControls.attachments.length || el('codex-local-image-path')?.value.trim()) {
    return false;
  }
  if (!restoreComposerDraft(draft, { replace: true })) {
    return false;
  }
  state.codexControls.pendingComposerDraftsBySession.delete(key);
  return true;
}

function mergeComposerDraftsForRestore(existingDraft, restoredDraft) {
  const existing = cloneComposerDraft(existingDraft || {});
  const restored = cloneComposerDraft(restoredDraft || {});
  if (!composerDraftHasTemporaryContent(existing)) return restored;
  const existingText = String(existing.text || '');
  const restoredText = String(restored.text || '');
  const attachments = [];
  const attachmentKeys = new Set();
  for (const attachment of [...existing.attachments, ...restored.attachments]) {
    const attachmentKey = composerAttachmentKey(attachment);
    if (!attachmentKey || attachmentKeys.has(attachmentKey)) continue;
    attachmentKeys.add(attachmentKey);
    attachments.push(cloneComposerAttachment(attachment));
  }
  return {
    ...restored,
    ...existing,
    text: existingText && restoredText
      ? `${existingText.trimEnd()}\n\n${restoredText}`
      : existingText || restoredText,
    attachments,
    localImagePath: existing.localImagePath || restored.localImagePath || '',
    selectionStart: null,
    selectionEnd: null,
  };
}

function restoreSentDraftSnapshotForSession(sessionOrKey, clientRequestId = '') {
  const key = resolveComposerSessionKey(sessionOrKey);
  const snapshot = getSentDraftSnapshotForSession(key);
  const expected = String(clientRequestId || '').trim();
  if (!key || !snapshot || (expected && snapshot.clientRequestId !== expected)) return false;
  const selectedKey = resolveComposerSessionKey(getSessionKey(getSelectedSession()) || '');
  if (selectedKey === key) {
    if (!restoreComposerDraft(snapshot, { replace: false })) return false;
    rememberMountedComposerDraft();
  } else {
    const mergedDraft = mergeComposerDraftsForRestore(getComposerDraftForSessionKey(key), snapshot);
    setComposerDraftForSessionKey(key, mergedDraft);
    stashPendingComposerDraftForSession(key, mergedDraft);
  }
  state.codexControls.sentDraftSnapshotsBySession.delete(key);
  return true;
}

function restoreActiveDraftForSession(session) {
  const key = resolveComposerSessionKey(session);
  if (!key) {
    return false;
  }
  const draft = state.codexControls.activeDraftsBySession.get(key);
  if (!restoreComposerDraft(draft, { replace: false })) {
    return false;
  }
  state.codexControls.activeDraftsBySession.delete(key);
  return true;
}

function completeComposerSubmissionForSession(sessionOrKey, submissionId = '') {
  const submission = getComposerSubmission(sessionOrKey);
  if (submissionId && submission?.id !== submissionId) return false;
  if (submission?.signature) {
    state.codexControls.recentSubmissions.delete(submission.signature);
  }
  return clearComposerSubmissionForSession(sessionOrKey, submissionId);
}

function recoverComposerSubmissionForSession(sessionOrKey, options = {}) {
  const key = resolveComposerSessionKey(sessionOrKey);
  if (!key) return false;
  const submission = state.codexControls.composerSubmissionsBySession.get(key) || null;
  const activeDraft = state.codexControls.activeDraftsBySession.get(key) || null;
  const sentDraft = state.codexControls.sentDraftSnapshotsBySession.get(key) || null;
  const expectedRequestId = String(options.clientRequestId || '').trim();
  const retainedRequestId = String(
    submission?.id || activeDraft?.clientRequestId || sentDraft?.clientRequestId || ''
  ).trim();
  if (retainedRequestId && !expectedRequestId) {
    return false;
  }
  if (expectedRequestId && retainedRequestId && expectedRequestId !== retainedRequestId) {
    return false;
  }
  const draft = activeDraft || submission?.draft || sentDraft || null;
  if (!draft) {
    clearComposerSubmissionForSession(key, expectedRequestId);
    return false;
  }

  const selectedKey = resolveComposerSessionKey(getSessionKey(getSelectedSession()) || '');
  if (selectedKey === key) {
    restoreComposerDraft(draft, { replace: false });
    rememberMountedComposerDraft();
  } else {
    const mergedDraft = mergeComposerDraftsForRestore(getComposerDraftForSessionKey(key), draft);
    setComposerDraftForSessionKey(key, mergedDraft);
    stashPendingComposerDraftForSession(key, mergedDraft);
  }
  const submissionSignature = String(
    submission?.signature || activeDraft?.submissionSignature || ''
  ).trim();
  if (submissionSignature) {
    state.codexControls.recentSubmissions.delete(submissionSignature);
  }
  state.codexControls.activeDraftsBySession.delete(key);
  state.codexControls.sentDraftSnapshotsBySession.delete(key);
  clearComposerSubmissionForSession(key, retainedRequestId || expectedRequestId);
  return true;
}

